class GovernanceError(RuntimeError):
    """A fail-closed governance validation error."""

    def __init__(self, message: str, *, state: str = "BLOCKED_EVIDENCE") -> None:
        super().__init__(message)
        self.state = state


def fail(message: str, *, state: str = "BLOCKED_EVIDENCE") -> NoReturn:
    raise GovernanceError(message, state=state)


def require(condition: bool, message: str, *, state: str = "BLOCKED_EVIDENCE") -> None:
    if not condition:
        fail(message, state=state)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    require(path.is_file() and not path.is_symlink(), f"not a regular file: {path}")
    return sha256_bytes(path.read_bytes())


def decode_canonical_base64url_nopad(value: Any, label: str) -> bytes:
    """Decode one canonical RFC 4648 base64url value without padding."""

    require(
        isinstance(value, str)
        and value
        and len(value) <= 1024
        and "=" not in value
        and re.fullmatch(r"[A-Za-z0-9_-]+", value) is not None,
        f"{label} is not unpadded base64url",
    )
    try:
        decoded = base64.b64decode(
            value + "=" * ((-len(value)) % 4),
            altchars=b"-_",
            validate=True,
        )
    except (ValueError, binascii.Error):
        fail(f"{label} base64url decoding failed")
    require(
        base64.urlsafe_b64encode(decoded).rstrip(b"=").decode("ascii") == value,
        f"{label} is not the canonical base64url encoding",
    )
    return decoded


def canonical_rsa_pss_public_numbers(
    modulus_b64url: Any,
    exponent_b64url: Any,
    label: str,
) -> tuple[int, int, int]:
    """Load the closed RSA-3072/4096 public-key form used by M00 exports."""

    modulus_bytes = decode_canonical_base64url_nopad(
        modulus_b64url, f"{label} modulus",
    )
    exponent_bytes = decode_canonical_base64url_nopad(
        exponent_b64url, f"{label} exponent",
    )
    require(
        len(modulus_bytes) in {384, 512}
        and modulus_bytes[0] & 0x80
        and modulus_bytes[-1] & 1,
        f"{label} modulus is not canonical RSA-3072/4096",
    )
    require(
        exponent_bytes == b"\x01\x00\x01",
        f"{label} exponent is not the canonical 65537 encoding",
    )
    modulus = int.from_bytes(modulus_bytes, "big")
    exponent = int.from_bytes(exponent_bytes, "big")
    require(
        modulus.bit_length() in {3072, 4096},
        f"{label} modulus bit length drift",
    )
    return modulus, exponent, len(modulus_bytes)


def canonical_rsa_pss_public_numbers_hex(
    modulus_hex: Any,
    public_exponent: Any,
    label: str,
) -> tuple[int, int, int]:
    """Load the schema's strict lowercase-hex RSA public-key projection."""

    require(
        isinstance(modulus_hex, str)
        and len(modulus_hex) in {768, 1024}
        and len(modulus_hex) % 2 == 0
        and re.fullmatch(r"[0-9a-f]+", modulus_hex) is not None,
        f"{label} modulus is not strict lowercase even-length RSA-3072/4096 hex",
    )
    require(
        isinstance(public_exponent, int)
        and not isinstance(public_exponent, bool)
        and public_exponent == 65537,
        f"{label} exponent is not the canonical integer 65537",
    )
    modulus_bytes = bytes.fromhex(modulus_hex)
    require(
        modulus_bytes[0] & 0x80
        and modulus_bytes[-1] & 1,
        f"{label} modulus is not canonical RSA-3072/4096",
    )
    modulus = int.from_bytes(modulus_bytes, "big")
    require(
        modulus.bit_length() in {3072, 4096},
        f"{label} modulus bit length drift",
    )
    return modulus, public_exponent, len(modulus_bytes)


def mgf1_sha256(seed: bytes, length: int) -> bytes:
    require(
        isinstance(seed, bytes)
        and exact_nonnegative_int(length)
        and length <= 512,
        "MGF1-SHA256 input bound invalid",
    )
    result = bytearray()
    counter = 0
    while len(result) < length:
        result.extend(hashlib.sha256(seed + counter.to_bytes(4, "big")).digest())
        counter += 1
    return bytes(result[:length])


def verify_rsa_pss_sha256_signature(
    message: bytes,
    signature_b64url: Any,
    modulus_b64url: Any,
    exponent_b64url: Any,
    label: str,
) -> bool:
    """Verify RSA-PSS SHA-256/MGF1-SHA256 with an exact 32-byte salt.

    Malformed encodings and noncanonical keys are evidence errors. A
    canonical, correctly sized but cryptographically invalid signature simply
    returns false so a caller can derive its typed FAIL branch.
    """

    require(isinstance(message, bytes), f"{label} signed message is not bytes")
    modulus, exponent, modulus_length = canonical_rsa_pss_public_numbers(
        modulus_b64url, exponent_b64url, label,
    )
    signature = decode_canonical_base64url_nopad(
        signature_b64url, f"{label} signature",
    )
    require(
        len(signature) == modulus_length,
        f"{label} signature length does not match its RSA modulus",
    )
    signature_integer = int.from_bytes(signature, "big")
    if signature_integer >= modulus:
        return False
    encoded_message_bits = modulus.bit_length() - 1
    encoded_message_length = (encoded_message_bits + 7) // 8
    encoded = pow(signature_integer, exponent, modulus).to_bytes(
        encoded_message_length, "big",
    )
    digest_length = hashlib.sha256().digest_size
    salt_length = 32
    if (
        encoded_message_length < digest_length + salt_length + 2
        or encoded[-1:] != b"\xbc"
    ):
        return False
    masked_db = encoded[:encoded_message_length - digest_length - 1]
    encoded_digest = encoded[encoded_message_length - digest_length - 1:-1]
    unused_bits = 8 * encoded_message_length - encoded_message_bits
    if unused_bits and masked_db[0] & (0xFF << (8 - unused_bits)):
        return False
    mask = mgf1_sha256(encoded_digest, len(masked_db))
    database = bytearray(left ^ right for left, right in zip(masked_db, mask))
    if unused_bits:
        database[0] &= 0xFF >> unused_bits
    padding_length = encoded_message_length - digest_length - salt_length - 2
    if (
        database[:padding_length] != b"\x00" * padding_length
        or database[padding_length] != 1
    ):
        return False
    salt = bytes(database[-salt_length:])
    message_digest = hashlib.sha256(message).digest()
    expected_digest = hashlib.sha256(
        b"\x00" * 8 + message_digest + salt,
    ).digest()
    return hmac.compare_digest(encoded_digest, expected_digest)


def verify_rsa_pss_sha256_signature_hex_key(
    message: bytes,
    signature_b64url: Any,
    modulus_hex: Any,
    public_exponent: Any,
    label: str,
) -> bool:
    """Verify a base64url signature using the schema's hex/integer key form."""

    _, _, modulus_length = canonical_rsa_pss_public_numbers_hex(
        modulus_hex,
        public_exponent,
        label,
    )
    modulus_bytes = bytes.fromhex(modulus_hex)
    require(len(modulus_bytes) == modulus_length, f"{label} modulus length drift")
    modulus_b64url = base64.urlsafe_b64encode(modulus_bytes).rstrip(b"=").decode("ascii")
    return verify_rsa_pss_sha256_signature(
        message,
        signature_b64url,
        modulus_b64url,
        "AQAB",
        label,
    )


