def expect_failure(function: Callable[[], Any], needle: str) -> None:
    try:
        function()
    except GovernanceError as exc:
        require(needle in str(exc), f"self-test expected {needle!r}, got {exc!r}")
    else:
        fail(f"self-test expected failure containing {needle!r}")


class MemoryPath:
    """Minimal immutable Path substitute for no-I/O approval self-tests."""

    def __init__(self, data: bytes) -> None:
        self._data = data

    def read_bytes(self) -> bytes:
        return self._data

    def read_text(self, encoding: str = "utf-8") -> str:
        return self._data.decode(encoding)

    def is_file(self) -> bool:
        return True

    def is_symlink(self) -> bool:
        return False


def self_test_approval_receipt(
    gate_id: str,
    packet: dict[str, Any],
    now: dt.datetime,
) -> None:
    packet_path = MemoryPath(canonical_json_bytes(packet))
    packet_digest = sha256_file(packet_path)  # type: ignore[arg-type]
    receipt = {
        "record_type": "FC01_DAVIDE_APPROVAL_RECEIPT",
        "schema_version": 1,
        "campaign_id": CAMPAIGN_ID,
        "amendment_id": AMENDMENT_ID,
        "gate_id": gate_id,
        "packet_id": packet["packet_id"],
        "packet_path": packet["packet_path"],
        "packet_sha256": packet_digest,
        "decision": "APPROVE",
        "exact_response": f"APPROVE {gate_id} {packet_digest}",
        "decided_at": "2026-08-17T23:20:00Z",
        "captured_at": "2026-08-17T23:21:00Z",
        "presentation_stop_receipt_path": f"{EVIDENCE_REL.as_posix()}/{gate_id.lower()}-presentation.json",
        "presentation_stop_receipt_sha256": "2" * 64,
        "task_or_thread_id": "task-fixture-0001",
        "task_or_thread_id_null_reason": None,
        "user_message_id": "message-fixture-0001",
        "user_message_id_null_reason": None,
        "message_role": "user",
        "method": "INTERACTIVE_DAVIDE_APPROVAL_V1",
        "agent_authored": False,
        "state_before": GATE_WAITING_STATES[gate_id],
        "authorized_transition": GATE_TRANSITIONS[gate_id],
        "one_use": True,
        "revocation_status": "NOT_REVOKED",
        "expiry_status": "VALID",
        "authority_flags_after_decision_before_consumption": FALSE_AUTHORITY,
    }
    receipt_path = MemoryPath(canonical_json_bytes(receipt))
    validated, decided = validate_approval_receipt(
        receipt_path,  # type: ignore[arg-type]
        packet_path,  # type: ignore[arg-type]
        packet,
        dt.datetime(2026, 8, 17, 23, 10, tzinfo=UTC),
        dt.datetime(2026, 8, 18, 1, 0, tzinfo=UTC),
        now,
    )
    require(validated == receipt, f"{gate_id} receipt self-test drift")
    approval_relative = f"{EVIDENCE_REL.as_posix()}/{gate_id.lower()}-approval.json"
    consumption = {
        "record_type": "FC01_APPROVAL_CONSUMPTION_RECEIPT_V1",
        "schema_version": 1,
        "campaign_id": CAMPAIGN_ID,
        "amendment_id": AMENDMENT_ID,
        "gate_id": gate_id,
        "packet_id": packet["packet_id"],
        "packet_path": packet["packet_path"],
        "packet_sha256": packet_digest,
        "approval_receipt_path": approval_relative,
        "approval_receipt_sha256": sha256_file(receipt_path),  # type: ignore[arg-type]
        "consumed_at": "2026-08-17T23:30:00Z",
        "active_clock_snapshot": {
            "clock_version": "FC01_B_CLOCK_V1",
            "seal_receipt": {"path": f"{EVIDENCE_REL.as_posix()}/seal/receipt.json", "sha256": "3" * 64},
            "engineering_start_receipt": {"path": f"{EVIDENCE_REL.as_posix()}/clock/start.json", "sha256": "4" * 64},
            "evaluated_at": "2026-08-17T23:30:00Z",
            "absolute_expires_at": "2026-08-31T20:00:00Z",
            "pause_intervals": [],
            "active_elapsed_seconds": 12600,
            "active_remaining_seconds": 73800,
            "status": "PASS",
        },
        "first_action": packet["actions"][0],
        "prior_consumption_count": 0,
    }
    consumption_path = MemoryPath(canonical_json_bytes(consumption))
    validate_consumption_receipt(
        consumption_path,  # type: ignore[arg-type]
        receipt_path,  # type: ignore[arg-type]
        approval_relative,
        packet_path,  # type: ignore[arg-type]
        packet,
        decided,
        dt.datetime(2026, 8, 18, 1, 0, tzinfo=UTC),
        now,
    )

    def changed_receipt(**changes: Any) -> MemoryPath:
        value = json.loads(json.dumps(receipt))
        value.update(changes)
        return MemoryPath(canonical_json_bytes(value))

    expect_failure(
        lambda: validate_approval_receipt(
            changed_receipt(exact_response="continue"),  # type: ignore[arg-type]
            packet_path,  # type: ignore[arg-type]
            packet,
            dt.datetime(2026, 8, 17, 23, 10, tzinfo=UTC),
            dt.datetime(2026, 8, 18, 1, 0, tzinfo=UTC),
            now,
        ),
        "exact response mismatch",
    )
    expect_failure(
        lambda: validate_approval_receipt(
            changed_receipt(agent_authored=True),  # type: ignore[arg-type]
            packet_path,  # type: ignore[arg-type]
            packet,
            dt.datetime(2026, 8, 17, 23, 10, tzinfo=UTC),
            dt.datetime(2026, 8, 18, 1, 0, tzinfo=UTC),
            now,
        ),
        "agent-authored approval",
    )
    expect_failure(
        lambda: validate_approval_receipt(
            changed_receipt(packet_sha256="0" * 64),  # type: ignore[arg-type]
            packet_path,  # type: ignore[arg-type]
            packet,
            dt.datetime(2026, 8, 17, 23, 10, tzinfo=UTC),
            dt.datetime(2026, 8, 18, 1, 0, tzinfo=UTC),
            now,
        ),
        "packet digest mismatch",
    )
    reused = json.loads(json.dumps(consumption))
    reused["prior_consumption_count"] = 1
    expect_failure(
        lambda: validate_consumption_receipt(
            MemoryPath(canonical_json_bytes(reused)),  # type: ignore[arg-type]
            receipt_path,  # type: ignore[arg-type]
            approval_relative,
            packet_path,  # type: ignore[arg-type]
            packet,
            decided,
            dt.datetime(2026, 8, 18, 1, 0, tzinfo=UTC),
            now,
        ),
        "second consumption",
    )


