def paths_overlap(left: Path, right: Path) -> bool:
    return left == right or left in right.parents or right in left.parents


def canonical_regular_cli_input(raw: str, label: str) -> Path:
    require(isinstance(raw, str) and raw and ".." not in Path(raw).parts, f"{label} path invalid")
    lexical = Path(os.path.abspath(raw))
    require(lexical.is_absolute(), f"{label} path is not absolute")
    try:
        resolved = lexical.resolve(strict=True)
    except OSError as exc:
        fail(f"{label} path cannot be resolved: {exc}")
    require(resolved == lexical and lexical.is_file() and not lexical.is_symlink(), f"{label} traverses a symlink or is not a regular file")
    stat = lexical.stat()
    require(stat.st_nlink == 1, f"{label} has a hard-link alias")
    return lexical


def read_held_regular_fd(fd: int, label: str, *, maximum_bytes: int) -> tuple[bytes, os.stat_result]:
    """Read a held regular-file descriptor and prove its identity stayed fixed."""

    before = os.fstat(fd)
    require(
        stat.S_ISREG(before.st_mode) and before.st_nlink == 1,
        f"{label} is not a single-link regular file",
        state="BLOCKED_SCOPE",
    )
    os.lseek(fd, 0, os.SEEK_SET)
    chunks: list[bytes] = []
    total = 0
    while True:
        chunk = os.read(fd, min(1024 * 1024, maximum_bytes - total + 1))
        if not chunk:
            break
        total += len(chunk)
        require(total <= maximum_bytes, f"{label} exceeds the sealed input bound", state="BLOCKED_SCOPE")
        chunks.append(chunk)
    after = os.fstat(fd)
    require(
        (before.st_dev, before.st_ino, before.st_mode, before.st_nlink, before.st_size,
         before.st_mtime_ns, before.st_ctime_ns)
        == (after.st_dev, after.st_ino, after.st_mode, after.st_nlink, after.st_size,
            after.st_mtime_ns, after.st_ctime_ns),
        f"{label} changed while held",
        state="BLOCKED_SCOPE",
    )
    return b"".join(chunks), after


def open_m00_transient_inputs(
    observation_raw: str,
    initial_raw: str,
    final_raw: str,
    sentinel: str,
) -> dict[str, Any]:
    """Open the exact transient root and all inputs without following links.

    Descriptors stay open in the returned context.  A successful emitter must
    use those same descriptors for parsing/hashing and recheck them before any
    unlink; callers close them with ``close_m00_transient_inputs``.
    """

    observation = Path(os.path.abspath(observation_raw))
    require(
        ".." not in Path(observation_raw).parts
        and observation.name == "observation.json",
        "M00 observation path/name invalid",
        state="BLOCKED_SCOPE",
    )
    root = observation.parent
    parent = root.parent
    require(
        root.name not in {"", ".", ".."}
        and parent.resolve(strict=True) == parent
        and not os.path.ismount(root),
        "M00 transient root is not a canonical non-mount directory",
        state="BLOCKED_SCOPE",
    )
    open_flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    directory_flags = open_flags | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    file_flags = open_flags | getattr(os, "O_NOFOLLOW", 0)
    parent_fd = os.open(parent, directory_flags)
    root_fd: Optional[int] = None
    held_fds: dict[str, int] = {}
    try:
        root_fd = os.open(root.name, directory_flags, dir_fd=parent_fd)
        root_stat = os.fstat(root_fd)
        parent_stat = os.fstat(parent_fd)
        require(
            stat.S_ISDIR(root_stat.st_mode)
            and root_stat.st_dev == parent_stat.st_dev,
            "M00 transient root is a mount/device alias",
            state="BLOCKED_SCOPE",
        )
        expected_names = {"observation.json"}
        artifact_names: dict[str, Optional[str]] = {
            "initial": None if initial_raw == sentinel else "initial.pptx",
            "final": None if final_raw == sentinel else "final.pptx",
        }
        for kind, expected_name in artifact_names.items():
            raw = initial_raw if kind == "initial" else final_raw
            if expected_name is None:
                require(raw == sentinel, f"M00 {kind} artifact sentinel drift", state="BLOCKED_SCOPE")
                continue
            artifact = Path(os.path.abspath(raw))
            require(
                ".." not in Path(raw).parts
                and artifact.parent == root
                and artifact.name == expected_name,
                f"M00 {kind} artifact path/name/root drift",
                state="BLOCKED_SCOPE",
            )
            expected_names.add(expected_name)
        require(
            set(os.listdir(root_fd)) == expected_names,
            "M00 transient root entry-set drift",
            state="BLOCKED_SCOPE",
        )
        for name in sorted(expected_names):
            fd = os.open(name, file_flags, dir_fd=root_fd)
            held_fds[name] = fd
            descriptor_stat = os.fstat(fd)
            path_stat = os.stat(name, dir_fd=root_fd, follow_symlinks=False)
            require(
                stat.S_ISREG(descriptor_stat.st_mode)
                and descriptor_stat.st_nlink == 1
                and descriptor_stat.st_dev == root_stat.st_dev
                and (descriptor_stat.st_dev, descriptor_stat.st_ino)
                == (path_stat.st_dev, path_stat.st_ino),
                f"M00 transient input identity/link/device drift: {name}",
                state="BLOCKED_SCOPE",
            )
        observation_bytes, observation_stat = read_held_regular_fd(
            held_fds["observation.json"], "M00 observation bundle", maximum_bytes=16 * 1024 * 1024,
        )
        artifact_bytes: dict[str, Optional[bytes]] = {"initial": None, "final": None}
        artifact_stats: dict[str, Optional[os.stat_result]] = {"initial": None, "final": None}
        for kind, name in artifact_names.items():
            if name is None:
                continue
            data, held_stat = read_held_regular_fd(
                held_fds[name], f"M00 transient {kind} artifact", maximum_bytes=256 * 1024 * 1024,
            )
            artifact_bytes[kind] = data
            artifact_stats[kind] = held_stat
        return {
            "root": root,
            "parent": parent,
            "parent_fd": parent_fd,
            "root_fd": root_fd,
            "root_stat": root_stat,
            "expected_names": expected_names,
            "held_fds": held_fds,
            "observation_bytes": observation_bytes,
            "observation_stat": observation_stat,
            "artifact_bytes": artifact_bytes,
            "artifact_stats": artifact_stats,
            "artifact_names": artifact_names,
        }
    except BaseException:
        for fd in held_fds.values():
            os.close(fd)
        if root_fd is not None:
            os.close(root_fd)
        os.close(parent_fd)
        raise


def close_m00_transient_inputs(context: dict[str, Any]) -> None:
    for fd in context["held_fds"].values():
        os.close(fd)
    os.close(context["root_fd"])
    os.close(context["parent_fd"])


DESCRIPTOR_TRANSACTION_STATES = (
    "PREPARED",
    "STAGED_DURABLE",
    "INPUT_TOMBSTONED",
    "INPUTS_DELETED",
    "PUBLISHED",
)


def validate_plain_basename(value: Any, label: str) -> str:
    require(
        isinstance(value, str)
        and value not in {"", ".", ".."}
        and "\x00" not in value
        and len(os.fsencode(value)) <= 255
        and re.fullmatch(r"[A-Za-z0-9._-]+", value) is not None
        and Path(value).name == value
        and "/" not in value
        and "\\" not in value,
        f"{label} is not one plain basename",
        state="BLOCKED_SCOPE",
    )
    return value


def descriptor_open_flags(*, directory: bool = False, writable: bool = False) -> int:
    flags = (os.O_WRONLY if writable else os.O_RDONLY) | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    if directory:
        flags |= getattr(os, "O_DIRECTORY", 0)
    return flags


def open_canonical_directory(raw: Union[str, Path], label: str) -> tuple[Path, int, os.stat_result]:
    """Open one canonical directory without following its final component."""

    raw_text = os.fspath(raw)
    require(
        isinstance(raw_text, str) and raw_text and ".." not in Path(raw_text).parts,
        f"{label} path invalid",
        state="BLOCKED_SCOPE",
    )
    lexical = Path(os.path.abspath(raw_text))
    require(
        lexical.name not in {"", ".", ".."},
        f"{label} cannot be a broad filesystem root",
        state="BLOCKED_SCOPE",
    )
    try:
        parent_resolved = lexical.parent.resolve(strict=True)
    except OSError as exc:
        fail(f"{label} parent cannot be resolved: {exc}", state="BLOCKED_SCOPE")
    require(
        parent_resolved == lexical.parent,
        f"{label} parent traverses a symlink",
        state="BLOCKED_SCOPE",
    )
    try:
        fd = os.open(lexical, descriptor_open_flags(directory=True))
    except OSError as exc:
        fail(f"{label} cannot be opened without following links: {exc}", state="BLOCKED_SCOPE")
    try:
        held_stat = os.fstat(fd)
        path_stat = os.stat(lexical, follow_symlinks=False)
        require(
            stat.S_ISDIR(held_stat.st_mode)
            and (held_stat.st_dev, held_stat.st_ino)
            == (path_stat.st_dev, path_stat.st_ino),
            f"{label} descriptor/path identity drift",
            state="BLOCKED_SCOPE",
        )
        return lexical, fd, held_stat
    except BaseException:
        os.close(fd)
        raise


def decode_linux_mountinfo_token(value: str, label: str) -> str:
    """Decode only the four escapes emitted by proc(5) mountinfo."""

    require(isinstance(value, str) and value, f"{label} mountinfo token empty")
    result: list[str] = []
    index = 0
    allowed_escapes = {"040": " ", "011": "\t", "012": "\n", "134": "\\"}
    while index < len(value):
        character = value[index]
        if character != "\\":
            require(
                character not in {"\x00", "\r", "\n", "\t", " "},
                f"{label} mountinfo token has unescaped whitespace/control data",
            )
            result.append(character)
            index += 1
            continue
        require(index + 3 < len(value), f"{label} mountinfo escape is truncated")
        escape = value[index + 1:index + 4]
        require(escape in allowed_escapes, f"{label} mountinfo escape is not canonical: {escape}")
        result.append(allowed_escapes[escape])
        index += 4
    decoded = "".join(result)
    require("\x00" not in decoded, f"{label} mountinfo token decodes to NUL")
    return decoded


def canonical_linux_mount_path(value: str, label: str) -> str:
    decoded = decode_linux_mountinfo_token(value, label)
    require(
        decoded.startswith("/")
        and posixpath.normpath(decoded) == decoded
        and (decoded == "/" or not decoded.endswith("/")),
        f"{label} mountinfo path is not canonical absolute POSIX",
    )
    return decoded


def parse_linux_mountinfo(text: str) -> list[dict[str, Any]]:
    """Parse one exact `/proc/self/mountinfo` snapshot fail-closed."""

    require(
        isinstance(text, str) and text and text.endswith("\n") and "\r" not in text,
        "Linux mountinfo is not canonical newline-terminated text",
    )
    rows: list[dict[str, Any]] = []
    seen_mount_ids: set[int] = set()
    for line_index, line in enumerate(text[:-1].split("\n"), start=1):
        require(line and line.count(" - ") == 1, f"Linux mountinfo separator drift: {line_index}")
        before_text, after_text = line.split(" - ", 1)
        before = before_text.split(" ")
        after = after_text.split(" ")
        require(
            len(before) >= 6
            and len(after) == 3
            and all(token for token in before)
            and all(token for token in after),
            f"Linux mountinfo field count drift: {line_index}",
        )
        require(
            re.fullmatch(r"[1-9][0-9]*", before[0]) is not None
            and re.fullmatch(r"[1-9][0-9]*", before[1]) is not None,
            f"Linux mountinfo mount/parent id invalid: {line_index}",
        )
        mount_id = int(before[0])
        parent_id = int(before[1])
        require(mount_id not in seen_mount_ids, f"Linux mountinfo duplicate mount id: {mount_id}")
        seen_mount_ids.add(mount_id)
        device_match = re.fullmatch(r"(0|[1-9][0-9]*):(0|[1-9][0-9]*)", before[2])
        require(device_match is not None, f"Linux mountinfo device invalid: {line_index}")
        root = canonical_linux_mount_path(before[3], f"Linux mountinfo root {line_index}")
        mount_point = canonical_linux_mount_path(
            before[4],
            f"Linux mountinfo mount point {line_index}",
        )
        mount_options = before[5].split(",")
        optional_fields = before[6:]
        super_options = after[2].split(",")
        require(
            all(re.fullmatch(r"[A-Za-z0-9._:=+-]+", value) for value in mount_options)
            and all(re.fullmatch(r"[A-Za-z0-9._:=+-]+", value) for value in optional_fields)
            and all(re.fullmatch(r"[A-Za-z0-9._:=+/@-]+", value) for value in super_options),
            f"Linux mountinfo option token invalid: {line_index}",
        )
        filesystem_type = decode_linux_mountinfo_token(
            after[0],
            f"Linux mountinfo filesystem type {line_index}",
        )
        mount_source = decode_linux_mountinfo_token(
            after[1],
            f"Linux mountinfo mount source {line_index}",
        )
        rows.append(
            {
                "mount_id": mount_id,
                "parent_id": parent_id,
                "device_major": int(device_match.group(1)),
                "device_minor": int(device_match.group(2)),
                "root": root,
                "mount_point": mount_point,
                "mount_options": mount_options,
                "optional_fields": optional_fields,
                "filesystem_type": filesystem_type,
                "mount_source": mount_source,
                "super_options": super_options,
            }
        )
    require(rows, "Linux mountinfo contains no rows")
    return rows


def parse_linux_fdinfo_mount_id(text: str) -> int:
    require(
        isinstance(text, str)
        and text
        and text.endswith("\n")
        and "\x00" not in text
        and "\r" not in text,
        "Linux fdinfo is not canonical newline-terminated text",
    )
    matches = re.findall(r"(?m)^mnt_id:\s+([1-9][0-9]*)$", text)
    require(len(matches) == 1, "Linux fdinfo does not contain exactly one mount id")
    return int(matches[0])


def _posix_path_parts(value: str) -> tuple[str, ...]:
    require(value.startswith("/") and posixpath.normpath(value) == value, "POSIX path invalid")
    return tuple(part for part in value.split("/") if part)


def _posix_path_contains(parent: str, child: str) -> bool:
    parent_parts = _posix_path_parts(parent)
    child_parts = _posix_path_parts(child)
    return child_parts[:len(parent_parts)] == parent_parts


def project_linux_mount_identity(
    label: str,
    canonical_path: str,
    mount_id: int,
    device_major: int,
    device_minor: int,
    inode: int,
    mount_rows: list[dict[str, Any]],
) -> dict[str, Any]:
    require(
        isinstance(label, str) and label
        and isinstance(canonical_path, str)
        and canonical_path.startswith("/")
        and posixpath.normpath(canonical_path) == canonical_path,
        "Linux protected mount projection label/path invalid",
    )
    require(
        exact_nonnegative_int(device_major)
        and exact_nonnegative_int(device_minor)
        and exact_nonnegative_int(inode),
        f"Linux protected mount projection stat invalid: {label}",
    )
    matching = [row for row in mount_rows if row["mount_id"] == mount_id]
    require(len(matching) == 1, f"Linux protected mount id is absent/ambiguous: {label}")
    row = matching[0]
    require(
        (row["device_major"], row["device_minor"]) == (device_major, device_minor),
        f"Linux protected mount device disagrees with held descriptor: {label}",
    )
    require(
        _posix_path_contains(row["mount_point"], canonical_path),
        f"Linux protected path is outside its fd mount point: {label}",
    )
    mount_parts = _posix_path_parts(row["mount_point"])
    path_parts = _posix_path_parts(canonical_path)
    relative_parts = path_parts[len(mount_parts):]
    underlying = posixpath.normpath(
        posixpath.join(row["root"], *relative_parts),
    )
    require(
        underlying.startswith("/") and _posix_path_contains(row["root"], underlying),
        f"Linux protected underlying path escapes its mount root: {label}",
    )
    return {
        "label": label,
        "canonical_path": canonical_path,
        "mount_id": mount_id,
        "device_major": device_major,
        "device_minor": device_minor,
        "inode": inode,
        "mount_root": row["root"],
        "mount_point": row["mount_point"],
        "underlying_path": underlying,
    }


def require_disjoint_linux_mount_identities(projections: list[dict[str, Any]]) -> None:
    require(
        isinstance(projections, list)
        and len(projections) >= 2
        and all(isinstance(row, dict) and isinstance(row.get("label"), str) for row in projections)
        and len(projections) == len({row["label"] for row in projections}),
        "Linux protected mount projections have duplicate labels",
    )
    for projection_index, projection in enumerate(projections):
        exact_keys(
            projection,
            {
                "label",
                "canonical_path",
                "mount_id",
                "device_major",
                "device_minor",
                "inode",
                "mount_root",
                "mount_point",
                "underlying_path",
            },
            f"Linux protected mount projection {projection_index + 1}",
        )
        require(
            all(
                isinstance(projection[field], str)
                for field in (
                    "label",
                    "canonical_path",
                    "mount_root",
                    "mount_point",
                    "underlying_path",
                )
            )
            and all(
                exact_nonnegative_int(projection[field])
                for field in (
                    "mount_id",
                    "device_major",
                    "device_minor",
                    "inode",
                )
            ),
            f"Linux protected mount projection scalar type drift: {projection_index + 1}",
        )
        require(
            _posix_path_contains(projection["mount_point"], projection["canonical_path"]),
            f"Linux protected mount projection path/mount drift: {projection['label']}",
        )
        mount_parts = _posix_path_parts(projection["mount_point"])
        path_parts = _posix_path_parts(projection["canonical_path"])
        require(
            projection["underlying_path"]
            == posixpath.normpath(
                posixpath.join(projection["mount_root"], *path_parts[len(mount_parts):])
            ),
            f"Linux protected mount projection underlying-path drift: {projection['label']}",
        )
    for left_index, left in enumerate(projections):
        for right in projections[left_index + 1:]:
            lexical_overlap = _posix_path_contains(
                left["canonical_path"],
                right["canonical_path"],
            ) or _posix_path_contains(
                right["canonical_path"],
                left["canonical_path"],
            )
            require(
                not lexical_overlap,
                f"Linux protected paths overlap lexically: {left['label']}/{right['label']}",
                state="BLOCKED_SCOPE",
            )
            same_device = (
                left["device_major"],
                left["device_minor"],
            ) == (
                right["device_major"],
                right["device_minor"],
            )
            underlying_overlap = same_device and (
                _posix_path_contains(left["underlying_path"], right["underlying_path"])
                or _posix_path_contains(right["underlying_path"], left["underlying_path"])
            )
            same_object = same_device and left["inode"] == right["inode"]
            require(
                not underlying_overlap and not same_object,
                f"Linux protected paths are bind/inode aliases: {left['label']}/{right['label']}",
                state="BLOCKED_SCOPE",
            )


def read_linux_proc_snapshot(path: str, label: str, *, maximum_bytes: int) -> str:
    require(sys.platform.startswith("linux"), f"{label} requires Linux procfs")
    require(path.startswith("/proc/") and ".." not in Path(path).parts, f"{label} proc path invalid")
    try:
        fd = os.open(path, os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0))
    except OSError as exc:
        fail(f"{label} cannot be held: {exc}", state="BLOCKED_SCOPE")
    try:
        held_stat = os.fstat(fd)
        path_stat = os.stat(path, follow_symlinks=False)
        require(
            stat.S_ISREG(held_stat.st_mode)
            and (held_stat.st_dev, held_stat.st_ino)
            == (path_stat.st_dev, path_stat.st_ino),
            f"{label} proc descriptor/path identity drift",
            state="BLOCKED_SCOPE",
        )
        chunks: list[bytes] = []
        total = 0
        while True:
            chunk = os.read(fd, min(1024 * 1024, maximum_bytes - total + 1))
            if not chunk:
                break
            total += len(chunk)
            require(total <= maximum_bytes, f"{label} exceeds its input bound")
            chunks.append(chunk)
        data = b"".join(chunks)
        require(os.fstat(fd).st_ino == held_stat.st_ino, f"{label} proc descriptor changed")
        try:
            return data.decode("utf-8")
        except UnicodeError as exc:
            fail(f"{label} is not UTF-8: {exc}")
    finally:
        os.close(fd)


def capture_linux_mount_identity_for_fd(
    label: str,
    canonical_path: Union[str, Path],
    fd: int,
    mount_rows: list[dict[str, Any]],
) -> dict[str, Any]:
    path_text = os.fspath(canonical_path)
    path = Path(path_text)
    held_stat = os.fstat(fd)
    require(
        path.is_absolute()
        and ".." not in path.parts
        and path.resolve(strict=True) == path,
        f"Linux protected path is not canonical: {label}",
        state="BLOCKED_SCOPE",
    )
    path_stat = os.stat(path, follow_symlinks=False)
    require(
        (held_stat.st_dev, held_stat.st_ino) == (path_stat.st_dev, path_stat.st_ino),
        f"Linux protected path/descriptor identity drift: {label}",
        state="BLOCKED_SCOPE",
    )
    fdinfo = read_linux_proc_snapshot(
        f"/proc/self/fdinfo/{fd}",
        f"Linux fdinfo/{label}",
        maximum_bytes=64 * 1024,
    )
    return project_linux_mount_identity(
        label,
        path_text,
        parse_linux_fdinfo_mount_id(fdinfo),
        os.major(held_stat.st_dev),
        os.minor(held_stat.st_dev),
        held_stat.st_ino,
        mount_rows,
    )


def self_test_linux_mount_alias_primitives() -> None:
    mountinfo = (
        "36 25 8:1 / / rw,relatime - ext4 /dev/root rw\n"
        "100 36 8:1 /srv/control /control ro,relatime - ext4 /dev/root rw\n"
        "101 36 8:1 /srv/control /alias ro,relatime - ext4 /dev/root rw\n"
        "102 36 8:1 /srv/candidate /candidate ro,relatime - ext4 /dev/root rw\n"
        "103 36 8:1 /srv/space\\040name /space\\040name ro,relatime - ext4 /dev/root rw\n"
    )
    rows = parse_linux_mountinfo(mountinfo)
    require(parse_linux_fdinfo_mount_id("pos:\t0\nflags:\t0100000\nmnt_id:\t100\n") == 100, "fdinfo mount id parse drift")
    control = project_linux_mount_identity(
        "control",
        "/control/docs",
        100,
        8,
        1,
        10,
        rows,
    )
    alias = project_linux_mount_identity(
        "alias",
        "/alias/docs",
        101,
        8,
        1,
        11,
        rows,
    )
    candidate = project_linux_mount_identity(
        "candidate",
        "/candidate/worktree",
        102,
        8,
        1,
        12,
        rows,
    )
    require_disjoint_linux_mount_identities([control, candidate])
    expect_failure(
        lambda: require_disjoint_linux_mount_identities([control, alias]),
        "bind/inode aliases",
    )
    same_inode = {**candidate, "inode": control["inode"]}
    expect_failure(
        lambda: require_disjoint_linux_mount_identities([control, same_inode]),
        "bind/inode aliases",
    )
    lexical_child = project_linux_mount_identity(
        "candidate",
        "/control/docs/subtree",
        100,
        8,
        1,
        12,
        rows,
    )
    expect_failure(
        lambda: require_disjoint_linux_mount_identities([control, lexical_child]),
        "overlap lexically",
    )
    expect_failure(
        lambda: parse_linux_mountinfo(mountinfo + mountinfo.splitlines(keepends=True)[1]),
        "duplicate mount id",
    )
    expect_failure(
        lambda: parse_linux_mountinfo(mountinfo.replace("/space\\040name", "/space\\041name", 1)),
        "escape is not canonical",
    )
    expect_failure(
        lambda: parse_linux_fdinfo_mount_id("pos:\t0\n"),
        "exactly one mount id",
    )
    expect_failure(
        lambda: parse_linux_fdinfo_mount_id("mnt_id:\t100\nmnt_id:\t101\n"),
        "exactly one mount id",
    )
    self_test_real_linux_bind_mount_alias_if_capable()


def self_test_real_linux_bind_mount_alias_if_capable() -> None:
    """Exercise a real bind alias only inside a private capable mount ns."""

    if not sys.platform.startswith("linux") or os.geteuid() != 0:
        return
    try:
        self_namespace = os.stat("/proc/self/ns/mnt").st_ino
        init_namespace = os.stat("/proc/1/ns/mnt").st_ino
        status = read_linux_proc_snapshot(
            "/proc/self/status",
            "Linux process capability status",
            maximum_bytes=1024 * 1024,
        )
    except (OSError, GovernanceError):
        return
    capability_match = re.search(r"(?m)^CapEff:\s*([0-9A-Fa-f]+)$", status)
    if (
        self_namespace == init_namespace
        or capability_match is None
        or not (int(capability_match.group(1), 16) & (1 << 21))
    ):
        return
    mount_binary = next(
        (path for path in (Path("/usr/bin/mount"), Path("/bin/mount")) if path.is_file()),
        None,
    )
    umount_binary = next(
        (path for path in (Path("/usr/bin/umount"), Path("/bin/umount")) if path.is_file()),
        None,
    )
    if mount_binary is None or umount_binary is None:
        return
    with tempfile.TemporaryDirectory(prefix="fc01-bind-alias-") as raw_temp:
        root = Path(raw_temp).resolve()
        source = root / "source"
        alias = root / "alias"
        source.mkdir(mode=0o700)
        alias.mkdir(mode=0o700)
        mounted = False
        try:
            proc = subprocess.run(
                [os.fspath(mount_binary), "--bind", os.fspath(source), os.fspath(alias)],
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=False,
                env={"LANG": "C", "PATH": "/usr/bin:/bin"},
            )
            if proc.returncode != 0:
                return
            mounted = True
            source_fd = os.open(source, descriptor_open_flags(directory=True))
            alias_fd = os.open(alias, descriptor_open_flags(directory=True))
            try:
                rows = parse_linux_mountinfo(
                    read_linux_proc_snapshot(
                        "/proc/self/mountinfo",
                        "Linux mountinfo",
                        maximum_bytes=8 * 1024 * 1024,
                    )
                )
                source_projection = capture_linux_mount_identity_for_fd(
                    "real-bind-source",
                    os.fspath(source),
                    source_fd,
                    rows,
                )
                alias_projection = capture_linux_mount_identity_for_fd(
                    "real-bind-alias",
                    os.fspath(alias),
                    alias_fd,
                    rows,
                )
                expect_failure(
                    lambda: require_disjoint_linux_mount_identities(
                        [source_projection, alias_projection]
                    ),
                    "bind/inode aliases",
                )
            finally:
                os.close(source_fd)
                os.close(alias_fd)
        finally:
            if mounted:
                unmount = subprocess.run(
                    [os.fspath(umount_binary), os.fspath(alias)],
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    check=False,
                    env={"LANG": "C", "PATH": "/usr/bin:/bin"},
                )
                require(unmount.returncode == 0, "real bind-mount self-test could not unmount its alias")


def regular_file_identity_row(
    basename: str,
    held_stat: os.stat_result,
    data: bytes,
) -> dict[str, Any]:
    return {
        "basename": basename,
        "device": held_stat.st_dev,
        "inode": held_stat.st_ino,
        "nlink": held_stat.st_nlink,
        "mode": stat.S_IMODE(held_stat.st_mode),
        "size": held_stat.st_size,
        "mtime_ns": held_stat.st_mtime_ns,
        "ctime_ns": held_stat.st_ctime_ns,
        "sha256": sha256_bytes(data),
    }


def open_exact_regular_file_inventory(
    root_raw: Union[str, Path],
    maximum_bytes_by_basename: dict[str, int],
    label: str,
) -> dict[str, Any]:
    """Hold and hash an exact, flat set of single-link regular files.

    The parent, directory, and every file remain open in the returned context.
    The final directory and file components are opened relative to held dirfds
    with ``O_NOFOLLOW``.  The inventory is intentionally flat: a caller must
    enumerate every permitted basename and cannot smuggle a nested tree.
    """

    require(
        isinstance(maximum_bytes_by_basename, dict),
        f"{label} bounds are not a basename mapping",
        state="BLOCKED_SCOPE",
    )
    expected_names = set(maximum_bytes_by_basename)
    for basename, maximum_bytes in maximum_bytes_by_basename.items():
        validate_plain_basename(basename, f"{label} basename")
        require(
            exact_nonnegative_int(maximum_bytes) and maximum_bytes > 0,
            f"{label} byte bound invalid: {basename}",
            state="BLOCKED_SCOPE",
        )
    raw_text = os.fspath(root_raw)
    require(
        isinstance(raw_text, str) and raw_text and ".." not in Path(raw_text).parts,
        f"{label} root path invalid",
        state="BLOCKED_SCOPE",
    )
    root = Path(os.path.abspath(raw_text))
    validate_plain_basename(root.name, f"{label} root")
    parent, parent_fd, parent_stat = open_canonical_directory(root.parent, f"{label} parent")
    root_fd: Optional[int] = None
    held_fds: dict[str, int] = {}
    try:
        try:
            root_fd = os.open(root.name, descriptor_open_flags(directory=True), dir_fd=parent_fd)
        except OSError as exc:
            fail(f"{label} root cannot be opened without following links: {exc}", state="BLOCKED_SCOPE")
        root_stat = os.fstat(root_fd)
        root_path_stat = os.stat(root.name, dir_fd=parent_fd, follow_symlinks=False)
        require(
            stat.S_ISDIR(root_stat.st_mode)
            and root_stat.st_dev == parent_stat.st_dev
            and (root_stat.st_dev, root_stat.st_ino)
            == (root_path_stat.st_dev, root_path_stat.st_ino),
            f"{label} root is a mount, link, or descriptor alias",
            state="BLOCKED_SCOPE",
        )
        actual_names = set(os.listdir(root_fd))
        require(
            actual_names == expected_names,
            f"{label} entry-set drift: missing={sorted(expected_names - actual_names)} "
            f"extra={sorted(actual_names - expected_names)}",
            state="BLOCKED_SCOPE",
        )
        file_rows: list[dict[str, Any]] = []
        file_bytes: dict[str, bytes] = {}
        for basename in sorted(expected_names):
            try:
                fd = os.open(basename, descriptor_open_flags(), dir_fd=root_fd)
            except OSError as exc:
                fail(
                    f"{label} file cannot be opened without following links: {basename}: {exc}",
                    state="BLOCKED_SCOPE",
                )
            held_fds[basename] = fd
            descriptor_stat = os.fstat(fd)
            path_stat = os.stat(basename, dir_fd=root_fd, follow_symlinks=False)
            require(
                stat.S_ISREG(descriptor_stat.st_mode)
                and descriptor_stat.st_nlink == 1
                and descriptor_stat.st_dev == root_stat.st_dev
                and (descriptor_stat.st_dev, descriptor_stat.st_ino)
                == (path_stat.st_dev, path_stat.st_ino),
                f"{label} file identity/link/device drift: {basename}",
                state="BLOCKED_SCOPE",
            )
            data, after = read_held_regular_fd(
                fd,
                f"{label}/{basename}",
                maximum_bytes=maximum_bytes_by_basename[basename],
            )
            file_bytes[basename] = data
            file_rows.append(regular_file_identity_row(basename, after, data))
        manifest = {
            "root_device": root_stat.st_dev,
            "root_inode": root_stat.st_ino,
            "root_nlink": root_stat.st_nlink,
            "root_mode": stat.S_IMODE(root_stat.st_mode),
            "file_rows": file_rows,
        }
        return {
            "root": root,
            "parent": parent,
            "parent_fd": parent_fd,
            "root_fd": root_fd,
            "current_root_basename": root.name,
            "root_stat": root_stat,
            "expected_names": expected_names,
            "maximum_bytes_by_basename": dict(maximum_bytes_by_basename),
            "held_fds": held_fds,
            "file_bytes": file_bytes,
            "manifest": manifest,
            "manifest_sha256": sha256_bytes(canonical_json_bytes(manifest)),
            "closed": False,
        }
    except BaseException:
        for fd in held_fds.values():
            os.close(fd)
        if root_fd is not None:
            os.close(root_fd)
        os.close(parent_fd)
        raise


def close_exact_regular_file_inventory(context: dict[str, Any]) -> None:
    if context.get("closed"):
        return
    for fd in context["held_fds"].values():
        os.close(fd)
    os.close(context["root_fd"])
    os.close(context["parent_fd"])
    context["closed"] = True


def validate_held_regular_file_inventory(context: dict[str, Any], label: str) -> None:
    require(not context.get("closed"), f"{label} inventory descriptors are closed", state="BLOCKED_SCOPE")
    root_stat = os.fstat(context["root_fd"])
    root_path_stat = os.stat(
        context["current_root_basename"],
        dir_fd=context["parent_fd"],
        follow_symlinks=False,
    )
    manifest = context["manifest"]
    require(
        stat.S_ISDIR(root_stat.st_mode)
        and (
            root_stat.st_dev,
            root_stat.st_ino,
            root_stat.st_nlink,
            stat.S_IMODE(root_stat.st_mode),
        )
        == (
            manifest["root_device"],
            manifest["root_inode"],
            manifest["root_nlink"],
            manifest["root_mode"],
        )
        and (root_stat.st_dev, root_stat.st_ino)
        == (root_path_stat.st_dev, root_path_stat.st_ino),
        f"{label} root descriptor identity drift",
        state="BLOCKED_SCOPE",
    )
    require(
        set(os.listdir(context["root_fd"])) == context["expected_names"],
        f"{label} held entry-set drift",
        state="BLOCKED_SCOPE",
    )
    expected_rows = {row["basename"]: row for row in manifest["file_rows"]}
    for basename in sorted(context["expected_names"]):
        fd = context["held_fds"][basename]
        path_stat = os.stat(basename, dir_fd=context["root_fd"], follow_symlinks=False)
        data, after = read_held_regular_fd(
            fd,
            f"{label}/{basename}",
            maximum_bytes=context["maximum_bytes_by_basename"][basename],
        )
        row = regular_file_identity_row(basename, after, data)
        require(
            row == expected_rows[basename]
            and (after.st_dev, after.st_ino) == (path_stat.st_dev, path_stat.st_ino)
            and data == context["file_bytes"][basename],
            f"{label} held file identity or content drift: {basename}",
            state="BLOCKED_SCOPE",
        )


def invoke_transaction_crash_hook(
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]],
    checkpoint: str,
    details: dict[str, Any],
) -> None:
    if crash_hook is not None:
        crash_hook(checkpoint, details)


def rename_held_inventory_to_tombstone(
    context: dict[str, Any],
    tombstone_basename: str,
    *,
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]] = None,
) -> str:
    """Atomically tombstone a held inventory in its original directory."""

    tombstone_basename = validate_plain_basename(tombstone_basename, "transaction tombstone")
    require(
        tombstone_basename != context["root"].name,
        "transaction tombstone aliases its input root",
        state="BLOCKED_SCOPE",
    )
    if context["current_root_basename"] == tombstone_basename:
        validate_held_regular_file_inventory(context, "tombstoned inventory")
        return "ALREADY_TOMBSTONED"
    validate_held_regular_file_inventory(context, "pre-tombstone inventory")
    try:
        os.stat(tombstone_basename, dir_fd=context["parent_fd"], follow_symlinks=False)
    except FileNotFoundError:
        pass
    except OSError as exc:
        fail(f"transaction tombstone lookup failed: {exc}", state="BLOCKED_SCOPE")
    else:
        fail("transaction tombstone already exists", state="BLOCKED_SCOPE")
    try:
        os.rename(
            context["current_root_basename"],
            tombstone_basename,
            src_dir_fd=context["parent_fd"],
            dst_dir_fd=context["parent_fd"],
        )
        os.fsync(context["parent_fd"])
    except OSError as exc:
        fail(f"transaction tombstone rename/fsync failed: {exc}", state="BLOCKED_SCOPE")
    context["current_root_basename"] = tombstone_basename
    validate_held_regular_file_inventory(context, "post-tombstone inventory")
    invoke_transaction_crash_hook(
        crash_hook,
        "INPUT_TOMBSTONED",
        {"manifest_sha256": context["manifest_sha256"], "tombstone": tombstone_basename},
    )
    return "TOMBSTONED"


def _statat_optional(directory_fd: int, basename: str) -> Optional[os.stat_result]:
    try:
        return os.stat(basename, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        return None
    except OSError as exc:
        fail(f"descriptor-relative lookup failed for {basename}: {exc}", state="BLOCKED_SCOPE")


def reconcile_exact_inventory_location(
    parent_raw: Union[str, Path],
    source_basename: str,
    tombstone_basename: str,
    manifest: dict[str, Any],
) -> str:
    """Recognize a crash immediately before or after the tombstone rename.

    Exactly one location must exist and it must still match the complete held
    inventory.  A caller may then append the missing INPUT_TOMBSTONED journal
    row before allowing any unlink.
    """

    source_basename = validate_plain_basename(source_basename, "transaction source")
    tombstone_basename = validate_plain_basename(tombstone_basename, "transaction tombstone")
    require(source_basename != tombstone_basename, "transaction source/tombstone alias")
    parent, parent_fd, _ = open_canonical_directory(parent_raw, "transaction inventory parent")
    try:
        source_exists = _statat_optional(parent_fd, source_basename) is not None
        tombstone_exists = _statat_optional(parent_fd, tombstone_basename) is not None
        require(
            source_exists != tombstone_exists,
            "transaction inventory must exist at exactly one source/tombstone location",
            state="BLOCKED_SCOPE",
        )
    finally:
        os.close(parent_fd)
    selected = source_basename if source_exists else tombstone_basename
    bounds = {
        row["basename"]: max(1, row["size"])
        for row in manifest["file_rows"]
    }
    context = open_exact_regular_file_inventory(
        parent / selected,
        bounds,
        "reconciled transaction inventory",
    )
    try:
        require(
            context["manifest"] == manifest,
            "reconciled transaction inventory identity/content drift",
            state="BLOCKED_SCOPE",
        )
    finally:
        close_exact_regular_file_inventory(context)
    return "SOURCE_PRESENT" if source_exists else "TOMBSTONED"


def delete_exact_tombstoned_inventory(
    parent_raw: Union[str, Path],
    source_basename: str,
    tombstone_basename: str,
    manifest: dict[str, Any],
    *,
    allow_partial_resume: bool,
    allow_already_absent: bool,
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]] = None,
) -> str:
    """Delete only a previously captured tombstone, safely and resumably."""

    source_basename = validate_plain_basename(source_basename, "transaction source")
    tombstone_basename = validate_plain_basename(tombstone_basename, "transaction tombstone")
    require(source_basename != tombstone_basename, "transaction source/tombstone alias", state="BLOCKED_SCOPE")
    parent, parent_fd, parent_stat = open_canonical_directory(parent_raw, "transaction tombstone parent")
    del parent
    tombstone_fd: Optional[int] = None
    try:
        require(
            _statat_optional(parent_fd, source_basename) is None,
            "transaction source still exists beside its tombstone",
            state="BLOCKED_SCOPE",
        )
        tombstone_path_stat = _statat_optional(parent_fd, tombstone_basename)
        if tombstone_path_stat is None:
            require(
                allow_already_absent,
                "transaction tombstone is unexpectedly absent",
                state="BLOCKED_SCOPE",
            )
            return "ALREADY_DELETED"
        try:
            tombstone_fd = os.open(
                tombstone_basename,
                descriptor_open_flags(directory=True),
                dir_fd=parent_fd,
            )
        except OSError as exc:
            fail(f"transaction tombstone cannot be opened: {exc}", state="BLOCKED_SCOPE")
        tombstone_stat = os.fstat(tombstone_fd)
        require(
            stat.S_ISDIR(tombstone_stat.st_mode)
            and tombstone_stat.st_dev == parent_stat.st_dev
            and (
                tombstone_stat.st_dev,
                tombstone_stat.st_ino,
                stat.S_IMODE(tombstone_stat.st_mode),
            )
            == (
                manifest["root_device"],
                manifest["root_inode"],
                manifest["root_mode"],
            )
            and (tombstone_stat.st_dev, tombstone_stat.st_ino)
            == (tombstone_path_stat.st_dev, tombstone_path_stat.st_ino),
            "transaction tombstone root identity drift",
            state="BLOCKED_SCOPE",
        )
        expected_rows = {row["basename"]: row for row in manifest["file_rows"]}
        actual_names = set(os.listdir(tombstone_fd))
        require(
            actual_names <= set(expected_rows),
            f"transaction tombstone has unlisted entries: {sorted(actual_names - set(expected_rows))}",
            state="BLOCKED_SCOPE",
        )
        require(
            allow_partial_resume or actual_names == set(expected_rows),
            "transaction tombstone is partially deleted without resume authority",
            state="BLOCKED_SCOPE",
        )
        for basename in sorted(expected_rows):
            if basename not in actual_names:
                continue
            row = expected_rows[basename]
            try:
                file_fd = os.open(basename, descriptor_open_flags(), dir_fd=tombstone_fd)
            except OSError as exc:
                fail(f"transaction tombstone file cannot be opened: {basename}: {exc}", state="BLOCKED_SCOPE")
            try:
                data, held_stat = read_held_regular_fd(
                    file_fd,
                    f"transaction tombstone/{basename}",
                    maximum_bytes=max(1, row["size"]),
                )
                path_stat = os.stat(basename, dir_fd=tombstone_fd, follow_symlinks=False)
                require(
                    regular_file_identity_row(basename, held_stat, data) == row
                    and (held_stat.st_dev, held_stat.st_ino)
                    == (path_stat.st_dev, path_stat.st_ino),
                    f"transaction tombstone file drift: {basename}",
                    state="BLOCKED_SCOPE",
                )
                os.unlink(basename, dir_fd=tombstone_fd)
                os.fsync(tombstone_fd)
                require(os.fstat(file_fd).st_nlink == 0, f"transaction tombstone unlink did not detach: {basename}")
            finally:
                os.close(file_fd)
            invoke_transaction_crash_hook(
                crash_hook,
                "TOMBSTONE_FILE_UNLINKED",
                {"basename": basename, "sha256": row["sha256"]},
            )
        require(not os.listdir(tombstone_fd), "transaction tombstone is not empty after deletion")
        final_path_stat = os.stat(tombstone_basename, dir_fd=parent_fd, follow_symlinks=False)
        require(
            (tombstone_stat.st_dev, tombstone_stat.st_ino)
            == (final_path_stat.st_dev, final_path_stat.st_ino),
            "transaction tombstone path changed before rmdir",
            state="BLOCKED_SCOPE",
        )
        os.rmdir(tombstone_basename, dir_fd=parent_fd)
        os.fsync(parent_fd)
        require(
            _statat_optional(parent_fd, tombstone_basename) is None,
            "transaction tombstone still exists after rmdir",
            state="BLOCKED_SCOPE",
        )
        invoke_transaction_crash_hook(
            crash_hook,
            "INPUTS_DELETED",
            {"tombstone": tombstone_basename},
        )
        return "DELETED"
    finally:
        if tombstone_fd is not None:
            os.close(tombstone_fd)
        os.close(parent_fd)


def validate_descriptor_transaction_journal(
    entries: Any,
    transaction_id: str,
) -> list[dict[str, Any]]:
    """Validate a gapless, monotonic, content-addressed journal prefix."""

    require(
        isinstance(transaction_id, str)
        and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}", transaction_id) is not None,
        "transaction journal id invalid",
        state="BLOCKED_SCOPE",
    )
    require(
        isinstance(entries, list) and len(entries) <= len(DESCRIPTOR_TRANSACTION_STATES),
        "transaction journal is not a bounded row list",
        state="BLOCKED_SCOPE",
    )
    previous_digest: Optional[str] = None
    previous_time: Optional[dt.datetime] = None
    for index, entry in enumerate(entries):
        require(isinstance(entry, dict), f"transaction journal row is not an object: {index + 1}")
        exact_keys(
            entry,
            {
                "transaction_id",
                "sequence",
                "state",
                "recorded_at",
                "previous_entry_sha256",
                "payload_sha256",
                "entry_sha256",
            },
            f"transaction journal row {index + 1}",
        )
        require(
            entry["transaction_id"] == transaction_id
            and entry["sequence"] == index + 1
            and entry["state"] == DESCRIPTOR_TRANSACTION_STATES[index],
            f"transaction journal sequence/state drift: {index + 1}",
        )
        require(
            entry["previous_entry_sha256"] == previous_digest,
            f"transaction journal previous digest drift: {index + 1}",
        )
        require(
            isinstance(entry["payload_sha256"], str)
            and HEX64_RE.fullmatch(entry["payload_sha256"]) is not None,
            f"transaction journal payload digest invalid: {index + 1}",
        )
        recorded_at = parse_time(entry["recorded_at"], f"transaction journal row {index + 1} time")
        require(
            previous_time is None or recorded_at >= previous_time,
            f"transaction journal time regressed: {index + 1}",
        )
        body = {key: value for key, value in entry.items() if key != "entry_sha256"}
        derived_digest = sha256_bytes(canonical_json_bytes(body))
        require(
            entry["entry_sha256"] == derived_digest,
            f"transaction journal entry digest drift: {index + 1}",
        )
        previous_digest = derived_digest
        previous_time = recorded_at
    return entries


def descriptor_transaction_clock_value(
    clock: Callable[[], Union[str, dt.datetime]],
) -> str:
    value = clock()
    if isinstance(value, str):
        parse_time(value, "transaction journal clock")
        return value
    require(
        isinstance(value, dt.datetime)
        and value.tzinfo is not None
        and value.utcoffset() == dt.timedelta(0)
        and value.microsecond == 0,
        "transaction journal clock is not exact second-resolution UTC",
    )
    return format_time(value)


def append_descriptor_transaction_journal_entry(
    entries: list[dict[str, Any]],
    transaction_id: str,
    state_name: str,
    payload_sha256: str,
    *,
    clock: Callable[[], Union[str, dt.datetime]],
) -> list[dict[str, Any]]:
    validate_descriptor_transaction_journal(entries, transaction_id)
    next_index = len(entries)
    require(
        next_index < len(DESCRIPTOR_TRANSACTION_STATES)
        and state_name == DESCRIPTOR_TRANSACTION_STATES[next_index],
        "transaction journal transition is not the exact next state",
    )
    require(
        isinstance(payload_sha256, str) and HEX64_RE.fullmatch(payload_sha256) is not None,
        "transaction journal payload digest invalid",
    )
    body = {
        "transaction_id": transaction_id,
        "sequence": next_index + 1,
        "state": state_name,
        "recorded_at": descriptor_transaction_clock_value(clock),
        "previous_entry_sha256": entries[-1]["entry_sha256"] if entries else None,
        "payload_sha256": payload_sha256,
    }
    entry = {**body, "entry_sha256": sha256_bytes(canonical_json_bytes(body))}
    result = [*entries, entry]
    validate_descriptor_transaction_journal(result, transaction_id)
    return result


def _read_regular_at(
    directory_fd: int,
    basename: str,
    label: str,
    *,
    maximum_bytes: int,
    expected_mode: Optional[int] = None,
) -> Optional[bytes]:
    try:
        fd = os.open(basename, descriptor_open_flags(), dir_fd=directory_fd)
    except FileNotFoundError:
        return None
    except OSError as exc:
        fail(f"{label} cannot be opened without following links: {exc}", state="BLOCKED_SCOPE")
    try:
        data, held_stat = read_held_regular_fd(fd, label, maximum_bytes=maximum_bytes)
        directory_stat = os.fstat(directory_fd)
        path_stat = os.stat(basename, dir_fd=directory_fd, follow_symlinks=False)
        require(
            held_stat.st_dev == directory_stat.st_dev
            and (held_stat.st_dev, held_stat.st_ino)
            == (path_stat.st_dev, path_stat.st_ino)
            and (
                expected_mode is None
                or stat.S_IMODE(held_stat.st_mode) == expected_mode
            ),
            f"{label} descriptor/path/device drift",
            state="BLOCKED_SCOPE",
        )
        return data
    finally:
        os.close(fd)


def _decode_transaction_journal_snapshot(
    data: bytes,
    transaction_id: str,
    label: str,
) -> list[dict[str, Any]]:
    try:
        value = json.loads(
            data.decode("utf-8"),
            object_pairs_hook=duplicate_guard,
            parse_constant=reject_json_constant,
        )
    except (UnicodeError, json.JSONDecodeError) as exc:
        fail(f"{label} is invalid JSON: {exc}")
    require(isinstance(value, dict), f"{label} is not an object")
    exact_keys(value, {"entries"}, label)
    require(data == canonical_json_bytes(value), f"{label} is not canonical JSON")
    return validate_descriptor_transaction_journal(value["entries"], transaction_id)


def read_persistent_descriptor_transaction_journal(
    parent_raw: Union[str, Path],
    journal_basename: str,
    transaction_id: str,
) -> list[dict[str, Any]]:
    journal_basename = validate_plain_basename(journal_basename, "transaction journal")
    parent, parent_fd, _ = open_canonical_directory(parent_raw, "transaction journal parent")
    del parent
    try:
        data = _read_regular_at(
            parent_fd,
            journal_basename,
            "transaction journal",
            maximum_bytes=1024 * 1024,
            expected_mode=0o600,
        )
        return [] if data is None else _decode_transaction_journal_snapshot(
            data,
            transaction_id,
            "transaction journal",
        )
    finally:
        os.close(parent_fd)


def _transaction_journal_temp_basename(journal_basename: str, transaction_id: str) -> str:
    temp_basename = f".{journal_basename}.{transaction_id}.next"
    require(len(os.fsencode(temp_basename)) <= 255, "transaction journal temporary basename too long")
    return validate_plain_basename(temp_basename, "transaction journal temporary file")


def _write_all(fd: int, data: bytes, label: str) -> None:
    offset = 0
    while offset < len(data):
        try:
            written = os.write(fd, data[offset:])
        except OSError as exc:
            fail(f"{label} write failed: {exc}", state="BLOCKED_SCOPE")
        require(written > 0, f"{label} write made no progress", state="BLOCKED_SCOPE")
        offset += written


def advance_persistent_descriptor_transaction_journal(
    parent_raw: Union[str, Path],
    journal_basename: str,
    transaction_id: str,
    state_name: str,
    payload_sha256: str,
    *,
    clock: Callable[[], Union[str, dt.datetime]],
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]] = None,
) -> list[dict[str, Any]]:
    """Durably append one exact state, recovering an already-fsynced snapshot."""

    journal_basename = validate_plain_basename(journal_basename, "transaction journal")
    validate_descriptor_transaction_journal([], transaction_id)
    temp_basename = _transaction_journal_temp_basename(journal_basename, transaction_id)
    parent, parent_fd, _ = open_canonical_directory(parent_raw, "transaction journal parent")
    del parent
    try:
        current_data = _read_regular_at(
            parent_fd,
            journal_basename,
            "transaction journal",
            maximum_bytes=1024 * 1024,
            expected_mode=0o600,
        )
        current = [] if current_data is None else _decode_transaction_journal_snapshot(
            current_data,
            transaction_id,
            "transaction journal",
        )
        temp_data = _read_regular_at(
            parent_fd,
            temp_basename,
            "transaction journal pending snapshot",
            maximum_bytes=1024 * 1024,
            expected_mode=0o600,
        )
        if current and current[-1]["state"] == state_name:
            require(
                current[-1]["payload_sha256"] == payload_sha256,
                "idempotent journal replay payload drift",
            )
            if temp_data is not None:
                pending = _decode_transaction_journal_snapshot(
                    temp_data,
                    transaction_id,
                    "transaction journal pending snapshot",
                )
                require(pending == current, "stale journal temporary snapshot conflicts with committed state")
                os.unlink(temp_basename, dir_fd=parent_fd)
                os.fsync(parent_fd)
            return current
        expected_index = len(current)
        require(
            expected_index < len(DESCRIPTOR_TRANSACTION_STATES)
            and state_name == DESCRIPTOR_TRANSACTION_STATES[expected_index],
            "persistent transaction journal transition is not the exact next state",
        )
        if temp_data is not None:
            desired = _decode_transaction_journal_snapshot(
                temp_data,
                transaction_id,
                "transaction journal pending snapshot",
            )
            require(
                desired[:-1] == current
                and len(desired) == len(current) + 1
                and desired[-1]["state"] == state_name
                and desired[-1]["payload_sha256"] == payload_sha256,
                "pending transaction journal snapshot is not the exact resumable transition",
            )
            desired_data = temp_data
        else:
            desired = append_descriptor_transaction_journal_entry(
                current,
                transaction_id,
                state_name,
                payload_sha256,
                clock=clock,
            )
            desired_data = canonical_json_bytes({"entries": desired})
            flags = (
                os.O_WRONLY
                | os.O_CREAT
                | os.O_EXCL
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0)
            )
            try:
                temp_fd = os.open(temp_basename, flags, 0o600, dir_fd=parent_fd)
            except OSError as exc:
                fail(f"transaction journal temporary create failed: {exc}", state="BLOCKED_SCOPE")
            try:
                _write_all(temp_fd, desired_data, "transaction journal")
                os.fsync(temp_fd)
                temp_stat = os.fstat(temp_fd)
                require(
                    stat.S_ISREG(temp_stat.st_mode)
                    and temp_stat.st_nlink == 1
                    and stat.S_IMODE(temp_stat.st_mode) == 0o600,
                    "transaction journal temporary file identity/mode drift",
                    state="BLOCKED_SCOPE",
                )
            finally:
                os.close(temp_fd)
            os.fsync(parent_fd)
            invoke_transaction_crash_hook(
                crash_hook,
                "JOURNAL_TEMP_SYNCED",
                {"state": state_name, "snapshot_sha256": sha256_bytes(desired_data)},
            )
        pending_before_publish = _read_regular_at(
            parent_fd,
            temp_basename,
            "transaction journal pending snapshot",
            maximum_bytes=1024 * 1024,
            expected_mode=0o600,
        )
        require(
            pending_before_publish == desired_data,
            "transaction journal pending snapshot changed before publish",
            state="BLOCKED_SCOPE",
        )
        try:
            os.rename(
                temp_basename,
                journal_basename,
                src_dir_fd=parent_fd,
                dst_dir_fd=parent_fd,
            )
            os.fsync(parent_fd)
        except OSError as exc:
            fail(f"transaction journal publish/fsync failed: {exc}", state="BLOCKED_SCOPE")
        committed_data = _read_regular_at(
            parent_fd,
            journal_basename,
            "committed transaction journal",
            maximum_bytes=1024 * 1024,
            expected_mode=0o600,
        )
        require(
            committed_data == desired_data,
            "committed transaction journal changed during publish",
            state="BLOCKED_SCOPE",
        )
        invoke_transaction_crash_hook(
            crash_hook,
            "JOURNAL_COMMITTED",
            {"state": state_name, "entry_sha256": desired[-1]["entry_sha256"]},
        )
        return desired
    finally:
        os.close(parent_fd)


def _expected_flat_regular_output_rows_legacy(files: dict[str, bytes]) -> list[dict[str, Any]]:
    require(isinstance(files, dict) and files, "transaction output set is empty or invalid")
    rows: list[dict[str, Any]] = []
    for basename in sorted(files):
        validate_plain_basename(basename, "transaction output")
        data = files[basename]
        require(isinstance(data, bytes), f"transaction output is not bytes: {basename}")
        rows.append(
            {
                "basename": basename,
                "mode": 0o600,
                "size": len(data),
                "sha256": sha256_bytes(data),
            }
        )
    return rows


def validate_output_inventory_projection(
    context: dict[str, Any],
    expected_rows: list[dict[str, Any]],
    label: str,
) -> None:
    projection = [
        {
            "basename": row["basename"],
            "mode": row["mode"],
            "size": row["size"],
            "sha256": row["sha256"],
        }
        for row in context["manifest"]["file_rows"]
    ]
    require(projection == expected_rows, f"{label} output projection drift", state="BLOCKED_SCOPE")


def _publish_exact_regular_files_flat_legacy(
    parent_raw: Union[str, Path],
    staging_basename: str,
    published_basename: str,
    files: dict[str, bytes],
    *,
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]] = None,
) -> str:
    """Create, fsync, and atomically publish an exact flat output directory.

    A partial staging directory is resumed file by file.  An already-published
    directory is accepted only when every mode, size, and digest is exact.
    """

    staging_basename = validate_plain_basename(staging_basename, "transaction staging directory")
    published_basename = validate_plain_basename(published_basename, "transaction published directory")
    require(staging_basename != published_basename, "transaction staging/published alias")
    expected_rows = _expected_flat_regular_output_rows_legacy(files)
    bounds = {row["basename"]: max(1, row["size"]) for row in expected_rows}
    parent, parent_fd, parent_stat = open_canonical_directory(parent_raw, "transaction output parent")
    try:
        staging_stat = _statat_optional(parent_fd, staging_basename)
        published_stat = _statat_optional(parent_fd, published_basename)
        if published_stat is not None:
            require(staging_stat is None, "published output coexists with staging directory")
            os.close(parent_fd)
            parent_fd = -1
            context = open_exact_regular_file_inventory(
                parent / published_basename,
                bounds,
                "published transaction output",
            )
            try:
                validate_output_inventory_projection(context, expected_rows, "published transaction")
            finally:
                close_exact_regular_file_inventory(context)
            return "ALREADY_PUBLISHED"
        if staging_stat is None:
            try:
                os.mkdir(staging_basename, 0o700, dir_fd=parent_fd)
                os.fsync(parent_fd)
            except OSError as exc:
                fail(f"transaction staging directory create/fsync failed: {exc}", state="BLOCKED_SCOPE")
            invoke_transaction_crash_hook(
                crash_hook,
                "STAGING_DIRECTORY_CREATED",
                {"staging": staging_basename},
            )
        try:
            staging_fd = os.open(
                staging_basename,
                descriptor_open_flags(directory=True),
                dir_fd=parent_fd,
            )
        except OSError as exc:
            fail(f"transaction staging directory cannot be opened: {exc}", state="BLOCKED_SCOPE")
        try:
            staging_root_stat = os.fstat(staging_fd)
            staging_path_stat = os.stat(staging_basename, dir_fd=parent_fd, follow_symlinks=False)
            require(
                stat.S_ISDIR(staging_root_stat.st_mode)
                and staging_root_stat.st_dev == parent_stat.st_dev
                and stat.S_IMODE(staging_root_stat.st_mode) == 0o700
                and (staging_root_stat.st_dev, staging_root_stat.st_ino)
                == (staging_path_stat.st_dev, staging_path_stat.st_ino),
                "transaction staging directory identity/mode drift",
                state="BLOCKED_SCOPE",
            )
            expected_names = set(files)
            actual_names = set(os.listdir(staging_fd))
            require(
                actual_names <= expected_names,
                f"transaction staging directory has extra entries: {sorted(actual_names - expected_names)}",
                state="BLOCKED_SCOPE",
            )
            row_by_name = {row["basename"]: row for row in expected_rows}
            for basename in sorted(expected_names):
                row = row_by_name[basename]
                existing = _read_regular_at(
                    staging_fd,
                    basename,
                    f"transaction staging output/{basename}",
                    maximum_bytes=max(1, row["size"]),
                )
                if existing is not None:
                    existing_stat = os.stat(basename, dir_fd=staging_fd, follow_symlinks=False)
                    require(
                        stat.S_IMODE(existing_stat.st_mode) == row["mode"]
                        and existing_stat.st_size == row["size"]
                        and sha256_bytes(existing) == row["sha256"],
                        f"transaction staging output drift: {basename}",
                        state="BLOCKED_SCOPE",
                    )
                    continue
                flags = (
                    os.O_WRONLY
                    | os.O_CREAT
                    | os.O_EXCL
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_NOFOLLOW", 0)
                )
                try:
                    file_fd = os.open(basename, flags, 0o600, dir_fd=staging_fd)
                except OSError as exc:
                    fail(f"transaction staging output create failed: {basename}: {exc}", state="BLOCKED_SCOPE")
                try:
                    _write_all(file_fd, files[basename], f"transaction staging output/{basename}")
                    os.fsync(file_fd)
                    created_stat = os.fstat(file_fd)
                    require(
                        stat.S_ISREG(created_stat.st_mode)
                        and created_stat.st_nlink == 1
                        and created_stat.st_dev == staging_root_stat.st_dev
                        and stat.S_IMODE(created_stat.st_mode) == row["mode"],
                        f"transaction staging output identity/mode drift: {basename}",
                        state="BLOCKED_SCOPE",
                    )
                finally:
                    os.close(file_fd)
                os.fsync(staging_fd)
                invoke_transaction_crash_hook(
                    crash_hook,
                    "STAGING_FILE_SYNCED",
                    {"basename": basename, "sha256": row["sha256"]},
                )
            require(
                set(os.listdir(staging_fd)) == expected_names,
                "transaction staging output set incomplete after resume",
            )
            os.fsync(staging_fd)
            os.fsync(parent_fd)
            invoke_transaction_crash_hook(
                crash_hook,
                "OUTPUTS_SYNCED",
                {"output_manifest_sha256": sha256_bytes(canonical_json_bytes(expected_rows))},
            )
        finally:
            os.close(staging_fd)
        try:
            os.rename(
                staging_basename,
                published_basename,
                src_dir_fd=parent_fd,
                dst_dir_fd=parent_fd,
            )
            os.fsync(parent_fd)
        except OSError as exc:
            fail(f"transaction output publish/fsync failed: {exc}", state="BLOCKED_SCOPE")
        invoke_transaction_crash_hook(
            crash_hook,
            "PUBLISHED",
            {"published": published_basename},
        )
        return "PUBLISHED"
    finally:
        if parent_fd >= 0:
            os.close(parent_fd)


def canonical_relative_regular_path(value: Any, label: str) -> tuple[str, ...]:
    require(
        isinstance(value, str)
        and value
        and not value.startswith("/")
        and not value.endswith("/")
        and "//" not in value
        and "\\" not in value
        and "\x00" not in value,
        f"{label} is not a canonical relative path",
        state="BLOCKED_SCOPE",
    )
    parts = tuple(value.split("/"))
    for part in parts:
        validate_plain_basename(part, label)
    require(
        "/".join(parts) == value and posixpath.normpath(value) == value,
        f"{label} relative path normalization drift",
        state="BLOCKED_SCOPE",
    )
    return parts


def expected_regular_tree_contract(files: dict[str, bytes]) -> dict[str, Any]:
    require(isinstance(files, dict) and files, "transaction output tree is empty or invalid")
    normalized_files: dict[str, bytes] = {}
    directories: set[str] = set()
    for relative_path, data in files.items():
        parts = canonical_relative_regular_path(relative_path, "transaction output path")
        require(isinstance(data, bytes), f"transaction output is not bytes: {relative_path}")
        normalized = "/".join(parts)
        require(normalized not in normalized_files, f"duplicate transaction output path: {normalized}")
        normalized_files[normalized] = data
        for depth in range(1, len(parts)):
            directories.add("/".join(parts[:depth]))
    require(
        not (directories & set(normalized_files)),
        "transaction output path is both a file and a directory",
    )
    rows: list[dict[str, Any]] = []
    for relative_path in directories:
        rows.append(
            {
                "relative_path": relative_path,
                "entry_kind": "DIRECTORY",
                "mode": 0o700,
                "size": None,
                "sha256": None,
            }
        )
    for relative_path, data in normalized_files.items():
        rows.append(
            {
                "relative_path": relative_path,
                "entry_kind": "REGULAR_FILE",
                "mode": 0o600,
                "size": len(data),
                "sha256": sha256_bytes(data),
            }
        )
    rows.sort(key=lambda row: row["relative_path"])
    return {
        "files": normalized_files,
        "directories": directories,
        "rows": rows,
        "manifest_sha256": sha256_bytes(canonical_json_bytes(rows)),
    }


def _open_owned_transaction_tree_root_at(
    parent_fd: int,
    basename: str,
    parent_device: int,
    label: str,
) -> tuple[int, os.stat_result]:
    try:
        root_fd = os.open(basename, descriptor_open_flags(directory=True), dir_fd=parent_fd)
    except OSError as exc:
        fail(f"{label} cannot be opened without following links: {exc}", state="BLOCKED_SCOPE")
    try:
        held_stat = os.fstat(root_fd)
        path_stat = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
        require(
            stat.S_ISDIR(held_stat.st_mode)
            and held_stat.st_dev == parent_device
            and held_stat.st_uid == os.geteuid()
            and stat.S_IMODE(held_stat.st_mode) == 0o700
            and (held_stat.st_dev, held_stat.st_ino)
            == (path_stat.st_dev, path_stat.st_ino),
            f"{label} identity/owner/mode/device drift",
            state="BLOCKED_SCOPE",
        )
        return root_fd, held_stat
    except BaseException:
        os.close(root_fd)
        raise


def _open_relative_transaction_directory(
    root_fd: int,
    root_device: int,
    relative_directory: str,
    label: str,
) -> int:
    current_fd = os.dup(root_fd)
    try:
        if not relative_directory:
            return current_fd
        parts = canonical_relative_regular_path(relative_directory, label)
        for part in parts:
            try:
                next_fd = os.open(part, descriptor_open_flags(directory=True), dir_fd=current_fd)
            except OSError as exc:
                fail(f"{label} cannot open directory component {part}: {exc}", state="BLOCKED_SCOPE")
            try:
                held_stat = os.fstat(next_fd)
                path_stat = os.stat(part, dir_fd=current_fd, follow_symlinks=False)
                require(
                    stat.S_ISDIR(held_stat.st_mode)
                    and held_stat.st_dev == root_device
                    and held_stat.st_uid == os.geteuid()
                    and stat.S_IMODE(held_stat.st_mode) == 0o700
                    and (held_stat.st_dev, held_stat.st_ino)
                    == (path_stat.st_dev, path_stat.st_ino),
                    f"{label} directory identity/owner/mode/device drift: {part}",
                    state="BLOCKED_SCOPE",
                )
            except BaseException:
                os.close(next_fd)
                raise
            os.close(current_fd)
            current_fd = next_fd
        return current_fd
    except BaseException:
        os.close(current_fd)
        raise


def _validate_transaction_tree_file_at(
    directory_fd: int,
    basename: str,
    expected_data: bytes,
    root_device: int,
    label: str,
) -> None:
    try:
        file_fd = os.open(basename, descriptor_open_flags(), dir_fd=directory_fd)
    except OSError as exc:
        fail(f"{label} cannot open regular file {basename}: {exc}", state="BLOCKED_SCOPE")
    try:
        data, held_stat = read_held_regular_fd(
            file_fd,
            f"{label}/{basename}",
            maximum_bytes=max(1, len(expected_data)),
        )
        path_stat = os.stat(basename, dir_fd=directory_fd, follow_symlinks=False)
        require(
            stat.S_ISREG(held_stat.st_mode)
            and held_stat.st_dev == root_device
            and held_stat.st_uid == os.geteuid()
            and held_stat.st_nlink == 1
            and stat.S_IMODE(held_stat.st_mode) == 0o600
            and (held_stat.st_dev, held_stat.st_ino)
            == (path_stat.st_dev, path_stat.st_ino)
            and held_stat.st_size == len(expected_data)
            and data == expected_data,
            f"{label} regular file identity/owner/mode/content drift: {basename}",
            state="BLOCKED_SCOPE",
        )
    finally:
        os.close(file_fd)


def _scan_exact_regular_tree(
    root_fd: int,
    root_stat: os.stat_result,
    contract: dict[str, Any],
    label: str,
    *,
    require_complete: bool,
) -> None:
    expected_directories = contract["directories"]
    expected_files = contract["files"]
    seen_directories: set[str] = set()
    seen_files: set[str] = set()

    def scan(directory_fd: int, parent_relative: str) -> None:
        for basename in sorted(os.listdir(directory_fd)):
            validate_plain_basename(basename, f"{label} entry")
            relative_path = f"{parent_relative}/{basename}" if parent_relative else basename
            path_stat = os.stat(basename, dir_fd=directory_fd, follow_symlinks=False)
            if relative_path in expected_directories:
                require(
                    stat.S_ISDIR(path_stat.st_mode),
                    f"{label} expected directory kind drift: {relative_path}",
                    state="BLOCKED_SCOPE",
                )
                try:
                    child_fd = os.open(
                        basename,
                        descriptor_open_flags(directory=True),
                        dir_fd=directory_fd,
                    )
                except OSError as exc:
                    fail(f"{label} cannot open directory {relative_path}: {exc}", state="BLOCKED_SCOPE")
                try:
                    held_stat = os.fstat(child_fd)
                    require(
                        held_stat.st_dev == root_stat.st_dev
                        and held_stat.st_uid == os.geteuid()
                        and stat.S_IMODE(held_stat.st_mode) == 0o700
                        and (held_stat.st_dev, held_stat.st_ino)
                        == (path_stat.st_dev, path_stat.st_ino),
                        f"{label} directory identity/owner/mode/device drift: {relative_path}",
                        state="BLOCKED_SCOPE",
                    )
                    seen_directories.add(relative_path)
                    scan(child_fd, relative_path)
                finally:
                    os.close(child_fd)
            elif relative_path in expected_files:
                require(
                    stat.S_ISREG(path_stat.st_mode),
                    f"{label} expected regular-file kind drift: {relative_path}",
                    state="BLOCKED_SCOPE",
                )
                _validate_transaction_tree_file_at(
                    directory_fd,
                    basename,
                    expected_files[relative_path],
                    root_stat.st_dev,
                    label,
                )
                seen_files.add(relative_path)
            else:
                fail(f"{label} contains unlisted tree entry: {relative_path}", state="BLOCKED_SCOPE")

    scan(root_fd, "")
    if require_complete:
        require(
            seen_directories == expected_directories
            and seen_files == set(expected_files),
            f"{label} tree is incomplete: missing_directories="
            f"{sorted(expected_directories - seen_directories)} missing_files="
            f"{sorted(set(expected_files) - seen_files)}",
            state="BLOCKED_SCOPE",
        )


def _ensure_exact_regular_tree_contents(
    root_fd: int,
    root_stat: os.stat_result,
    contract: dict[str, Any],
    *,
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]],
) -> None:
    _scan_exact_regular_tree(
        root_fd,
        root_stat,
        contract,
        "transaction staging tree",
        require_complete=False,
    )
    for relative_directory in sorted(
        contract["directories"],
        key=lambda value: (value.count("/") + 1, value),
    ):
        parts = relative_directory.split("/")
        parent_relative = "/".join(parts[:-1])
        basename = parts[-1]
        parent_fd = _open_relative_transaction_directory(
            root_fd,
            root_stat.st_dev,
            parent_relative,
            "transaction staging tree",
        )
        try:
            existing = _statat_optional(parent_fd, basename)
            if existing is None:
                try:
                    os.mkdir(basename, 0o700, dir_fd=parent_fd)
                    os.fsync(parent_fd)
                except OSError as exc:
                    fail(f"transaction staging directory create failed: {relative_directory}: {exc}")
                invoke_transaction_crash_hook(
                    crash_hook,
                    "STAGING_DIRECTORY_SYNCED",
                    {"relative_path": relative_directory},
                )
            child_fd = _open_relative_transaction_directory(
                root_fd,
                root_stat.st_dev,
                relative_directory,
                "transaction staging tree",
            )
            os.close(child_fd)
        finally:
            os.close(parent_fd)
    for relative_path in sorted(contract["files"]):
        parts = relative_path.split("/")
        parent_relative = "/".join(parts[:-1])
        basename = parts[-1]
        data = contract["files"][relative_path]
        parent_fd = _open_relative_transaction_directory(
            root_fd,
            root_stat.st_dev,
            parent_relative,
            "transaction staging tree",
        )
        try:
            existing = _statat_optional(parent_fd, basename)
            if existing is None:
                flags = (
                    os.O_WRONLY
                    | os.O_CREAT
                    | os.O_EXCL
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_NOFOLLOW", 0)
                )
                try:
                    file_fd = os.open(basename, flags, 0o600, dir_fd=parent_fd)
                except OSError as exc:
                    fail(f"transaction staging output create failed: {relative_path}: {exc}")
                try:
                    _write_all(file_fd, data, f"transaction staging output/{relative_path}")
                    os.fsync(file_fd)
                    created_stat = os.fstat(file_fd)
                    require(
                        stat.S_ISREG(created_stat.st_mode)
                        and created_stat.st_dev == root_stat.st_dev
                        and created_stat.st_uid == os.geteuid()
                        and created_stat.st_nlink == 1
                        and stat.S_IMODE(created_stat.st_mode) == 0o600,
                        f"transaction staging output identity/owner/mode drift: {relative_path}",
                        state="BLOCKED_SCOPE",
                    )
                finally:
                    os.close(file_fd)
                os.fsync(parent_fd)
                invoke_transaction_crash_hook(
                    crash_hook,
                    "STAGING_FILE_SYNCED",
                    {
                        "basename": basename,
                        "relative_path": relative_path,
                        "sha256": sha256_bytes(data),
                    },
                )
            _validate_transaction_tree_file_at(
                parent_fd,
                basename,
                data,
                root_stat.st_dev,
                "transaction staging tree",
            )
        finally:
            os.close(parent_fd)
    _scan_exact_regular_tree(
        root_fd,
        root_stat,
        contract,
        "transaction staging tree",
        require_complete=True,
    )


def _fsync_regular_tree_bottom_up(
    root_fd: int,
    root_stat: os.stat_result,
    directories: set[str],
) -> None:
    for relative_directory in sorted(
        directories,
        key=lambda value: (-(value.count("/") + 1), value),
    ):
        directory_fd = _open_relative_transaction_directory(
            root_fd,
            root_stat.st_dev,
            relative_directory,
            "transaction staging fsync",
        )
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    os.fsync(root_fd)


def stage_exact_regular_tree(
    parent_raw: Union[str, Path],
    staging_basename: str,
    files: dict[str, bytes],
    *,
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]] = None,
) -> str:
    """Durably stage one exact descriptor-relative tree without publishing."""

    staging_basename = validate_plain_basename(staging_basename, "transaction staging directory")
    contract = expected_regular_tree_contract(files)
    parent, parent_fd, parent_stat = open_canonical_directory(parent_raw, "transaction output parent")
    del parent
    root_fd: Optional[int] = None
    try:
        if _statat_optional(parent_fd, staging_basename) is None:
            try:
                os.mkdir(staging_basename, 0o700, dir_fd=parent_fd)
                os.fsync(parent_fd)
            except OSError as exc:
                fail(f"transaction staging root create/fsync failed: {exc}", state="BLOCKED_SCOPE")
            invoke_transaction_crash_hook(
                crash_hook,
                "STAGING_DIRECTORY_CREATED",
                {"staging": staging_basename},
            )
        root_fd, root_stat = _open_owned_transaction_tree_root_at(
            parent_fd,
            staging_basename,
            parent_stat.st_dev,
            "transaction staging root",
        )
        _ensure_exact_regular_tree_contents(
            root_fd,
            root_stat,
            contract,
            crash_hook=crash_hook,
        )
        _fsync_regular_tree_bottom_up(root_fd, root_stat, contract["directories"])
        os.fsync(parent_fd)
        invoke_transaction_crash_hook(
            crash_hook,
            "STAGED_DURABLE",
            {"output_manifest_sha256": contract["manifest_sha256"]},
        )
        return "STAGED_DURABLE"
    finally:
        if root_fd is not None:
            os.close(root_fd)
        os.close(parent_fd)


def publish_exact_staged_tree(
    parent_raw: Union[str, Path],
    staging_basename: str,
    published_basename: str,
    files: dict[str, bytes],
    *,
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]] = None,
) -> str:
    """Publish only a fully durable exact tree; accept exact replay only."""

    staging_basename = validate_plain_basename(staging_basename, "transaction staging directory")
    published_basename = validate_plain_basename(published_basename, "transaction published directory")
    require(staging_basename != published_basename, "transaction staging/published alias")
    contract = expected_regular_tree_contract(files)
    parent, parent_fd, parent_stat = open_canonical_directory(parent_raw, "transaction output parent")
    del parent
    root_fd: Optional[int] = None
    try:
        staging_stat = _statat_optional(parent_fd, staging_basename)
        published_stat = _statat_optional(parent_fd, published_basename)
        if published_stat is not None:
            require(staging_stat is None, "published output coexists with staging directory")
            root_fd, root_stat = _open_owned_transaction_tree_root_at(
                parent_fd,
                published_basename,
                parent_stat.st_dev,
                "published transaction root",
            )
            _scan_exact_regular_tree(
                root_fd,
                root_stat,
                contract,
                "published transaction tree",
                require_complete=True,
            )
            _fsync_regular_tree_bottom_up(root_fd, root_stat, contract["directories"])
            os.fsync(parent_fd)
            return "ALREADY_PUBLISHED"
        require(staging_stat is not None, "transaction staging tree is absent before publish")
        root_fd, root_stat = _open_owned_transaction_tree_root_at(
            parent_fd,
            staging_basename,
            parent_stat.st_dev,
            "transaction staging root",
        )
        _scan_exact_regular_tree(
            root_fd,
            root_stat,
            contract,
            "transaction staging tree",
            require_complete=True,
        )
        _fsync_regular_tree_bottom_up(root_fd, root_stat, contract["directories"])
        os.fsync(parent_fd)
        try:
            os.rename(
                staging_basename,
                published_basename,
                src_dir_fd=parent_fd,
                dst_dir_fd=parent_fd,
            )
            os.fsync(parent_fd)
        except OSError as exc:
            fail(f"transaction output publish/fsync failed: {exc}", state="BLOCKED_SCOPE")
        published_path_stat = os.stat(published_basename, dir_fd=parent_fd, follow_symlinks=False)
        require(
            (root_stat.st_dev, root_stat.st_ino)
            == (published_path_stat.st_dev, published_path_stat.st_ino),
            "published transaction root is not the held staged tree",
            state="BLOCKED_SCOPE",
        )
        _scan_exact_regular_tree(
            root_fd,
            root_stat,
            contract,
            "post-publish transaction tree",
            require_complete=True,
        )
        invoke_transaction_crash_hook(
            crash_hook,
            "PUBLISHED",
            {
                "published": published_basename,
                "output_manifest_sha256": contract["manifest_sha256"],
            },
        )
        return "PUBLISHED"
    finally:
        if root_fd is not None:
            os.close(root_fd)
        os.close(parent_fd)


def publish_exact_regular_tree(
    parent_raw: Union[str, Path],
    staging_basename: str,
    published_basename: str,
    files: dict[str, bytes],
    *,
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]] = None,
) -> str:
    staging_basename = validate_plain_basename(staging_basename, "transaction staging directory")
    published_basename = validate_plain_basename(published_basename, "transaction published directory")
    require(staging_basename != published_basename, "transaction staging/published alias")
    parent, parent_fd, _ = open_canonical_directory(parent_raw, "transaction output parent")
    try:
        published_exists = _statat_optional(parent_fd, published_basename) is not None
    finally:
        os.close(parent_fd)
    if not published_exists:
        stage_exact_regular_tree(
            parent,
            staging_basename,
            files,
            crash_hook=crash_hook,
        )
    return publish_exact_staged_tree(
        parent,
        staging_basename,
        published_basename,
        files,
        crash_hook=crash_hook,
    )


def publish_exact_regular_files(
    parent_raw: Union[str, Path],
    staging_basename: str,
    published_basename: str,
    files: dict[str, bytes],
    *,
    crash_hook: Optional[Callable[[str, dict[str, Any]], None]] = None,
) -> str:
    """Compatibility entry point; paths may now form a closed nested tree."""

    return publish_exact_regular_tree(
        parent_raw,
        staging_basename,
        published_basename,
        files,
        crash_hook=crash_hook,
    )


class DescriptorTransactionInjectedCrash(RuntimeError):
    pass


def self_test_descriptor_transaction_primitives() -> None:
    """Exercise descriptor, journal, tombstone, and replay fail-closed paths."""

    fixed_clock = lambda: dt.datetime(2026, 8, 17, 20, 0, 0, tzinfo=UTC)
    with tempfile.TemporaryDirectory(prefix="fc01-descriptor-transaction-") as raw_temp:
        temporary = Path(raw_temp).resolve()

        inventory_root = temporary / "inventory"
        inventory_root.mkdir(mode=0o700)
        (inventory_root / "a.bin").write_bytes(b"alpha")
        (inventory_root / "b.bin").write_bytes(b"beta")
        context = open_exact_regular_file_inventory(
            inventory_root,
            {"a.bin": 16, "b.bin": 16},
            "descriptor self-test inventory",
        )
        validate_held_regular_file_inventory(context, "descriptor self-test inventory")
        close_exact_regular_file_inventory(context)
        expect_failure(
            lambda: open_exact_regular_file_inventory(
                inventory_root,
                {"a.bin": 16},
                "descriptor omission self-test",
            ),
            "entry-set drift",
        )

        symlink_root = temporary / "symlink-inventory"
        symlink_root.mkdir(mode=0o700)
        (symlink_root / "target.bin").write_bytes(b"target")
        os.symlink("target.bin", symlink_root / "alias.bin")
        expect_failure(
            lambda: open_exact_regular_file_inventory(
                symlink_root,
                {"target.bin": 16, "alias.bin": 16},
                "descriptor symlink self-test",
            ),
            "without following links",
        )

        hardlink_root = temporary / "hardlink-inventory"
        hardlink_root.mkdir(mode=0o700)
        (hardlink_root / "one.bin").write_bytes(b"hardlink")
        os.link(hardlink_root / "one.bin", hardlink_root / "two.bin")
        expect_failure(
            lambda: open_exact_regular_file_inventory(
                hardlink_root,
                {"one.bin": 16, "two.bin": 16},
                "descriptor hardlink self-test",
            ),
            "identity/link/device drift",
        )

        mutation_root = temporary / "mutation-inventory"
        mutation_root.mkdir(mode=0o700)
        (mutation_root / "held.bin").write_bytes(b"before")
        mutation_context = open_exact_regular_file_inventory(
            mutation_root,
            {"held.bin": 16},
            "descriptor mutation self-test",
        )
        (mutation_root / "held.bin").write_bytes(b"after!")
        try:
            expect_failure(
                lambda: validate_held_regular_file_inventory(
                    mutation_context,
                    "descriptor mutation self-test",
                ),
                "identity or content drift",
            )
        finally:
            close_exact_regular_file_inventory(mutation_context)

        journal_root = temporary / "journal"
        journal_root.mkdir(mode=0o700)
        journal_payload = sha256_bytes(b"transaction-payload")
        crash_once = {"done": False}

        def journal_crash(checkpoint: str, details: dict[str, Any]) -> None:
            del details
            if checkpoint == "JOURNAL_TEMP_SYNCED" and not crash_once["done"]:
                crash_once["done"] = True
                raise DescriptorTransactionInjectedCrash(checkpoint)

        try:
            advance_persistent_descriptor_transaction_journal(
                journal_root,
                "transaction.json",
                "txn-self-test",
                "PREPARED",
                journal_payload,
                clock=fixed_clock,
                crash_hook=journal_crash,
            )
        except DescriptorTransactionInjectedCrash:
            pass
        else:
            fail("transaction journal crash hook was not reached")
        journal = advance_persistent_descriptor_transaction_journal(
            journal_root,
            "transaction.json",
            "txn-self-test",
            "PREPARED",
            journal_payload,
            clock=fixed_clock,
        )
        require(len(journal) == 1, "transaction journal did not resume its prepared snapshot")
        require(
            advance_persistent_descriptor_transaction_journal(
                journal_root,
                "transaction.json",
                "txn-self-test",
                "PREPARED",
                journal_payload,
                clock=fixed_clock,
            )
            == journal,
            "transaction journal idempotent replay drift",
        )
        for state_name in DESCRIPTOR_TRANSACTION_STATES[1:]:
            journal = advance_persistent_descriptor_transaction_journal(
                journal_root,
                "transaction.json",
                "txn-self-test",
                state_name,
                sha256_bytes(state_name.encode("ascii")),
                clock=fixed_clock,
            )
        require(
            read_persistent_descriptor_transaction_journal(
                journal_root,
                "transaction.json",
                "txn-self-test",
            )
            == journal,
            "transaction journal durable readback drift",
        )
        mutated_sequence = json.loads(json.dumps(journal))
        mutated_sequence[1]["sequence"] = 9
        expect_failure(
            lambda: validate_descriptor_transaction_journal(mutated_sequence, "txn-self-test"),
            "sequence/state drift",
        )
        mutated_chain = json.loads(json.dumps(journal))
        mutated_chain[1]["previous_entry_sha256"] = "0" * 64
        expect_failure(
            lambda: validate_descriptor_transaction_journal(mutated_chain, "txn-self-test"),
            "previous digest drift",
        )
        regressed_state = json.loads(json.dumps(journal))
        regressed_state[2]["state"] = "PREPARED"
        expect_failure(
            lambda: validate_descriptor_transaction_journal(regressed_state, "txn-self-test"),
            "sequence/state drift",
        )
        regressed_time = json.loads(json.dumps(journal))
        regressed_time[1]["recorded_at"] = "2026-08-17T19:59:59Z"
        expect_failure(
            lambda: validate_descriptor_transaction_journal(regressed_time, "txn-self-test"),
            "time regressed",
        )

        output_root = temporary / "output"
        output_root.mkdir(mode=0o700)
        output_files = {
            "02-source/one.json": b"{\"one\":1}\n",
            "09-terminal/two.json": b"{\"two\":2}\n",
        }
        output_crash_once = {"done": False}

        def output_crash(checkpoint: str, details: dict[str, Any]) -> None:
            if (
                checkpoint == "STAGING_FILE_SYNCED"
                and details["basename"] == "one.json"
                and not output_crash_once["done"]
            ):
                output_crash_once["done"] = True
                raise DescriptorTransactionInjectedCrash(checkpoint)

        try:
            publish_exact_regular_files(
                output_root,
                ".txn-stage",
                "published",
                output_files,
                crash_hook=output_crash,
            )
        except DescriptorTransactionInjectedCrash:
            pass
        else:
            fail("transaction output crash hook was not reached")
        (output_root / ".txn-stage" / "02-source" / "one.json").write_bytes(b"tampered\n")
        expect_failure(
            lambda: publish_exact_regular_files(
                output_root,
                ".txn-stage",
                "published",
                output_files,
            ),
            "staging tree regular file",
        )
        (output_root / ".txn-stage" / "02-source" / "one.json").write_bytes(
            output_files["02-source/one.json"]
        )
        require(
            publish_exact_regular_files(
                output_root,
                ".txn-stage",
                "published",
                output_files,
            )
            == "PUBLISHED",
            "transaction output did not resume and publish",
        )
        require(
            publish_exact_regular_files(
                output_root,
                ".txn-stage",
                "published",
                output_files,
            )
            == "ALREADY_PUBLISHED",
            "transaction output idempotent publish check drift",
        )
        require(
            all(
                (output_root / "published" / basename).read_bytes() == data
                for basename, data in output_files.items()
            ),
            "transaction output recovered tree is not byte-identical",
        )
        (output_root / "published" / "02-source" / "one.json").write_bytes(b"corrupt\n")
        expect_failure(
            lambda: publish_exact_regular_files(
                output_root,
                ".txn-stage",
                "published",
                output_files,
            ),
            "published transaction tree regular file",
        )

        tombstone_parent = temporary / "tombstone"
        tombstone_parent.mkdir(mode=0o700)
        tombstone_source = tombstone_parent / "inputs"
        tombstone_source.mkdir(mode=0o700)
        (tombstone_source / "a.bin").write_bytes(b"delete-a")
        (tombstone_source / "b.bin").write_bytes(b"delete-b")
        tombstone_context = open_exact_regular_file_inventory(
            tombstone_source,
            {"a.bin": 32, "b.bin": 32},
            "tombstone self-test inventory",
        )
        require(
            rename_held_inventory_to_tombstone(
                tombstone_context,
                ".txn-tombstone",
            )
            == "TOMBSTONED",
            "transaction tombstone rename did not execute",
        )
        require(
            reconcile_exact_inventory_location(
                tombstone_parent,
                "inputs",
                ".txn-tombstone",
                tombstone_context["manifest"],
            )
            == "TOMBSTONED",
            "transaction rename-before-journal recovery did not recognize its tombstone",
        )
        tombstone_crash_once = {"done": False}

        def tombstone_crash(checkpoint: str, details: dict[str, Any]) -> None:
            del details
            if checkpoint == "TOMBSTONE_FILE_UNLINKED" and not tombstone_crash_once["done"]:
                tombstone_crash_once["done"] = True
                raise DescriptorTransactionInjectedCrash(checkpoint)

        try:
            delete_exact_tombstoned_inventory(
                tombstone_parent,
                "inputs",
                ".txn-tombstone",
                tombstone_context["manifest"],
                allow_partial_resume=False,
                allow_already_absent=False,
                crash_hook=tombstone_crash,
            )
        except DescriptorTransactionInjectedCrash:
            pass
        else:
            fail("transaction tombstone crash hook was not reached")
        require(
            delete_exact_tombstoned_inventory(
                tombstone_parent,
                "inputs",
                ".txn-tombstone",
                tombstone_context["manifest"],
                allow_partial_resume=True,
                allow_already_absent=False,
            )
            == "DELETED",
            "transaction tombstone did not resume deletion",
        )
        require(
            delete_exact_tombstoned_inventory(
                tombstone_parent,
                "inputs",
                ".txn-tombstone",
                tombstone_context["manifest"],
                allow_partial_resume=True,
                allow_already_absent=True,
            )
            == "ALREADY_DELETED",
            "transaction tombstone idempotent deletion drift",
        )
        close_exact_regular_file_inventory(tombstone_context)

        boundary_parent = temporary / "delete-before-publish"
        boundary_parent.mkdir(mode=0o700)
        boundary_source = boundary_parent / "transient"
        boundary_source.mkdir(mode=0o700)
        (boundary_source / "observation.json").write_bytes(b"signed observation\n")
        boundary_context = open_exact_regular_file_inventory(
            boundary_source,
            {"observation.json": 64},
            "delete-before-publish input",
        )
        boundary_files = {
            "08-manifest/manifest.json": b"{\"status\":\"PASS\"}\n",
            "09-terminal/terminal.json": b"{\"result\":\"PASS\"}\n",
        }
        boundary_payload = expected_regular_tree_contract(boundary_files)["manifest_sha256"]
        boundary_journal_name = "boundary-transaction.json"
        boundary_transaction_id = "delete-before-publish-self-test"
        advance_persistent_descriptor_transaction_journal(
            boundary_parent,
            boundary_journal_name,
            boundary_transaction_id,
            "PREPARED",
            boundary_payload,
            clock=fixed_clock,
        )
        require(
            stage_exact_regular_tree(
                boundary_parent,
                ".boundary-stage",
                boundary_files,
            )
            == "STAGED_DURABLE",
            "delete-before-publish tree was not durably staged",
        )
        advance_persistent_descriptor_transaction_journal(
            boundary_parent,
            boundary_journal_name,
            boundary_transaction_id,
            "STAGED_DURABLE",
            boundary_payload,
            clock=fixed_clock,
        )
        rename_held_inventory_to_tombstone(
            boundary_context,
            ".boundary-tombstone",
        )
        advance_persistent_descriptor_transaction_journal(
            boundary_parent,
            boundary_journal_name,
            boundary_transaction_id,
            "INPUT_TOMBSTONED",
            boundary_context["manifest_sha256"],
            clock=fixed_clock,
        )
        delete_exact_tombstoned_inventory(
            boundary_parent,
            "transient",
            ".boundary-tombstone",
            boundary_context["manifest"],
            allow_partial_resume=False,
            allow_already_absent=False,
        )
        close_exact_regular_file_inventory(boundary_context)
        boundary_crash_once = {"done": False}

        def boundary_crash(checkpoint: str, details: dict[str, Any]) -> None:
            if (
                checkpoint == "JOURNAL_COMMITTED"
                and details["state"] == "INPUTS_DELETED"
                and not boundary_crash_once["done"]
            ):
                boundary_crash_once["done"] = True
                raise DescriptorTransactionInjectedCrash(checkpoint)

        try:
            advance_persistent_descriptor_transaction_journal(
                boundary_parent,
                boundary_journal_name,
                boundary_transaction_id,
                "INPUTS_DELETED",
                boundary_context["manifest_sha256"],
                clock=fixed_clock,
                crash_hook=boundary_crash,
            )
        except DescriptorTransactionInjectedCrash:
            pass
        else:
            fail("delete-before-publish crash hook was not reached")
        require(
            not boundary_source.exists()
            and not (boundary_parent / ".boundary-tombstone").exists()
            and (boundary_parent / ".boundary-stage").is_dir()
            and not (boundary_parent / "published").exists(),
            "delete-before-publish crash exposed output or lost durable staging",
        )
        require(
            read_persistent_descriptor_transaction_journal(
                boundary_parent,
                boundary_journal_name,
                boundary_transaction_id,
            )[-1]["state"]
            == "INPUTS_DELETED",
            "delete-before-publish crash did not durably record deletion",
        )
        require(
            publish_exact_staged_tree(
                boundary_parent,
                ".boundary-stage",
                "published",
                boundary_files,
            )
            == "PUBLISHED",
            "delete-before-publish resume did not publish staged bytes",
        )
        final_boundary_journal = advance_persistent_descriptor_transaction_journal(
            boundary_parent,
            boundary_journal_name,
            boundary_transaction_id,
            "PUBLISHED",
            boundary_payload,
            clock=fixed_clock,
        )
        require(
            len(final_boundary_journal) == len(DESCRIPTOR_TRANSACTION_STATES)
            and all(
                (boundary_parent / "published" / relative_path).read_bytes() == data
                for relative_path, data in boundary_files.items()
            ),
            "delete-before-publish recovery did not preserve the exact output tree",
        )


def derive_m00_pptx_package_facts(
    data: bytes,
    contract: dict[str, Any],
) -> dict[str, bool]:
    """Derive the two locally-authoritative PPTX facts from held bytes only.

    This parser intentionally uses only the Python standard library.  It does
    not render, execute macros, resolve an external relationship, or import a
    candidate module.  An invalid or ambiguous package produces false facts;
    archive-bomb bounds are checked before any member is decompressed.
    """

    facts = {fact_id: False for fact_id in contract["derived_fact_ids"]}
    require(
        set(facts) == {"PPTX_CONTAINER_VALID", "NATIVE_ARTIFACT_VALID"},
        "M00 sealed PPTX fact contract drift",
    )
    if not data or len(data) > contract["maximum_archive_bytes"]:
        return facts
    try:
        archive = zipfile.ZipFile(io.BytesIO(data), "r")
    except (OSError, ValueError, zipfile.BadZipFile):
        return facts
    try:
        infos = archive.infolist()
        if not infos or len(infos) > contract["maximum_entry_count"]:
            return facts
        eocd_offset = data.rfind(b"PK\x05\x06")
        if eocd_offset < 0 or eocd_offset + 22 != len(data):
            return facts
        (
            disk_number,
            central_disk,
            disk_entries,
            total_entries,
            central_size,
            central_offset,
            comment_length,
        ) = struct.unpack_from("<HHHHIIH", data, eocd_offset + 4)
        if (
            any((disk_number, central_disk, comment_length))
            or disk_entries != total_entries
            or total_entries != len(infos)
            or total_entries == 0xFFFF
            or central_size == 0xFFFFFFFF
            or central_offset == 0xFFFFFFFF
            or central_offset != archive.start_dir
            or central_offset + central_size != eocd_offset
        ):
            return facts
        names: list[str] = []
        normalized_names: set[str] = set()
        total_uncompressed = 0
        ranges: list[tuple[int, int, str]] = []
        for info in infos:
            name = info.filename
            if (
                not isinstance(name, str)
                or not name
                or "\\" in name
                or "\x00" in name
                or any(ord(char) < 32 or ord(char) == 127 for char in name)
                or name.startswith("/")
                or re.match(r"^[A-Za-z]:", name) is not None
            ):
                return facts
            path_parts = name.rstrip("/").split("/")
            if not path_parts or any(part in {"", ".", ".."} for part in path_parts):
                return facts
            normalized = posixpath.normpath(name.rstrip("/"))
            if normalized != name.rstrip("/") or normalized in normalized_names:
                return facts
            normalized_names.add(normalized)
            names.append(normalized)
            if info.flag_bits not in {0, 0x800} or info.compress_type not in {zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED}:
                return facts
            unix_mode = (info.external_attr >> 16) & 0xFFFF
            file_type = stat.S_IFMT(unix_mode)
            if file_type not in {0, stat.S_IFREG, stat.S_IFDIR}:
                return facts
            if info.is_dir() != name.endswith("/"):
                return facts
            if info.file_size > contract["maximum_single_entry_bytes"]:
                return facts
            total_uncompressed += info.file_size
            if total_uncompressed > contract["maximum_total_uncompressed_bytes"]:
                return facts
            if info.file_size:
                if info.compress_size <= 0:
                    return facts
                if info.file_size / info.compress_size > contract["maximum_compression_ratio"]:
                    return facts
            offset = info.header_offset
            if offset < 0 or offset + 30 > len(data) or data[offset:offset + 4] != b"PK\x03\x04":
                return facts
            local_flags, local_method = struct.unpack_from("<HH", data, offset + 6)
            local_crc, local_compressed, local_uncompressed = struct.unpack_from("<III", data, offset + 14)
            name_length, extra_length = struct.unpack_from("<HH", data, offset + 26)
            local_name_bytes = data[offset + 30:offset + 30 + name_length]
            try:
                local_name = local_name_bytes.decode("utf-8" if info.flag_bits & 0x800 else "cp437")
            except UnicodeError:
                return facts
            if (
                local_flags != info.flag_bits
                or local_method != info.compress_type
                or local_crc != info.CRC
                or local_compressed != info.compress_size
                or local_uncompressed != info.file_size
                or local_name != info.filename
                or 0xFFFFFFFF in {local_compressed, local_uncompressed}
            ):
                return facts
            payload_start = offset + 30 + name_length + extra_length
            payload_end = payload_start + info.compress_size
            if payload_start > payload_end or payload_end > archive.start_dir:
                return facts
            ranges.append((offset, payload_end, normalized))
        ordered_ranges = sorted(ranges)
        if any(left[1] > right[0] for left, right in zip(ordered_ranges, ordered_ranges[1:])):
            return facts
        central_cursor = central_offset
        for info in infos:
            if central_cursor + 46 > eocd_offset or data[central_cursor:central_cursor + 4] != b"PK\x01\x02":
                return facts
            central_flags, central_method = struct.unpack_from("<HH", data, central_cursor + 8)
            central_crc, central_compressed, central_uncompressed = struct.unpack_from("<III", data, central_cursor + 16)
            central_name_length, central_extra_length, central_comment_length = struct.unpack_from(
                "<HHH", data, central_cursor + 28,
            )
            central_disk_start = struct.unpack_from("<H", data, central_cursor + 34)[0]
            central_external_attr = struct.unpack_from("<I", data, central_cursor + 38)[0]
            central_local_offset = struct.unpack_from("<I", data, central_cursor + 42)[0]
            central_name_start = central_cursor + 46
            central_name_bytes = data[central_name_start:central_name_start + central_name_length]
            try:
                central_name = central_name_bytes.decode("utf-8" if central_flags & 0x800 else "cp437")
            except UnicodeError:
                return facts
            if (
                central_flags != info.flag_bits
                or central_flags not in {0, 0x800}
                or central_method != info.compress_type
                or central_crc != info.CRC
                or central_compressed != info.compress_size
                or central_uncompressed != info.file_size
                or central_name != info.filename
                or central_disk_start != 0
                or central_external_attr != info.external_attr
                or central_local_offset != info.header_offset
                or 0xFFFFFFFF in {
                    central_compressed, central_uncompressed, central_local_offset,
                }
            ):
                return facts
            central_cursor = (
                central_name_start + central_name_length
                + central_extra_length + central_comment_length
            )
        if central_cursor != eocd_offset:
            return facts
        name_set = set(names)
        if not set(contract["required_root_parts"]) <= name_set:
            return facts
        prohibited_suffixes = {
            ".bin", ".exe", ".dll", ".com", ".scr", ".bat", ".cmd",
            ".js", ".vbs", ".ps1", ".msi", ".jar", ".ocx",
        }
        if any(
            name.lower().startswith(("ppt/activex/", "ppt/embeddings/"))
            or any(name.lower().endswith(suffix) for suffix in prohibited_suffixes)
            for name in name_set
        ):
            return facts

        xml_roots: dict[str, ET.Element] = {}
        for info, normalized in zip(infos, names):
            if info.is_dir() or not (normalized.endswith(".xml") or normalized.endswith(".rels")):
                continue
            try:
                payload = archive.read(info)
            except (OSError, RuntimeError, zipfile.BadZipFile, zlib.error):
                return facts
            if len(payload) != info.file_size:
                return facts
            lowered = payload.lower()
            if any(marker in lowered for marker in (b"<!doctype", b"<!entity", b"xinclude", b"xi:include")):
                return facts
            declaration = re.match(br"\s*<\?xml[^>]*encoding\s*=\s*['\"]([^'\"]+)['\"]", payload, re.I)
            if declaration is not None and declaration.group(1).lower().replace(b"-", b"") != b"utf8":
                return facts
            try:
                xml_roots[normalized] = ET.fromstring(payload)
            except (ET.ParseError, ValueError, UnicodeError):
                return facts

        content_types = xml_roots.get("[Content_Types].xml")
        if content_types is None:
            return facts
        content_ns = "{http://schemas.openxmlformats.org/package/2006/content-types}"
        if content_types.tag != content_ns + "Types":
            return facts
        defaults: set[str] = set()
        overrides: set[str] = set()
        prohibited_content_type_tokens = (
            "macroenabled", "vbaproject", "activex", "oleobject",
            "ms-office.package", "executable",
        )
        for child in content_types:
            if child.tag == content_ns + "Default":
                extension = child.attrib.get("Extension", "").lower()
                content_type = child.attrib.get("ContentType", "")
                if (
                    not extension
                    or not content_type
                    or extension in defaults
                    or any(token in content_type.lower() for token in prohibited_content_type_tokens)
                ):
                    return facts
                defaults.add(extension)
            elif child.tag == content_ns + "Override":
                part_name = child.attrib.get("PartName", "")
                content_type = child.attrib.get("ContentType", "")
                normalized_part = posixpath.normpath(part_name.lstrip("/"))
                if (
                    not part_name.startswith("/")
                    or normalized_part not in name_set
                    or normalized_part in overrides
                    or not content_type
                    or any(token in content_type.lower() for token in prohibited_content_type_tokens)
                ):
                    return facts
                overrides.add(normalized_part)
            else:
                return facts
        for name in name_set - {"[Content_Types].xml"}:
            if name.endswith("/"):
                continue
            extension = name.rsplit(".", 1)[-1].lower() if "." in name else ""
            if name not in overrides and extension not in defaults:
                return facts

        relationship_ns = "{http://schemas.openxmlformats.org/package/2006/relationships}"
        relationships_by_owner: dict[str, dict[str, str]] = {}
        relationship_types_by_owner: dict[str, dict[str, str]] = {}
        prohibited_relationship_type_suffixes = (
            "/vbaproject", "/activexcontrol", "/activexcontrolbinary",
            "/oleobject", "/package",
        )
        for rel_path, root in xml_roots.items():
            if not rel_path.endswith(".rels"):
                continue
            if root.tag != relationship_ns + "Relationships":
                return facts
            if rel_path == "_rels/.rels":
                owner = ""
            else:
                parent, basename = posixpath.split(rel_path)
                if posixpath.basename(parent) != "_rels" or not basename.endswith(".rels"):
                    return facts
                owner = posixpath.join(posixpath.dirname(parent), basename[:-5])
                if owner not in name_set:
                    return facts
            ids: set[str] = set()
            resolved: dict[str, str] = {}
            resolved_types: dict[str, str] = {}
            for relationship in root:
                if relationship.tag != relationship_ns + "Relationship":
                    return facts
                rel_id = relationship.attrib.get("Id", "")
                rel_type = relationship.attrib.get("Type", "")
                target = relationship.attrib.get("Target", "")
                if not rel_id or rel_id in ids or not rel_type or not target:
                    return facts
                if any(rel_type.lower().endswith(suffix) for suffix in prohibited_relationship_type_suffixes):
                    return facts
                ids.add(rel_id)
                target_mode = relationship.attrib.get("TargetMode")
                if target_mode not in {None, "Internal", "External"}:
                    return facts
                resolved_types[rel_id] = rel_type
                if target_mode == "External":
                    continue
                if any(char in target for char in ("\\", "\x00", "?", "#")):
                    return facts
                base = posixpath.dirname(owner)
                resolved_target = posixpath.normpath(
                    target.lstrip("/") if target.startswith("/")
                    else posixpath.join(base, target)
                )
                if (
                    resolved_target.startswith("../")
                    or resolved_target in {"", ".", ".."}
                    or resolved_target not in name_set
                ):
                    return facts
                resolved[rel_id] = resolved_target
            relationships_by_owner[owner] = resolved
            relationship_types_by_owner[owner] = resolved_types
        if (
            "" not in relationships_by_owner
            or "ppt/presentation.xml" not in relationships_by_owner
            or "ppt/presentation.xml" not in relationships_by_owner[""].values()
        ):
            return facts
        root_presentation_ids = [
            rel_id for rel_id, target in relationships_by_owner[""].items()
            if target == "ppt/presentation.xml"
        ]
        if (
            len(root_presentation_ids) != 1
            or not relationship_types_by_owner[""][root_presentation_ids[0]].endswith("/officeDocument")
        ):
            return facts
        facts["PPTX_CONTAINER_VALID"] = True

        presentation = xml_roots.get("ppt/presentation.xml")
        if presentation is None:
            return facts
        presentation_ns = "{http://schemas.openxmlformats.org/presentationml/2006/main}"
        document_rel_ns = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}"
        slide_ids = presentation.findall(f".//{presentation_ns}sldId")
        slide_targets: list[str] = []
        for slide_id in slide_ids:
            rel_id = slide_id.attrib.get(document_rel_ns + "id")
            target = relationships_by_owner["ppt/presentation.xml"].get(rel_id or "")
            if (
                target is None
                or not target.startswith("ppt/slides/slide")
                or not target.endswith(".xml")
                or not relationship_types_by_owner["ppt/presentation.xml"].get(rel_id or "", "").endswith("/slide")
            ):
                return facts
            slide_targets.append(target)
        if not slide_targets or len(slide_targets) != len(set(slide_targets)):
            return facts
        for slide_target in slide_targets:
            if slide_target not in xml_roots or slide_target not in relationships_by_owner:
                return facts
            layouts = {
                target for rel_id, target in relationships_by_owner[slide_target].items()
                if target.startswith("ppt/slideLayouts/")
                and target.endswith(".xml")
                and relationship_types_by_owner[slide_target].get(rel_id, "").endswith("/slideLayout")
            }
            if not layouts:
                return facts
            for layout in layouts:
                masters = {
                    target for rel_id, target in relationships_by_owner.get(layout, {}).items()
                    if target.startswith("ppt/slideMasters/")
                    and target.endswith(".xml")
                    and relationship_types_by_owner.get(layout, {}).get(rel_id, "").endswith("/slideMaster")
                }
                if not masters:
                    return facts
                for master in masters:
                    themes = {
                        target for rel_id, target in relationships_by_owner.get(master, {}).items()
                        if target.startswith("ppt/theme/")
                        and target.endswith(".xml")
                        and relationship_types_by_owner.get(master, {}).get(rel_id, "").endswith("/theme")
                    }
                    if not themes:
                        return facts
        facts["NATIVE_ARTIFACT_VALID"] = True
        return facts
    finally:
        archive.close()


def validate_m00_transient_capture_attestation(
    value: dict[str, Any],
    finalizer_contract: dict[str, Any],
    trust_contract: dict[str, Any],
    trust_context: dict[str, Any],
    *,
    consumed_at: dt.datetime,
    finalizer_started_at: dt.datetime,
) -> dict[str, Any]:
    """Verify the frozen whole-capture signature and every source envelope."""

    transient = finalizer_contract["transient_observation_bundle_contract"]
    attestation = value["capture_attestation"]
    exact_keys(
        attestation,
        transient["capture_attestation_exact_fields"],
        "M00 transient capture attestation",
    )
    capture_started = parse_m00_deterministic_time(
        value["capture_started_at"], "M00 transient capture_started_at",
    )
    capture_ended = parse_m00_deterministic_time(
        value["capture_ended_at"], "M00 transient capture_ended_at",
    )
    signed_at = parse_m00_deterministic_time(
        attestation["signed_at"], "M00 transient signed_at",
    )
    require(
        capture_started == consumed_at
        and capture_started < capture_ended <= signed_at <= finalizer_started_at,
        "M00 transient capture interval/signing chronology drift",
    )
    aggregate = trust_context["aggregate"]
    require(
        exact_nonnegative_int(attestation["whole_capture_attester_sequence"])
        and attestation["whole_capture_attester_sequence"] > 0
        and attestation["whole_capture_attester_sequence"] == aggregate["sequence"]
        and attestation["attester_id"] == aggregate["attester_id"]
        and attestation["attestation_key_id"] == aggregate["attestation_key_id"]
        and attestation["attestation_algorithm"] == trust_contract["attestation_algorithm"],
        "M00 transient capture signer/algorithm drift",
    )
    valid_from = parse_time(aggregate["valid_from"], "M00 capture key valid_from")
    valid_through = parse_time(aggregate["valid_through"], "M00 capture key valid_through")
    require(valid_from <= signed_at <= valid_through, "M00 capture signature lies outside key validity")

    envelope_ids: set[str] = set()
    component_slots: set[str] = set()
    allowed_attesters = set(aggregate["covered_attester_sequences"])
    for index, export in enumerate(value["source_exports"]):
        label = f"M00 signed source envelope {index}"
        attester_sequence = export["source_attester_sequence"]
        require(
            exact_nonnegative_int(attester_sequence)
            and attester_sequence in allowed_attesters
            and attester_sequence in trust_context["by_sequence"],
            f"{label} selects an unauthorized attester",
        )
        authorized = trust_context["by_sequence"][attester_sequence]
        require(
            authorized["source_domain"] == export["source_domain"]
            and authorized["source_key_or_class"] == export["source_key"],
            f"{label} domain/key authorization drift",
        )
        slot = export["component_source_slot_id"]
        group = export["provider_receipt_projection_group_id"]
        if export["source_domain"] == "COMPONENT_SOURCE":
            require(
                isinstance(slot, str)
                and slot in authorized["component_source_slot_ids"]
                and slot not in component_slots,
                f"{label} component slot is absent, duplicated, or unauthorized",
            )
            component_slots.add(slot)
        else:
            require(slot is None, f"{label} noncomponent source carries a component slot")
        if export["result"] == "UNAVAILABLE":
            require(group is None, f"{label} unavailable source carries a projection group")
        elif group is None:
            require(
                not authorized["provider_receipt_projection_group_ids"],
                f"{label} omits its authorized provider projection group",
            )
        else:
            require(
                isinstance(group, str)
                and group in authorized["provider_receipt_projection_group_ids"],
                f"{label} provider projection group is unauthorized",
            )
        projection = [
            "FC01_M00_SIGNED_SOURCE_ENVELOPE_V1",
            export["source_domain"],
            export["source_key"],
            slot,
            attester_sequence,
            export["observer_mode"],
            export["started_at"],
            export["ended_at"],
            export["observed_event_count"],
            export["opaque_identity_aliases"],
            export["minimized_fact_rows"],
            export["opaque_provider_receipt_id"],
            export["opaque_provider_receipt_sha256"],
            group,
            export["provider_receipt_null_reason"],
            export["sealed_local_observer_ref"],
            export["failure_signal_code"],
            export["unavailable_reason"],
            export["result"],
            export["status"],
            export["raw_content_present"],
        ]
        expected_envelope_sha = sha256_bytes(canonical_json_bytes(projection))
        require(
            export["source_envelope_sha256"] == expected_envelope_sha
            and export["source_envelope_id"] == expected_envelope_sha
            and expected_envelope_sha not in envelope_ids,
            f"{label} ID/digest formula drift or duplicate envelope",
        )
        envelope_ids.add(expected_envelope_sha)

    signature_contract = trust_contract["capture_signature_contract"]
    signed_projection = [
        signature_contract["message_domain"],
        attestation["whole_capture_attester_sequence"],
        attestation["attester_id"],
        attestation["attestation_key_id"],
        attestation["attestation_algorithm"],
        attestation["signed_at"],
        value["d2_consumption_ref"],
        value["candidate_sha"],
        value["candidate_tree"],
        value["attempt_id"],
        value["synthetic_scope_alias"],
        value["capture_started_at"],
        value["capture_ended_at"],
        value["source_exports"],
        value["lifecycle_event_exports"],
    ]
    signed_bytes = canonical_json_bytes(signed_projection)
    require(
        attestation["signed_projection_sha256"] == sha256_bytes(signed_bytes),
        "M00 transient signed projection digest drift",
    )
    require(
        verify_rsa_pss_sha256_signature_hex_key(
            signed_bytes,
            attestation["signature_base64url"],
            aggregate["rsa_modulus_hex"],
            aggregate["rsa_public_exponent"],
            "M00 transient capture signature",
        ),
        "M00 transient capture RSA-PSS signature invalid",
    )
    return {
        "capture_started": capture_started,
        "capture_ended": capture_ended,
        "signed_at": signed_at,
        "signed_projection": signed_projection,
        "signed_projection_sha256": attestation["signed_projection_sha256"],
    }


def validate_m00_transient_observation_bundle_value(
    value: dict[str, Any],
    finalizer_contract: dict[str, Any],
    runtime_contract: dict[str, Any],
    component_contract: dict[str, Any],
    *,
    schema: Optional[dict[str, Any]] = None,
    expected_implementation_ref: Optional[dict[str, Any]] = None,
    expected_d2_consumption_ref: Optional[dict[str, Any]] = None,
    expected_candidate: Optional[tuple[str, str]] = None,
    expected_synthetic_scope_alias: Optional[str] = None,
    call_budget: Optional[dict[str, Any]] = None,
    spend_budget: Optional[dict[str, Any]] = None,
    expected_effects: Optional[dict[str, Any]] = None,
    trust_contract: Optional[dict[str, Any]] = None,
    trust_context: Optional[dict[str, Any]] = None,
    consumed_at: Optional[dt.datetime] = None,
    finalizer_started_at: Optional[dt.datetime] = None,
    held_initial_artifact_sha256: Optional[str] = None,
    held_final_artifact_sha256: Optional[str] = None,
    held_final_artifact_facts: Optional[dict[str, bool]] = None,
) -> dict[str, Any]:
    """Validate and normalize the privacy-minimized M00 finalizer input.

    The transient file is the last place where the authenticated source result,
    observer mode, and per-fact execution prefix exist together.  Validate those
    facts here and return only deterministic projections used by the emitter;
    never let the emitter infer a PASS, event boundary, or identity from an
    aggregate supplied by the caller.
    """

    transient = finalizer_contract["transient_observation_bundle_contract"]
    exact_keys(value, transient["top_level_exact_fields"], "M00 transient observation bundle")
    require(
        schema is not None
        and call_budget is not None
        and spend_budget is not None
        and expected_effects is not None
        and trust_contract is not None
        and trust_context is not None
        and consumed_at is not None
        and finalizer_started_at is not None
        and expected_d2_consumption_ref is not None
        and expected_candidate is not None
        and expected_synthetic_scope_alias is not None,
        "M00 transient validation lacks complete frozen D2/candidate/trust context",
    )
    require(
        isinstance(value["candidate_sha"], str)
        and HEX40_RE.fullmatch(value["candidate_sha"]) is not None
        and isinstance(value["candidate_tree"], str)
        and HEX40_RE.fullmatch(value["candidate_tree"]) is not None,
        "M00 transient candidate identity invalid",
    )
    require(
        value["d2_consumption_ref"] == expected_d2_consumption_ref
        and (value["candidate_sha"], value["candidate_tree"]) == expected_candidate
        and value["synthetic_scope_alias"] == expected_synthetic_scope_alias,
        "M00 transient D2 consumption/candidate/synthetic-scope binding drift",
    )
    require(
        (expected_effects["candidate_sha"], expected_effects["candidate_tree"])
        == expected_candidate
        and expected_effects["synthetic_scope_alias"] == expected_synthetic_scope_alias,
        "M00 transient expected-effect authority is not bound to the D2 attempt",
    )
    expected_attempt_id = sha256_bytes(canonical_json_bytes([
        1,
        AMENDMENT_ID,
        expected_d2_consumption_ref["path"],
        expected_d2_consumption_ref["sha256"],
        expected_candidate[0],
        expected_candidate[1],
    ]))
    require(value["attempt_id"] == expected_attempt_id, "M00 transient attempt identity drift")
    exports = value["source_exports"]
    require(isinstance(exports, list) and exports, "M00 transient source exports are empty")
    for index, export in enumerate(exports):
        require(isinstance(export, dict), f"M00 transient source export {index} is not an object")
        exact_keys(
            export,
            transient["source_export_exact_fields"],
            f"M00 transient source export {index}",
        )
    lifecycle_exports = value["lifecycle_event_exports"]
    require(
        isinstance(lifecycle_exports, list) and lifecycle_exports,
        "M00 transient lifecycle exports are empty",
    )
    for index, event in enumerate(lifecycle_exports):
        require(isinstance(event, dict), f"M00 transient lifecycle export {index} is not an object")
        exact_keys(
            event,
            transient["lifecycle_event_export_exact_fields"],
            f"M00 transient lifecycle export {index}",
        )
    capture_context = validate_m00_transient_capture_attestation(
        value,
        finalizer_contract,
        trust_contract,
        trust_context,
        consumed_at=consumed_at,
        finalizer_started_at=finalizer_started_at,
    )
    provider_tuple_groups: dict[tuple[str, str], Optional[str]] = {}
    projection_group_tuples: dict[str, tuple[str, str]] = {}
    native_keys: list[str] = []
    native_exports: dict[str, dict[str, Any]] = {}
    native_aliases_by_class: dict[str, tuple[str, str]] = {}
    identity_claims_by_class: dict[str, list[dict[str, Any]]] = {
        identity_class: [] for identity_class in runtime_contract["required_identity_classes"]
    }
    identity_projection_conflict = False
    fact_values_by_export: dict[int, dict[str, Any]] = {}
    fact_results_by_export: dict[int, dict[str, str]] = {}
    call_coverage_export_indices: list[int] = []
    export_results: list[str] = []
    missing_export_seen = False
    identity_classes = set(runtime_contract["required_identity_classes"])
    generic_contracts = transient["generic_fact_ids_by_source_domain"]
    generic_types = transient["generic_fact_value_type_by_fact_id"]
    component_specs = [
        spec
        for specs in component_contract["required_source_contract_by_category"].values()
        for spec in specs
    ] + [
        spec
        for specs in component_contract.get("optional_source_contract_by_category", {}).values()
        for spec in specs
    ]
    value_fields = {
        "BOOLEAN": "boolean_value",
        "INTEGER": "integer_value",
        "NUMBER": "number_value",
        "CLOSED_TOKEN": "token_value",
        "SHA256": "sha256_value",
    }

    def valid_closed_token(token: Any, label: str) -> None:
        require(
            isinstance(token, str)
            and 1 <= len(token) <= 160
            and token.strip() == token
            and not any(ord(char) < 32 or ord(char) == 127 for char in token)
            and "://" not in token
            and "=" not in token
            and not re.search(r"(?i)(password|secret|token|credential|api[_-]?key)\s*[:=]", token),
            f"{label} is not a closed privacy-safe token",
        )

    component_source_contract = (
        schema["supporting_receipt_contracts"]["m00_component_source_observation"]
        if schema is not None else None
    )
    effect_coverage_contract = (
        schema["supporting_receipt_contracts"]["m00_effect_observer_coverage"]
        if schema is not None else None
    )
    domain_rank = {
        domain: index for index, domain in enumerate(runtime_contract["source_domain_values"])
    }
    prior_domain_rank = -1
    signed_local_keys = set(transient["signed_sealed_local_component_source_keys"])
    optional_component_slot_ids = {
        slot["source_slot_id"]
        for slots in component_contract["component_source_slots_by_category"].values()
        for slot in slots
        if not slot["required"]
    }
    component_source_keys = {
        slot["source_system"]
        for slots in component_contract["component_source_slots_by_category"].values()
        for slot in slots
    }
    allowed_source_keys_by_domain = {
        "NATIVE_LIFECYCLE": set(runtime_contract["required_native_lifecycle_source_keys"]),
        "CALL_SOURCE_COVERAGE": {"CROSS_SYSTEM_TOOL_MODEL_CALL_COVERAGE"},
        "COMPONENT_SOURCE": component_source_keys,
        "CALL_EVENT": set(call_budget["call_categories"][index]["category"] for index in range(len(call_budget["call_categories"]))),
        "EFFECT_SOURCE_COVERAGE": set(effect_coverage_contract["required_source_classes"]),
        "EFFECT_EVENT": set(effect_coverage_contract["effect_category_to_source_class"]),
    }

    for index, export in enumerate(exports):
        label = f"M00 transient source export {index}"
        exact_keys(export, transient["source_export_exact_fields"], label)
        require(
            export["source_domain"] in runtime_contract["source_domain_values"]
            and isinstance(export["source_key"], str)
            and export["source_key"] in allowed_source_keys_by_domain[export["source_domain"]]
            and export["raw_content_present"] is False,
            f"{label} domain/key/privacy drift",
        )
        require(
            domain_rank[export["source_domain"]] >= prior_domain_rank,
            f"{label} violates deterministic source-domain order",
        )
        prior_domain_rank = domain_rank[export["source_domain"]]
        require(
            export["observer_mode"] in transient["source_export_observer_mode_values"]
            and export["result"] in transient["source_export_result_status_contract"]
            and export["observer_mode"]
            in transient["source_export_result_status_contract"][export["result"]]
            and export["status"]
            == transient["source_export_result_status_contract"][export["result"]][export["observer_mode"]]
            and exact_nonnegative_int(export["observed_event_count"]),
            f"{label} observer/result/status/count drift",
        )
        require(
            not (
                export["source_domain"] in {"CALL_EVENT", "EFFECT_EVENT"}
                and export["result"] == "UNAVAILABLE"
            ),
            f"{label} unavailable event export has no coherent lifecycle/ledger projection",
        )
        require(
            (
                export["source_domain"] == "COMPONENT_SOURCE"
                and isinstance(export["component_source_slot_id"], str)
            )
            or (
                export["source_domain"] != "COMPONENT_SOURCE"
                and export["component_source_slot_id"] is None
            ),
            f"{label} component-slot null convention drift",
        )
        if export["result"] == "UNAVAILABLE":
            require(
                export["observer_mode"] == "PROVIDER_AUTHENTICATED"
                and export["started_at"] is None
                and export["ended_at"] is None
                and export["observed_event_count"] == 0
                and export["failure_signal_code"] == "AUTHENTICATED_EXPORT_UNAVAILABLE"
                and export["unavailable_reason"]
                == transient["source_export_unavailable_reason_by_result"]["UNAVAILABLE"],
                f"{label} NOT_OBSERVED null/count/projection drift",
            )
            missing_export_seen = True
        else:
            started = parse_m00_deterministic_time(export["started_at"], f"{label} started_at")
            ended = parse_m00_deterministic_time(export["ended_at"], f"{label} ended_at")
            require(
                capture_context["capture_started"] <= started < ended
                <= capture_context["capture_ended"],
                f"{label} time order/capture-bound drift",
            )
            require(
                export["unavailable_reason"] is None,
                f"{label} observed source carries an unavailable reason",
            )
            if export["source_domain"] in runtime_contract["full_coverage_source_domain_values"]:
                require(
                    started == capture_context["capture_started"]
                    and ended == capture_context["capture_ended"],
                    f"{label} does not span the exact signed capture interval",
                )
        provider_id = export["opaque_provider_receipt_id"]
        provider_sha = export["opaque_provider_receipt_sha256"]
        if export["observer_mode"] == "PROVIDER_AUTHENTICATED":
            if export["result"] == "UNAVAILABLE":
                require(
                    provider_id is None
                    and provider_sha is None
                    and export["provider_receipt_projection_group_id"] is None
                    and export["provider_receipt_null_reason"] is None
                    and export["sealed_local_observer_ref"] is None,
                    f"{label} unavailable provider/local null convention drift",
                )
            else:
                require(
                    isinstance(provider_id, str) and provider_id.strip()
                    and isinstance(provider_sha, str) and HEX64_RE.fullmatch(provider_sha) is not None
                    and export["provider_receipt_null_reason"] is None
                    and export["sealed_local_observer_ref"] is None,
                    f"{label} lacks its authenticated provider tuple",
                )
                provider_tuple = (provider_id, provider_sha)
                projection_group = export["provider_receipt_projection_group_id"]
                prior_group = provider_tuple_groups.get(provider_tuple, ...)
                if prior_group is not ...:
                    require(
                        projection_group is not None
                        and prior_group == projection_group
                        and export["source_domain"] in {"NATIVE_LIFECYCLE", "COMPONENT_SOURCE"},
                        f"{label} reuses a provider receipt without one symmetric authorized group",
                    )
                if projection_group is not None:
                    prior_tuple = projection_group_tuples.get(projection_group)
                    require(
                        prior_tuple is None or prior_tuple == provider_tuple,
                        f"{label} projection group aliases distinct provider receipts",
                    )
                    projection_group_tuples[projection_group] = provider_tuple
                provider_tuple_groups[provider_tuple] = projection_group
        elif export["observer_mode"] == "SEALED_LOCAL":
            require(
                export["source_domain"] == "COMPONENT_SOURCE"
                and export["source_key"] in signed_local_keys
                and provider_id is None
                and provider_sha is None
                and export["provider_receipt_null_reason"]
                == transient["source_export_local_null_reason"]
                and isinstance(export["sealed_local_observer_ref"], dict),
                f"{label} sealed-local receipt convention drift",
            )
            exact_keys(
                export["sealed_local_observer_ref"],
                transient["sealed_local_observer_ref_exact_fields"],
                f"{label} sealed-local observer",
            )
            if expected_implementation_ref is not None:
                require(
                    export["sealed_local_observer_ref"] == expected_implementation_ref,
                    f"{label} does not bind the activated sealed evaluator",
                )
            require(
                held_final_artifact_sha256 is not None
                and held_final_artifact_facts is not None,
                f"{label} cannot be accepted without held final-artifact recomputation",
            )

        if export["source_domain"] == "NATIVE_LIFECYCLE":
            require(
                export["source_key"]
                in runtime_contract["observer_mode_by_native_lifecycle_source_key"]
                and export["observer_mode"]
                == runtime_contract["observer_mode_by_native_lifecycle_source_key"][export["source_key"]],
                f"{label} attempts a local native-lifecycle substitution",
            )
        elif export["source_domain"] == "COMPONENT_SOURCE" and component_source_contract is not None:
            require(
                export["source_key"] in component_source_contract["observer_mode_by_source_system"]
                and export["observer_mode"]
                == component_source_contract["observer_mode_by_source_system"][export["source_key"]],
                f"{label} component observer mode drift",
            )

        aliases = export["opaque_identity_aliases"]
        require(isinstance(aliases, list), f"{label} identity aliases are not a list")
        alias_classes: list[str] = []
        alias_values: set[tuple[str, str]] = set()
        for alias_index, alias in enumerate(aliases):
            alias_label = f"{label} identity alias {alias_index}"
            exact_keys(alias, transient["opaque_identity_alias_row_exact_fields"], alias_label)
            require(
                alias["identity_class"] in identity_classes
                and alias["availability"] in runtime_contract["identity_availability_values"],
                f"{alias_label} class/availability drift",
            )
            if alias["availability"] == "AVAILABLE":
                valid_closed_token(alias["opaque_alias"], f"{alias_label} opaque alias")
                require(
                    isinstance(alias["projection_sha256"], str)
                    and HEX64_RE.fullmatch(alias["projection_sha256"]) is not None
                    and alias["projection_sha256"]
                    == sha256_bytes(canonical_json_bytes([
                        "FC01_M00_OPAQUE_IDENTITY_PROJECTION_V1",
                        alias["identity_class"], alias["opaque_alias"],
                    ]))
                    and alias["unavailable_reason"] is None
                    and (alias["identity_class"], alias["opaque_alias"]) not in alias_values,
                    f"{alias_label} available alias/digest/uniqueness drift",
                )
                prior_alias = native_aliases_by_class.get(alias["identity_class"])
                if (
                    prior_alias is not None
                    and prior_alias != (alias["opaque_alias"], alias["projection_sha256"])
                ):
                    identity_projection_conflict = True
                native_aliases_by_class.setdefault(
                    alias["identity_class"],
                    (alias["opaque_alias"], alias["projection_sha256"]),
                )
                alias_values.add((alias["identity_class"], alias["opaque_alias"]))
            else:
                require(
                    alias["opaque_alias"] is None
                    and alias["projection_sha256"] is None
                    and alias["unavailable_reason"]
                    == runtime_contract["identity_projection_status_by_availability"][alias["availability"]],
                    f"{alias_label} unavailable alias/null-reason drift",
                )
            if alias["identity_class"] == "SYNTHETIC_SCOPE":
                if alias["availability"] == "AVAILABLE":
                    require(
                        alias["opaque_alias"] == expected_synthetic_scope_alias,
                        f"{alias_label} does not retain the exact D2 synthetic scope",
                    )
                else:
                    require(
                        export["result"] == "UNAVAILABLE"
                        and alias["availability"] == "NOT_OBSERVED",
                        f"{alias_label} suppresses the D2 scope outside a signed unavailable export",
                    )
            alias_classes.append(alias["identity_class"])
            identity_claims_by_class[alias["identity_class"]].append(alias)
        expected_alias_classes: Optional[list[str]] = None
        if export["source_domain"] == "NATIVE_LIFECYCLE":
            expected_alias_classes = transient["native_identity_classes_by_source_key"][export["source_key"]]
        elif export["source_domain"] == "COMPONENT_SOURCE":
            expected_alias_classes = transient["identity_classes_by_component_source_slot_id"][export["component_source_slot_id"]]
        elif export["source_domain"] == "CALL_SOURCE_COVERAGE":
            expected_alias_classes = transient["identity_classes_by_call_source_coverage"]
        elif export["source_domain"] in {"EFFECT_SOURCE_COVERAGE", "EFFECT_EVENT"}:
            expected_alias_classes = transient["identity_classes_by_effect_source_domain"][export["source_domain"]]
        if expected_alias_classes is not None:
            require(
                alias_classes == expected_alias_classes,
                f"{label} identity-class order/bijection drift",
            )
        if export["result"] == "UNAVAILABLE":
            require(
                all(alias["availability"] == "NOT_OBSERVED" for alias in aliases),
                f"{label} unavailable export fabricates identity availability",
            )
        facts = export["minimized_fact_rows"]
        require(isinstance(facts, list), f"{label} minimized facts are not a list")
        fact_ids = [fact.get("fact_id") for fact in facts]
        if export["source_domain"] == "NATIVE_LIFECYCLE":
            native_keys.append(export["source_key"])
            require(export["source_key"] not in native_exports, f"{label} native source is duplicated")
            native_exports[export["source_key"]] = export
            expected_fact_contract = transient["native_fact_contract_by_source_key"].get(export["source_key"])
            require(expected_fact_contract is not None, f"{label} native source key is not closed")
            require(fact_ids == list(expected_fact_contract), f"{label} native fact order/bijection drift")
            expected_types = expected_fact_contract
            require(
                alias_classes == transient["native_identity_classes_by_source_key"][export["source_key"]],
                f"{label} native identity-class projection drift",
            )
        elif export["source_domain"] == "COMPONENT_SOURCE":
            slot_matches = [
                (category, slot)
                for category, slots in component_contract["component_source_slots_by_category"].items()
                for slot in slots
                if slot["source_slot_id"] == export["component_source_slot_id"]
            ]
            require(len(slot_matches) == 1, f"{label} component slot is not in the frozen catalog")
            component_category, slot = slot_matches[0]
            require(slot["source_system"] == export["source_key"], f"{label} component slot/source drift")
            category_specs = (
                component_contract["required_source_contract_by_category"][component_category]
                + component_contract.get("optional_source_contract_by_category", {}).get(component_category, [])
            )
            matching_specs = [
                spec for spec in category_specs
                if spec["source_system"] == export["source_key"]
                and spec["owned_fact_ids"] == fact_ids
            ]
            require(len(matching_specs) == 1, f"{label} does not match its closed component source/fact owner")
            expected_types = {
                fact_id: (
                    component_contract["required_fact_contract_by_category"].get(component_category, {})
                    | component_contract.get("optional_fact_contract_by_category", {}).get(component_category, {})
                )[fact_id]["value_type"].replace("TOKEN", "CLOSED_TOKEN")
                for fact_id in fact_ids
            }
        else:
            require(export["source_domain"] in generic_contracts, f"{label} lacks a generic fact contract")
            require(fact_ids == generic_contracts[export["source_domain"]], f"{label} generic fact order/bijection drift")
            expected_types = {fact_id: generic_types[fact_id] for fact_id in fact_ids}
        fact_values: dict[str, Any] = {}
        fact_results: dict[str, str] = {}
        for fact_index, fact in enumerate(facts):
            fact_label = f"{label} fact {fact_index}"
            exact_keys(fact, transient["minimized_fact_row_exact_fields"], fact_label)
            fact_id = fact["fact_id"]
            require(
                fact["value_type"] == expected_types[fact_id]
                and fact["value_type"] in transient["value_type_values"],
                f"{fact_label} value type drift",
            )
            require(fact["result"] in transient["fact_result_values"], f"{fact_label} result invalid")
            fact_results[fact_id] = fact["result"]
            selected = value_fields[fact["value_type"]]
            if fact["result"] == "NOT_OBSERVED":
                require(
                    all(fact[field] is None for field in value_fields.values())
                    and fact["not_observed_reason"]
                    == (
                        transient["source_export_unavailable_reason_by_result"]["UNAVAILABLE"]
                        if export["result"] == "UNAVAILABLE"
                        else "NOT_OBSERVED_DUE_TO_SOURCE_SHORT_CIRCUIT"
                    ),
                    f"{fact_label} NOT_OBSERVED projection drift",
                )
                fact_values[fact_id] = None
                continue
            require(
                fact[selected] is not None
                and all(fact[field] is None for field in value_fields.values() if field != selected)
                and fact["not_observed_reason"] is None,
                f"{fact_label} value/null/result projection drift",
            )
            fact_value = fact[selected]
            if fact["value_type"] == "BOOLEAN":
                require(isinstance(fact_value, bool), f"{fact_label} boolean invalid")
            elif fact["value_type"] == "INTEGER":
                require(exact_nonnegative_int(fact_value), f"{fact_label} integer invalid")
            elif fact["value_type"] == "NUMBER":
                require(finite_number(fact_value) and fact_value >= 0, f"{fact_label} number invalid")
            elif fact["value_type"] == "CLOSED_TOKEN":
                valid_closed_token(fact_value, fact_label)
            else:
                require(isinstance(fact_value, str) and HEX64_RE.fullmatch(fact_value) is not None, f"{fact_label} digest invalid")
            fact_values[fact_id] = fact_value
        fact_result_list = [fact["result"] for fact in facts]
        if export["result"] == "PASS":
            require(
                fact_result_list and set(fact_result_list) == {"PASS"}
                and export["failure_signal_code"] is None
                and export["unavailable_reason"] is None,
                f"{label} PASS contains a failed/unobserved fact",
            )
        elif export["result"] == "FAIL":
            require(
                "FAIL" in fact_result_list
                and export["failure_signal_code"]
                in transient["source_export_fail_signal_codes_by_source_domain"][export["source_domain"]]
                and export["unavailable_reason"] is None,
                f"{label} observed FAIL lacks retained failed facts/signal",
            )
        elif export["result"] == "PARTIAL":
            require(
                "FAIL" not in fact_result_list
                and "PASS" in fact_result_list
                and "NOT_OBSERVED" in fact_result_list
                and export["failure_signal_code"] == "PARTIAL_DUE_TO_PRIOR_BOUND_FAILURE"
                and export["unavailable_reason"] is None,
                f"{label} PARTIAL fact/signal shape drift",
            )
        else:
            require(
                export["result"] == "UNAVAILABLE"
                and fact_result_list
                and set(fact_result_list) == {"NOT_OBSERVED"},
                f"{label} UNAVAILABLE does not retain the complete unavailable fact catalog",
            )
        if export["source_domain"] in generic_contracts and export["result"] != "UNAVAILABLE":
            require(
                "NOT_OBSERVED" not in fact_results.values(),
                f"{label} hides an independently available generic fact",
            )
        if export["observer_mode"] == "SEALED_LOCAL":
            require(
                isinstance(held_final_artifact_facts, dict),
                f"{label} lacks held mechanical facts",
            )
            exact_keys(
                held_final_artifact_facts,
                {"PPTX_CONTAINER_VALID", "NATIVE_ARTIFACT_VALID"},
                f"{label} held mechanical facts",
            )
            require(
                all(isinstance(flag, bool) for flag in held_final_artifact_facts.values()),
                f"{label} held mechanical fact types drift",
            )
            expected_sealed_values = {
                "PPTX_CONTAINER_VALID": held_final_artifact_facts["PPTX_CONTAINER_VALID"],
                "NATIVE_ARTIFACT_VALID": (
                    held_final_artifact_facts["NATIVE_ARTIFACT_VALID"]
                    if held_final_artifact_facts["PPTX_CONTAINER_VALID"]
                    else None
                ),
            }
            expected_sealed_results = {
                "PPTX_CONTAINER_VALID": (
                    "PASS" if held_final_artifact_facts["PPTX_CONTAINER_VALID"] else "FAIL"
                ),
                "NATIVE_ARTIFACT_VALID": (
                    "NOT_OBSERVED"
                    if not held_final_artifact_facts["PPTX_CONTAINER_VALID"]
                    else "PASS" if held_final_artifact_facts["NATIVE_ARTIFACT_VALID"] else "FAIL"
                ),
            }
            expected_sealed_source_result = (
                "PASS" if set(expected_sealed_results.values()) == {"PASS"} else "FAIL"
            )
            require(
                export["source_key"] == "SEALED_PPTX_PACKAGE_VALIDATOR"
                and fact_values == expected_sealed_values
                and fact_results == expected_sealed_results
                and export["result"] == expected_sealed_source_result
                and isinstance(held_final_artifact_sha256, str)
                and HEX64_RE.fullmatch(held_final_artifact_sha256) is not None,
                f"{label} signed sealed-local facts/artifact identity do not equal held-byte recomputation",
            )
            if expected_sealed_source_result == "FAIL":
                require(
                    export["failure_signal_code"] == "SOURCE_POSTCONDITION_FAILED",
                    f"{label} sealed mechanical failure signal drift",
                )
        if export["source_domain"] == "CALL_SOURCE_COVERAGE":
            call_coverage_export_indices.append(index + 1)
        if export["result"] == "UNAVAILABLE":
            require(export["observed_event_count"] == 0, f"{label} unavailable observed-event count drift")
        elif export["source_domain"] in {"NATIVE_LIFECYCLE", "COMPONENT_SOURCE", "CALL_EVENT"}:
            require(export["observed_event_count"] == 1, f"{label} observed-event count drift")
        elif export["source_domain"] == "CALL_SOURCE_COVERAGE":
            require(
                export["source_key"] == "CROSS_SYSTEM_TOOL_MODEL_CALL_COVERAGE"
                and export["observer_mode"] == "PROVIDER_AUTHENTICATED"
                and (
                    export["result"] == "UNAVAILABLE"
                    or export["observed_event_count"] == fact_values["OBSERVED_CALL_COUNT"]
                ),
                f"{label} call-source coverage identity/mode/count drift",
            )
        elif export["source_domain"] == "EFFECT_SOURCE_COVERAGE":
            require(
                export["result"] == "UNAVAILABLE"
                or export["observed_event_count"] == fact_values["OBSERVED_EVENT_COUNT"],
                f"{label} coverage count/fact drift",
            )
            if effect_coverage_contract is not None:
                source_class = (
                    export["source_key"]
                    if export["result"] == "UNAVAILABLE"
                    else fact_values["SOURCE_CLASS"]
                )
                require(
                    source_class in effect_coverage_contract["observer_mode_by_source_class"]
                    and export["source_key"] == source_class
                    and export["observer_mode"]
                    == effect_coverage_contract["observer_mode_by_source_class"][source_class],
                    f"{label} effect-source observer mode/key drift",
                )
        else:
            require(
                export["result"] == "UNAVAILABLE"
                or export["observed_event_count"] == fact_values["COUNT"]
                and export["observed_event_count"] > 0,
                f"{label} effect count/fact drift",
            )
            if effect_coverage_contract is not None and export["result"] != "UNAVAILABLE":
                source_class = effect_coverage_contract["effect_category_to_source_class"].get(
                    fact_values["CATEGORY"]
                )
                require(
                    source_class is not None
                    and export["source_key"] == fact_values["CATEGORY"]
                    and export["observer_mode"]
                    == effect_coverage_contract["observer_mode_by_source_class"][source_class],
                    f"{label} effect-event observer mode/category drift",
                )
        if (
            export["source_domain"] == "CALL_EVENT"
            and export["result"] != "UNAVAILABLE"
            and call_budget is not None
        ):
            budget_row = next(
                (row for row in call_budget["call_categories"] if row["category"] == fact_values["CATEGORY"]),
                None,
            )
            require(
                budget_row is not None
                and export["source_key"] == fact_values["CATEGORY"]
                and export["observer_mode"] == budget_row["observation_mode"],
                f"{label} call-budget observer mode/category drift",
            )
            require(
                fact_values["PROVIDER_POLICY_ID"] == budget_row["provider_policy_id"]
                and fact_values["PHASE"]
                in schema["supporting_receipt_contracts"]["m00_call_observation"]["allowed_phase_values"]
                and isinstance(fact_values["OUTCOME"], str)
                and fact_values["OUTCOME"]
                in {
                    outcome
                    for outcomes in transient[
                        "call_event_outcome_values_by_fact_result"
                    ].values()
                    for outcome in outcomes
                },
                f"{label} call-budget policy/phase/outcome drift",
            )
        fact_values_by_export[index + 1] = fact_values
        fact_results_by_export[index + 1] = fact_results
        export_results.append(export["result"])
    require(
        len(call_coverage_export_indices) == 1,
        "M00 transient requires one exact call-source coverage export",
    )
    call_coverage_facts = fact_values_by_export[call_coverage_export_indices[0]]
    observed_call_exports = [
        export for export in exports
        if export["source_domain"] == "CALL_EVENT"
        and export["result"] != "UNAVAILABLE"
    ]
    call_outcome_failure_signal = {
        "FAIL": "SOURCE_REPORTED_REJECTED",
        "REJECTED": "SOURCE_REPORTED_REJECTED",
        "TIMEOUT": "SOURCE_TIMEOUT",
        "TRANSPORT_FAILURE": "SOURCE_TRANSPORT_FAILURE",
        "AUTHORIZATION_FAILED": "SOURCE_AUTHORIZATION_FAILED",
        "CONFLICT": "SOURCE_CONFLICT",
        "POSTCONDITION_FAILED": "SOURCE_POSTCONDITION_FAILED",
    }
    for call_index, call_export in enumerate(exports, start=1):
        if call_export["source_domain"] != "CALL_EVENT" or call_export["result"] == "UNAVAILABLE":
            continue
        call_facts = fact_values_by_export[call_index]
        call_results = fact_results_by_export[call_index]
        outcome = call_facts["OUTCOME"]
        expected_outcome_result = next(
            (
                fact_result
                for fact_result, values in transient["call_event_outcome_values_by_fact_result"].items()
                if outcome in values
            ),
            None,
        )
        require(
            expected_outcome_result is not None
            and all(
                call_results[fact_id] == "PASS"
                for fact_id in ("PHASE", "CATEGORY", "PROVIDER_POLICY_ID", "COST_USD")
            )
            and call_results["OUTCOME"] == expected_outcome_result
            and call_export["result"] == expected_outcome_result,
            "M00 transient call-event fact/source result derivation drift",
        )
        if expected_outcome_result == "FAIL":
            require(
                call_export["failure_signal_code"] == call_outcome_failure_signal[outcome],
                "M00 transient call-event outcome/failure-signal drift",
            )
    call_coverage_export = exports[call_coverage_export_indices[0] - 1]
    if call_coverage_export["result"] == "UNAVAILABLE":
        require(not observed_call_exports, "M00 unavailable call coverage coexists with observed call events")
    else:
        call_coverage_results = fact_results_by_export[call_coverage_export_indices[0]]
        call_coverage_contract = schema["supporting_receipt_contracts"]["m00_call_observer_coverage"]
        expected_call_coverage_results = {
            "OBSERVED_CALL_COUNT": (
                "PASS" if call_coverage_facts["OBSERVED_CALL_COUNT"] == len(observed_call_exports) else "FAIL"
            ),
            "UNCLASSIFIED_CALL_COUNT": (
                "PASS" if call_coverage_facts["UNCLASSIFIED_CALL_COUNT"] == 0 else "FAIL"
            ),
            "DROPPED_OBSERVATION_COUNT": (
                "PASS" if call_coverage_facts["DROPPED_OBSERVATION_COUNT"] == 0 else "FAIL"
            ),
            "STATUS": (
                "PASS"
                if call_coverage_facts["STATUS"]
                == call_coverage_contract["pass_required_values"]["status"]
                else "FAIL"
            ),
        }
        expected_call_coverage_status = (
            call_coverage_contract["pass_required_values"]["status"]
            if all(
                expected_call_coverage_results[fact_id] == "PASS"
                for fact_id in (
                    "OBSERVED_CALL_COUNT", "UNCLASSIFIED_CALL_COUNT",
                    "DROPPED_OBSERVATION_COUNT",
                )
            )
            else call_coverage_contract["failure_status"]
        )
        require(
            call_coverage_facts["STATUS"] == expected_call_coverage_status
            and call_coverage_results == expected_call_coverage_results
            and call_coverage_export["result"]
            == ("PASS" if set(expected_call_coverage_results.values()) == {"PASS"} else "FAIL"),
            "M00 transient call-source coverage fact/source result derivation drift",
        )
        require(
            call_coverage_facts["OBSERVED_CALL_COUNT"] == len(observed_call_exports),
            "M00 transient call coverage does not equal the exact observed call-event set",
        )
    call_budget_rows = {
        row["category"]: row for row in call_budget["call_categories"]
    }
    call_counts_by_category = {category: 0 for category in call_budget_rows}
    actual_spend_usd = 0.0
    for call_index, call_export in enumerate(exports, start=1):
        if call_export["source_domain"] != "CALL_EVENT" or call_export["result"] == "UNAVAILABLE":
            continue
        call_facts = fact_values_by_export[call_index]
        call_counts_by_category[call_facts["CATEGORY"]] += 1
        actual_spend_usd += float(call_facts["COST_USD"])
    actual_total_calls = sum(call_counts_by_category.values())
    call_maximum_exceeded = (
        actual_total_calls > call_budget["maximum_total_calls"]
        or any(
            call_counts_by_category[category] > row["maximum_calls"]
            for category, row in call_budget_rows.items()
        )
    )
    call_minimum_missing = (
        actual_total_calls < call_budget["minimum_total_calls"]
        or any(
            call_counts_by_category[category] < row["minimum_calls"]
            for category, row in call_budget_rows.items()
        )
    )
    spend_ceiling_exceeded = actual_spend_usd > float(spend_budget["maximum_spend"])

    component_exports = [
        export for export in exports if export["source_domain"] == "COMPONENT_SOURCE"
    ]
    effect_coverage_exports = [
        export for export in exports
        if export["source_domain"] == "EFFECT_SOURCE_COVERAGE"
    ]
    if effect_coverage_contract is not None:
        require(
            [export["source_key"] for export in effect_coverage_exports]
            == effect_coverage_contract["required_source_classes"],
            "M00 transient effect-source coverage order/bijection drift",
        )
        require(
            all(export["observer_mode"] == "PROVIDER_AUTHENTICATED" for export in effect_coverage_exports),
            "M00 transient effect-source coverage permits a local substitute",
        )
        effect_observation_contract = schema["supporting_receipt_contracts"]["m00_effect_observation"]
        expected_effect_rows = expected_effects["effect_rows"]
        observed_effect_exports = [
            (effect_index, export)
            for effect_index, export in enumerate(exports, start=1)
            if export["source_domain"] == "EFFECT_EVENT" and export["result"] != "UNAVAILABLE"
        ]
        effect_count_by_source_class = {
            source_class: 0 for source_class in effect_coverage_contract["required_source_classes"]
        }
        for effect_index, effect_export in observed_effect_exports:
            effect_facts = fact_values_by_export[effect_index]
            effect_results = fact_results_by_export[effect_index]
            category = effect_facts["CATEGORY"]
            source_class = effect_coverage_contract["effect_category_to_source_class"].get(category)
            authorized_effect = next(
                (
                    row for row in expected_effect_rows
                    if row["effect_class"] == category
                    and row["target_class"] == effect_facts["TARGET_CLASS"]
                    and row["operation"] == effect_facts["OPERATION"]
                    and row["synthetic_scope_alias"] == effect_facts["SYNTHETIC_SCOPE_ALIAS"]
                    and effect_facts["PHASE"] == "FORWARD_M00_ATTEMPT"
                ),
                None,
            )
            expected_classification = (
                "AUTHORIZED" if authorized_effect is not None else "UNEXPECTED"
            )
            require(
                source_class is not None
                and effect_export["source_key"] == category
                and effect_facts["PHASE"] in effect_observation_contract["allowed_phase_values"]
                and effect_facts["SYNTHETIC_SCOPE_ALIAS"] == expected_synthetic_scope_alias
                and exact_nonnegative_int(effect_facts["COUNT"])
                and effect_facts["COUNT"] > 0
                and effect_facts["CLASSIFICATION"]
                in effect_observation_contract["classification_values"]
                and effect_facts["CLASSIFICATION"] == expected_classification
                and all(
                    effect_results[fact_id] == "PASS"
                    for fact_id in (
                        "PHASE", "CATEGORY", "TARGET_CLASS", "OPERATION",
                        "SYNTHETIC_SCOPE_ALIAS", "COUNT",
                    )
                ),
                "M00 transient effect-event identity/value fact derivation drift",
            )
            expected_effect_result = (
                "PASS" if expected_classification == "AUTHORIZED" else "FAIL"
            )
            expected_effect_status = (
                "PASS_OBSERVED_EFFECT"
                if expected_effect_result == "PASS"
                else effect_observation_contract["failure_status"]
            )
            require(
                effect_results["CLASSIFICATION"] == expected_effect_result
                and effect_facts["STATUS"] == expected_effect_status
                and effect_results["STATUS"] == expected_effect_result
                and effect_export["result"] == expected_effect_result,
                "M00 transient effect-event classification/status derivation drift",
            )
            if expected_effect_result == "FAIL":
                require(
                    effect_export["failure_signal_code"] == "EFFECT_POLICY_VIOLATION",
                    "M00 transient unexpected effect lacks the exact safety signal",
                )
            effect_count_by_source_class[source_class] += effect_facts["COUNT"]
        for coverage_export in effect_coverage_exports:
            if coverage_export["result"] == "UNAVAILABLE":
                require(
                    effect_count_by_source_class[coverage_export["source_key"]] == 0,
                    "M00 transient unavailable effect coverage coexists with observed same-class events",
                )
                continue
            coverage_index = exports.index(coverage_export) + 1
            coverage_facts = fact_values_by_export[coverage_index]
            coverage_results = fact_results_by_export[coverage_index]
            source_class = coverage_facts["SOURCE_CLASS"]
            expected_coverage_results = {
                "SOURCE_CLASS": "PASS",
                "OBSERVED_EVENT_COUNT": (
                    "PASS"
                    if coverage_facts["OBSERVED_EVENT_COUNT"] == effect_count_by_source_class[source_class]
                    else "FAIL"
                ),
                "UNCLASSIFIED_EVENT_COUNT": (
                    "PASS" if coverage_facts["UNCLASSIFIED_EVENT_COUNT"] == 0 else "FAIL"
                ),
                "DROPPED_OBSERVATION_COUNT": (
                    "PASS" if coverage_facts["DROPPED_OBSERVATION_COUNT"] == 0 else "FAIL"
                ),
                "STATUS": (
                    "PASS"
                    if coverage_facts["STATUS"] == effect_coverage_contract["pass_source_status"]
                    else "FAIL"
                ),
            }
            expected_coverage_status = (
                effect_coverage_contract["pass_source_status"]
                if all(
                    expected_coverage_results[fact_id] == "PASS"
                    for fact_id in (
                        "SOURCE_CLASS", "OBSERVED_EVENT_COUNT",
                        "UNCLASSIFIED_EVENT_COUNT", "DROPPED_OBSERVATION_COUNT",
                    )
                )
                else effect_coverage_contract["failure_source_status"]
            )
            require(
                coverage_facts["STATUS"] == expected_coverage_status
                and coverage_results == expected_coverage_results
                and coverage_export["result"]
                == ("PASS" if set(expected_coverage_results.values()) == {"PASS"} else "FAIL"),
                "M00 transient effect-source coverage fact/source result derivation drift",
            )
        effect_counts_by_category = {
            category: 0 for category in effect_coverage_contract["effect_category_to_source_class"]
        }
        for effect_index, _effect_export in observed_effect_exports:
            effect_facts = fact_values_by_export[effect_index]
            effect_counts_by_category[effect_facts["CATEGORY"]] += effect_facts["COUNT"]
        effect_minimum_missing = any(
            effect_counts_by_category[row["effect_class"]] < row["minimum_count"]
            for row in expected_effect_rows
        )
        effect_maximum_exceeded = any(
            effect_counts_by_category[row["effect_class"]] > row["maximum_count"]
            for row in expected_effect_rows
        )

    events = value["lifecycle_event_exports"]
    require(isinstance(events, list) and events, "M00 transient lifecycle exports are empty")
    event_kinds = [row.get("event_kind") for row in events]
    matching_repairs = [
        int(repair_count)
        for repair_count, expected in runtime_contract["event_kind_sequences_by_repair_count"].items()
        if event_kinds == expected
    ]
    require(len(matching_repairs) == 1, "M00 transient lifecycle event order is not one closed sequence")
    repair_count = matching_repairs[0]
    event_results: list[str] = []
    consumed_call_indices: list[int] = []
    prior_event_end: Optional[dt.datetime] = None
    runtime_event_rows: list[dict[str, Any]] = []
    referenced_native_indices: list[int] = []
    call_event_kind_by_export_index: dict[int, str] = {}
    for index, event in enumerate(events):
        label = f"M00 transient lifecycle event {index}"
        exact_keys(event, transient["lifecycle_event_export_exact_fields"], label)
        expected_slot_id = f"{value['attempt_id']}/{index + 1:04d}/{event['event_kind']}"
        require(
            exact_nonnegative_int(event["sequence"])
            and event["sequence"] == index + 1
            and event["event_slot_id"] == expected_slot_id
            and event["result"] in {"PASS", "FAIL", "NOT_OBSERVED"},
            f"{label} sequence/slot/result drift",
        )
        allowed_sources = runtime_contract["required_native_sources_by_event_kind"][event["event_kind"]]
        source_indices = event["source_export_indices"]
        require(
            isinstance(source_indices, list)
            and len(source_indices) == len(set(source_indices))
            and all(
                exact_nonnegative_int(source_index)
                and 1 <= source_index <= len(exports)
                and exports[source_index - 1]["source_domain"] == "NATIVE_LIFECYCLE"
                and exports[source_index - 1]["result"] != "UNAVAILABLE"
                for source_index in source_indices
            )
            and [exports[source_index - 1]["source_key"] for source_index in source_indices]
            == event["source_keys"]
            and [exports[source_index - 1]["source_envelope_sha256"] for source_index in source_indices]
            == event["source_envelope_sha256s"],
            f"{label} native source index/key/envelope projection drift",
        )
        call_indices = event["call_export_indices"]
        require(
            isinstance(call_indices, list)
            and len(call_indices) == len(set(call_indices))
            and all(
                exact_nonnegative_int(call_index)
                and 1 <= call_index <= len(exports)
                and exports[call_index - 1]["source_domain"] == "CALL_EVENT"
                for call_index in call_indices
            )
            and not (set(call_indices) & set(consumed_call_indices)),
            f"{label} call-export projection invalid/reused",
        )
        require(
            [exports[call_index - 1]["source_envelope_sha256"] for call_index in call_indices]
            == event["call_envelope_sha256s"],
            f"{label} call envelope projection drift",
        )
        require(
            all(
                fact_values_by_export[call_index].get("PHASE") == "FORWARD_M00_ATTEMPT"
                for call_index in call_indices
            ),
            f"{label} owns a cleanup or non-forward call",
        )
        expected_call_category = runtime_contract["call_category_by_event_kind"][event["event_kind"]]
        minimum_call_rows = runtime_contract["minimum_call_rows_by_event_kind"][event["event_kind"]]
        if event["result"] == "PASS" and expected_call_category is not None:
            require(
                len(call_indices) >= minimum_call_rows
                and all(
                    fact_values_by_export[call_index].get("CATEGORY") == expected_call_category
                    and fact_values_by_export[call_index].get("OUTCOME") == "PASS"
                    for call_index in call_indices
                ),
                f"{label} does not select its exact required call category",
            )
        elif event["result"] == "NOT_OBSERVED" or expected_call_category is None:
            require(not call_indices, f"{label} carries an unapproved call export")
        else:
            require(
                all(fact_values_by_export[call_index].get("CATEGORY") == expected_call_category for call_index in call_indices)
                and all(
                    fact_values_by_export[call_index].get("OUTCOME") == "PASS"
                    for call_index in call_indices[:-1]
                )
                and (
                    not call_indices
                    or fact_values_by_export[call_indices[-1]].get("OUTCOME") != "PASS"
                ),
                f"{label} FAIL calls are not a complete PASS-prefix/final-FAIL projection",
            )
        expected_call_alias_classes = transient["identity_classes_by_call_event_kind"].get(event["event_kind"])
        for call_index in call_indices:
            require(
                [row["identity_class"] for row in exports[call_index - 1]["opaque_identity_aliases"]]
                == expected_call_alias_classes,
                f"{label} call identity-class projection drift",
            )
        consumed_call_indices.extend(call_indices)
        for call_index in call_indices:
            call_event_kind_by_export_index[call_index] = event["event_kind"]
        if event["result"] == "NOT_OBSERVED":
            require(
                event["status"]
                == runtime_contract["lifecycle_status_by_not_observed_reason"].get(event["not_observed_reason"])
                and event["not_observed_reason"] in runtime_contract["lifecycle_not_observed_reason_values"]
                and event["started_at"] is None
                and event["ended_at"] is None
                and event["source_keys"] == []
                and source_indices == []
                and event["source_envelope_sha256s"] == []
                and call_indices == []
                and event["call_envelope_sha256s"] == []
                and event["failure_signal_code"] is None
                and event["failure_source_envelope_sha256"] is None
                and event["failure_call_envelope_sha256"] is None
                and event["artifact_sha256"] is None
                and event["artifact_null_reason"] == event["not_observed_reason"],
                f"{label} NOT_OBSERVED null convention drift",
            )
        else:
            require(
                event["status"] == runtime_contract["lifecycle_status_by_observed_result"][event["result"]]
                and event["not_observed_reason"] is None,
                f"{label} observed result/status/reason drift",
            )
            started = parse_m00_deterministic_time(event["started_at"], f"{label} started_at")
            ended = parse_m00_deterministic_time(event["ended_at"], f"{label} ended_at")
            require(
                capture_context["capture_started"] <= started < ended
                <= capture_context["capture_ended"]
                and (prior_event_end is None or prior_event_end <= started),
                f"{label} chronology drift",
            )
            for call_index in call_indices:
                call_export = exports[call_index - 1]
                require(
                    started <= parse_m00_deterministic_time(call_export["started_at"], f"{label} call started_at")
                    <= parse_m00_deterministic_time(call_export["ended_at"], f"{label} call ended_at") <= ended,
                    f"{label} call export is outside its event",
                )
            prior_event_end = ended
            if event["result"] == "PASS":
                require(
                    event["source_keys"] == allowed_sources
                    and all(
                        exports[source_index - 1]["result"] == "PASS"
                        for source_index in source_indices
                    )
                    and event["failure_signal_code"] is None
                    and event["failure_source_envelope_sha256"] is None
                    and event["failure_call_envelope_sha256"] is None,
                    f"{label} PASS source/failure projection drift",
                )
            else:
                require(
                    event["source_keys"]
                    == [source for source in allowed_sources if source in event["source_keys"]]
                    and event["failure_signal_code"] in runtime_contract["lifecycle_failure_signal_code_values"],
                    f"{label} FAIL source subset/signal drift",
                )
                failing_calls = [
                    call_index for call_index in call_indices
                    if exports[call_index - 1]["result"] == "FAIL"
                ]
                failing_sources = [
                    source_index for source_index in source_indices
                    if exports[source_index - 1]["result"] == "FAIL"
                ]
                if failing_calls:
                    require(
                        event["failure_call_envelope_sha256"]
                        == exports[failing_calls[-1] - 1]["source_envelope_sha256"]
                        and event["failure_source_envelope_sha256"] is None
                        and event["failure_signal_code"]
                        == exports[failing_calls[-1] - 1]["failure_signal_code"],
                        f"{label} failing-call precedence/provenance drift",
                    )
                elif failing_sources:
                    require(
                        event["failure_source_envelope_sha256"]
                        == exports[failing_sources[0] - 1]["source_envelope_sha256"]
                        and event["failure_call_envelope_sha256"] is None
                        and event["failure_signal_code"]
                        == exports[failing_sources[0] - 1]["failure_signal_code"],
                        f"{label} failing-source precedence/provenance drift",
                    )
                else:
                    require(
                        event["failure_signal_code"]
                        in runtime_contract["direct_pre_provider_lifecycle_failure_signal_code_values"]
                        and event["failure_source_envelope_sha256"] is None
                        and event["failure_call_envelope_sha256"] is None,
                        f"{label} direct pre-provider failure provenance drift",
                    )
            if event["artifact_sha256"] is None:
                require(
                    event["result"] == "FAIL"
                    and event["artifact_null_reason"] == "NOT_PRODUCED_DUE_TO_FAILED_STAGE",
                    f"{label} missing-artifact convention drift",
                )
            else:
                require(
                    isinstance(event["artifact_sha256"], str)
                    and HEX64_RE.fullmatch(event["artifact_sha256"]) is not None
                    and event["artifact_null_reason"] is None,
                    f"{label} artifact digest/null convention drift",
                )
        stable_projection = [
            "FC01_M00_STABLE_LIFECYCLE_EVENT_V1",
            event["event_slot_id"], event["event_kind"], event["started_at"], event["ended_at"],
            event["source_envelope_sha256s"], event["call_envelope_sha256s"],
            event["failure_signal_code"], event["failure_source_envelope_sha256"],
            event["failure_call_envelope_sha256"], event["artifact_sha256"],
            event["artifact_null_reason"], event["not_observed_reason"], event["result"], event["status"],
        ]
        require(
            event["stable_event_projection_sha256"] == sha256_bytes(canonical_json_bytes(stable_projection)),
            f"{label} stable projection digest drift",
        )
        referenced_native_indices.extend(source_indices)
        runtime_event_rows.append({
            "sequence": event["sequence"],
            "event_slot_id": event["event_slot_id"],
            "event_kind": event["event_kind"],
            "started_at": event["started_at"],
            "ended_at": event["ended_at"],
            "source_registry_sequences": source_indices,
            "call_registry_sequences": call_indices,
            "failure_signal_code": event["failure_signal_code"],
            "failure_source_envelope_sha256": event["failure_source_envelope_sha256"],
            "failure_call_envelope_sha256": event["failure_call_envelope_sha256"],
            "stable_event_projection_sha256": event["stable_event_projection_sha256"],
            "artifact_sha256": event["artifact_sha256"],
            "artifact_null_reason": event["artifact_null_reason"],
            "not_observed_reason": event["not_observed_reason"],
            "result": event["result"],
            "status": event["status"],
        })
        event_results.append(event["result"])
    referenced_native_set = set(referenced_native_indices)
    actual_native_indices = [
        index + 1 for index, export in enumerate(exports)
        if export["source_domain"] == "NATIVE_LIFECYCLE"
    ]
    expected_native_keys = [
        key for key in runtime_contract["required_native_lifecycle_source_keys"]
        if any(
            exports[source_index - 1]["source_key"] == key
            for source_index in referenced_native_set
        )
    ]
    require(
        set(actual_native_indices) == referenced_native_set
        and native_keys == expected_native_keys,
        "M00 transient native lifecycle registry is not the exact referenced ordered set union",
    )
    native_result_by_source_key = {
        export["source_key"]: export["result"]
        for export in exports
        if export["source_domain"] == "NATIVE_LIFECYCLE"
    }
    precursor_context = derive_m00_native_lifecycle_precursor_manifest(
        value["attempt_id"],
        events,
        runtime_contract,
        native_result_by_source_key,
    )
    precursor_sha256 = precursor_context["manifest_sha256"]
    precursor_fact_by_source = runtime_contract[
        "native_lifecycle_precursor_contract"
    ]["fact_id_by_source_key"]
    event_by_kind = {event["event_kind"]: event for event in events}
    for source_key, fact_id in precursor_fact_by_source.items():
        matching = [
            (index + 1, export)
            for index, export in enumerate(exports)
            if export["source_domain"] == "NATIVE_LIFECYCLE"
            and export["source_key"] == source_key
        ]
        if not matching:
            continue
        source_index, export = matching[0]
        fact_results = fact_results_by_export[source_index]
        fact_values = fact_values_by_export[source_index]
        if export["result"] == "UNAVAILABLE":
            require(
                fact_results[fact_id] == "NOT_OBSERVED",
                f"M00 unavailable native precursor fact is fabricated: {source_key}/{fact_id}",
            )
            continue
        if source_key == "LANGGRAPH_DECK_DESIGN_LIFT_RUNTIME":
            prerequisite_met = (
                fact_results.get("TERMINAL_STATE") != "NOT_OBSERVED"
            )
        elif source_key == "LANGGRAPH_DECK_QUALITY_PERSISTENCE":
            prerequisite_met = (
                event_by_kind["JUDGE_INITIAL"]["result"] != "NOT_OBSERVED"
            )
        else:
            prerequisite_met = True
        expected_result = (
            "PASS"
            if prerequisite_met and fact_values[fact_id] == precursor_sha256
            else "FAIL" if prerequisite_met else "NOT_OBSERVED"
        )
        require(
            fact_results[fact_id] == expected_result
            and (
                prerequisite_met
                or fact_values[fact_id] is None
            ),
            f"M00 native precursor fact comparison/availability drift: {source_key}/{fact_id}",
        )
    for event_index, failure_source_key in enumerate(
        precursor_context["failure_source_keys"]
    ):
        event = events[event_index]
        failure_source_sha = event["failure_source_envelope_sha256"]
        if failure_source_key is None:
            require(
                failure_source_sha is None,
                f"M00 lifecycle event {event_index} fabricates failure-source provenance",
            )
            continue
        source_position = event["source_keys"].index(failure_source_key)
        require(
            failure_source_sha == event["source_envelope_sha256s"][source_position],
            f"M00 lifecycle event {event_index} failure source key/envelope redirect drift",
        )
    no_repair_early_exit = (
        repair_count == 0
        and event_results == ["PASS", "PASS", "NOT_OBSERVED", "NOT_OBSERVED"]
        and all(
            event["not_observed_reason"] == "NOT_OBSERVED_DUE_TO_FROZEN_NO_REPAIR_EARLY_EXIT"
            for event in events[2:]
        )
    )
    if no_repair_early_exit:
        result = "FAIL"
    elif "FAIL" in event_results:
        first_failure = event_results.index("FAIL")
        require(
            event_results.count("FAIL") == 1
            and event_results[:first_failure] == ["PASS"] * first_failure
            and event_results[first_failure + 1:] == ["NOT_OBSERVED"] * (len(events) - first_failure - 1),
            "M00 transient lifecycle is not a PASS/FAIL/NOT_OBSERVED prefix",
        )
        require(
            all(
                event["not_observed_reason"]
                == "NOT_OBSERVED_DUE_TO_PRIOR_BOUND_FAILURE"
                for event in events[first_failure + 1:]
            ),
            "M00 transient failed lifecycle does not use the exact prior-bound suffix",
        )
        result = "FAIL"
    else:
        require(event_results == ["PASS"] * len(events), "M00 transient lifecycle suffix lacks a failed event")
        require(repair_count == 1, "M00 zero-repair lifecycle cannot synthesize a completed final judge")
        authoritative_export_results = [
            export["result"]
            for export in exports
            if not (
                export["source_domain"] == "COMPONENT_SOURCE"
                and export["component_source_slot_id"] in optional_component_slot_ids
            )
        ]
        result = (
            "FAIL"
            if any(export_result != "PASS" for export_result in authoritative_export_results)
            else "PASS"
        )
    pass_only_minimum_failure = (
        result == "PASS" and (call_minimum_missing or effect_minimum_missing)
    )
    if (
        call_maximum_exceeded
        or spend_ceiling_exceeded
        or effect_maximum_exceeded
        or pass_only_minimum_failure
    ):
        result = "FAIL"
    forward_call_indices = [
        index + 1 for index, export in enumerate(exports)
        if export["source_domain"] == "CALL_EVENT"
        and export["result"] != "UNAVAILABLE"
        and fact_values_by_export[index + 1].get("PHASE") == "FORWARD_M00_ATTEMPT"
    ]
    require(
        consumed_call_indices == forward_call_indices,
        "M00 transient lifecycle does not consume every forward call exactly once in order",
    )
    call_indices_in_registry = [
        index + 1 for index, export in enumerate(exports)
        if export["source_domain"] == "CALL_EVENT"
        and export["result"] != "UNAVAILABLE"
    ]
    cleanup_call_indices = [
        index for index in call_indices_in_registry
        if fact_values_by_export[index].get("PHASE")
        == "BOUND_CLEANUP_OR_SAFETY_RESTORATION"
    ]
    for cleanup_index in cleanup_call_indices:
        call_event_kind_by_export_index[cleanup_index] = "BOUND_CLEANUP_OR_SAFETY_RESTORATION"
    require(
        call_indices_in_registry == forward_call_indices + cleanup_call_indices
        and cleanup_call_indices
        == sorted(
            cleanup_call_indices,
            key=lambda call_index: (
                exports[call_index - 1]["started_at"],
                exports[call_index - 1]["ended_at"],
                exports[call_index - 1]["opaque_provider_receipt_sha256"] or "",
            ),
        ),
        "M00 transient call-event canonical order drift",
    )
    for cleanup_index in cleanup_call_indices:
        require(
            [
                row["identity_class"]
                for row in exports[cleanup_index - 1]["opaque_identity_aliases"]
            ]
            == transient["identity_classes_by_call_event_kind"]
            ["BOUND_CLEANUP_OR_SAFETY_RESTORATION"],
            "M00 transient cleanup call identity-class projection drift",
        )
    for event in events:
        require(
            event["call_export_indices"]
            == sorted(
                event["call_export_indices"],
                key=lambda call_index: (
                    exports[call_index - 1]["started_at"],
                    exports[call_index - 1]["ended_at"],
                    exports[call_index - 1]["opaque_provider_receipt_sha256"] or "",
                ),
            ),
            f"M00 transient lifecycle call order drift: {event['event_kind']}",
        )
    observed_effect_indices = [
        index + 1 for index, export in enumerate(exports)
        if export["source_domain"] == "EFFECT_EVENT"
        and export["result"] != "UNAVAILABLE"
    ]
    require(
        observed_effect_indices
        == sorted(
            observed_effect_indices,
            key=lambda effect_index: (
                exports[effect_index - 1]["started_at"],
                fact_values_by_export[effect_index]["CATEGORY"],
                fact_values_by_export[effect_index]["TARGET_CLASS"],
                fact_values_by_export[effect_index]["OPERATION"],
                exports[effect_index - 1]["opaque_provider_receipt_sha256"] or "",
            ),
        ),
        "M00 transient effect-event canonical order drift",
    )

    initial_artifacts = {
        row["artifact_sha256"] for row in events
        if row["event_kind"] in {"CREATE_INITIAL", "JUDGE_INITIAL"}
        and row["artifact_sha256"] is not None
    }
    final_artifacts = {
        row["artifact_sha256"] for row in events
        if row["event_kind"] in {"REPAIR", "JUDGE_FINAL", "AUTHENTICATED_EVIDENCE_REVIEW"}
        and row["artifact_sha256"] is not None
    }
    require(len(initial_artifacts) <= 1 and len(final_artifacts) <= 1, "M00 transient lifecycle artifact projection is inconsistent")
    initial_artifact_sha256 = next(iter(initial_artifacts), None)
    final_artifact_sha256 = next(iter(final_artifacts), None)
    require(
        initial_artifact_sha256 == held_initial_artifact_sha256
        and final_artifact_sha256 == held_final_artifact_sha256,
        "M00 transient lifecycle artifacts do not equal the held descriptor identities/sentinels",
    )

    def event_materialized(event_kind: str) -> bool:
        event = event_by_kind.get(event_kind)
        return bool(
            event is not None
            and event["result"] != "NOT_OBSERVED"
            and (event["source_export_indices"] or event["call_export_indices"])
        )

    derived_role_availability: dict[str, bool] = {
        "INITIAL_QUALITY_RUN": event_materialized("JUDGE_INITIAL"),
        "INITIAL_QUALITY_ATTEMPT": event_materialized("JUDGE_INITIAL"),
        "FINAL_QUALITY_RUN": event_materialized("JUDGE_FINAL"),
        "FINAL_QUALITY_ATTEMPT": event_materialized("JUDGE_FINAL"),
        "BUILD_MUTATION_TRANSACTION": event_materialized("REPAIR"),
        "INITIAL_ARTIFACT_PUBLICATION": initial_artifact_sha256 is not None,
        "FINAL_ARTIFACT_PUBLICATION": final_artifact_sha256 is not None,
    }
    for identity_class, expected_available in derived_role_availability.items():
        has_available_claim = any(
            claim["availability"] == "AVAILABLE"
            for claim in identity_claims_by_class[identity_class]
        )
        if has_available_claim != expected_available:
            identity_projection_conflict = True

    def export_identity_descriptor(export_index: int) -> str:
        export = exports[export_index - 1]
        domain = export["source_domain"]
        if domain == "COMPONENT_SOURCE":
            return f"{domain}:{export['component_source_slot_id']}"
        if domain == "CALL_EVENT":
            return f"{domain}:{call_event_kind_by_export_index[export_index]}"
        return f"{domain}:{export['source_key']}"

    identity_projection_rows: list[dict[str, Any]] = []
    for sequence, identity_class in enumerate(runtime_contract["required_identity_classes"], start=1):
        if identity_class == "SYNTHETIC_SCOPE":
            availability = "AVAILABLE"
            alias = expected_synthetic_scope_alias
            projection_sha256 = sha256_bytes(canonical_json_bytes([
                "FC01_M00_OPAQUE_IDENTITY_PROJECTION_V1",
                identity_class,
                alias,
            ]))
            source_export_index = None
            unavailable_reason = None
        else:
            available_claims = [
                (export_index, claim)
                for export_index, export in enumerate(exports, start=1)
                for claim in export["opaque_identity_aliases"]
                if claim["identity_class"] == identity_class
                and claim["availability"] == "AVAILABLE"
            ]
            if available_claims:
                precedence = runtime_contract["identity_source_precedence_by_class"][identity_class]
                selected = next(
                    (
                        export_index
                        for descriptor in precedence
                        for export_index, _claim in available_claims
                        if export_identity_descriptor(export_index) == descriptor
                    ),
                    None,
                )
                require(selected is not None, f"M00 transient identity has no authorized precedence source: {identity_class}")
                selected_claim = next(
                    claim for export_index, claim in available_claims if export_index == selected
                )
                alias = selected_claim["opaque_alias"]
                projection_sha256 = selected_claim["projection_sha256"]
                if not all(
                    claim["opaque_alias"] == alias
                    and claim["projection_sha256"] == projection_sha256
                    for _export_index, claim in available_claims
                ):
                    identity_projection_conflict = True
                availability = "AVAILABLE"
                source_export_index = selected
                unavailable_reason = None
            else:
                alias = None
                projection_sha256 = None
                source_export_index = None
                availability = (
                    "NOT_CREATED"
                    if identity_class in derived_role_availability
                    else "NOT_OBSERVED"
                )
                unavailable_reason = runtime_contract["identity_projection_status_by_availability"][availability]
                if not all(
                    claim["availability"] == availability
                    for claim in identity_claims_by_class[identity_class]
                ):
                    identity_projection_conflict = True
        identity_projection_rows.append({
            "sequence": sequence,
            "identity_class": identity_class,
            "opaque_alias": alias,
            "projection_sha256": projection_sha256,
            "source_registry_sequence": source_export_index,
            "availability": availability,
            "unavailable_reason": unavailable_reason,
            "status": runtime_contract["identity_projection_status_by_availability"][availability],
        })
    for initial_class, final_class in (
        ("INITIAL_QUALITY_RUN", "FINAL_QUALITY_RUN"),
        ("INITIAL_QUALITY_ATTEMPT", "FINAL_QUALITY_ATTEMPT"),
        ("INITIAL_ARTIFACT_PUBLICATION", "FINAL_ARTIFACT_PUBLICATION"),
    ):
        initial_row = next(row for row in identity_projection_rows if row["identity_class"] == initial_class)
        final_row = next(row for row in identity_projection_rows if row["identity_class"] == final_class)
        if initial_row["availability"] == final_row["availability"] == "AVAILABLE":
            if initial_row["opaque_alias"] == final_row["opaque_alias"]:
                identity_projection_conflict = True

    reached_event_kinds = {
        event["event_kind"] for event in events if event["result"] != "NOT_OBSERVED"
    }
    attempted_categories: list[str] = []
    expected_component_slot_ids: list[str] = []
    actual_component_slot_ids = [
        export["component_source_slot_id"] for export in component_exports
    ]
    for category in component_contract["component_category_values"]:
        prerequisite = component_contract["component_availability_prerequisite_by_category"][category]
        attempted = (
            set(prerequisite["required_event_kinds"]) <= reached_event_kinds
            and (not prerequisite["requires_initial_artifact"] or initial_artifact_sha256 is not None)
            and (not prerequisite["requires_final_artifact"] or final_artifact_sha256 is not None)
        )
        if not attempted:
            continue
        attempted_categories.append(category)
        slots = component_contract["component_source_slots_by_category"][category]
        expected_component_slot_ids.extend(
            slot["source_slot_id"] for slot in slots
            if slot["required"] or slot["source_slot_id"] in actual_component_slot_ids
        )
    require(
        actual_component_slot_ids == expected_component_slot_ids,
        "M00 transient component-source slots are not the exact independently attempted catalog",
    )
    if "mechanical_validity" in attempted_categories:
        require(
            "mechanical_validity/0001/SEALED_PPTX_PACKAGE_VALIDATOR"
            in actual_component_slot_ids,
            "M00 attempted mechanical component omits the signed sealed PPTX validator",
        )

    identity_projection_by_class = {
        row["identity_class"]: row for row in identity_projection_rows
    }
    effect_coverage_available = {
        export["source_key"]: export["result"] != "UNAVAILABLE"
        for export in effect_coverage_exports
    }
    component_slot_catalog = {
        slot["source_slot_id"]: (category, slot)
        for category in component_contract["component_category_values"]
        for slot in component_contract["component_source_slots_by_category"][category]
    }

    def component_fact_prerequisite(
        token: str,
        export: dict[str, Any],
        fact_values: dict[str, Any],
    ) -> bool:
        source_reached = export["result"] != "UNAVAILABLE"
        closed_values = {
            "GATEWAY_ARTIFACT_API_EXPORT_REACHED": source_reached,
            "ARTIFACT_RETRIEVED_OBSERVED_TRUE": (
                source_reached and fact_values.get("ARTIFACT_RETRIEVED") is True
            ),
            "FINAL_ARTIFACT_DESCRIPTOR_AVAILABLE": final_artifact_sha256 is not None,
            "PPTX_CONTAINER_VALID_OBSERVED_TRUE": (
                source_reached and fact_values.get("PPTX_CONTAINER_VALID") is True
            ),
            "AUTHENTICATED_RENDER_EXPORT_REACHED_WITH_FINAL_ARTIFACT": (
                source_reached and final_artifact_sha256 is not None
            ),
            "FROZEN_MECHANICAL_RUBRIC_EXPORT_REACHED_WITH_FINAL_ARTIFACT_AND_D2_RUBRIC": (
                source_reached and final_artifact_sha256 is not None
            ),
            "INITIAL_ARTIFACT_PUBLICATION_DIGEST_AVAILABLE": initial_artifact_sha256 is not None,
            "INITIAL_ARTIFACT_PUBLICATION_EXPORT_REACHED": source_reached,
            "FINAL_ARTIFACT_PUBLICATION_DIGEST_AVAILABLE": final_artifact_sha256 is not None,
            "FINAL_ARTIFACT_PUBLICATION_EXPORT_REACHED": source_reached,
            "JUDGE_INITIAL_EVENT_REACHED": event_by_kind["JUDGE_INITIAL"]["result"] != "NOT_OBSERVED",
            "JUDGE_FINAL_EVENT_REACHED": event_by_kind["JUDGE_FINAL"]["result"] != "NOT_OBSERVED",
            "JUDGE_INITIAL_EVENT_REACHED_WITH_D2_RUBRIC": (
                event_by_kind["JUDGE_INITIAL"]["result"] != "NOT_OBSERVED"
            ),
            "INITIAL_AND_FINAL_QUALITY_RUNS_AVAILABLE": (
                identity_projection_by_class["INITIAL_QUALITY_RUN"]["availability"] == "AVAILABLE"
                and identity_projection_by_class["FINAL_QUALITY_RUN"]["availability"] == "AVAILABLE"
            ),
            "GATEWAY_RUNTIME_EXPORT_REACHED": source_reached,
            "LANGGRAPH_RUNTIME_EXPORT_REACHED": source_reached,
            "GATEWAY_TERMINAL_EVENT_OBSERVED": source_reached,
            "AUTHENTICATED_EVIDENCE_REVIEW_EVENT_REACHED": (
                event_by_kind["AUTHENTICATED_EVIDENCE_REVIEW"]["result"] != "NOT_OBSERVED"
            ),
            "SIGNED_FINAL_ARTIFACT_DOWNLOAD_OBSERVATION_PRESENT": (
                source_reached and final_artifact_sha256 is not None
            ),
            "GATEWAY_SESSION_STORE_EXPORT_REACHED": source_reached,
            "PRIVATE_ARTIFACT_STORE_EXPORT_REACHED": source_reached,
            "LANGGRAPH_CHECKPOINTER_EXPORT_REACHED": source_reached,
            "BROWSER_CORRELATION_EXPORT_REACHED": source_reached,
            "GATEWAY_CORRELATION_EXPORT_REACHED": source_reached,
            "LANGGRAPH_CORRELATION_EXPORT_REACHED": source_reached,
            "LANGSMITH_SUPPLEMENTAL_EXPORT_REACHED": source_reached,
            "GATEWAY_SESSION_EFFECT_COVERAGE_AVAILABLE": effect_coverage_available.get(
                "SYNTHETIC_SESSION_STORE", False
            ),
            "LANGGRAPH_CHECKPOINTER_EFFECT_COVERAGE_AVAILABLE": effect_coverage_available.get(
                "SYNTHETIC_CHECKPOINTER", False
            ),
            "PRIVATE_ARTIFACT_EFFECT_COVERAGE_AVAILABLE": effect_coverage_available.get(
                "SYNTHETIC_ARTIFACT_OR_STORAGE", False
            ),
        }
        require(token in closed_values, f"M00 component fact prerequisite token is unknown: {token}")
        return closed_values[token]

    for component_index, export in enumerate(exports, start=1):
        if export["source_domain"] != "COMPONENT_SOURCE":
            continue
        category, slot = component_slot_catalog[export["component_source_slot_id"]]
        fact_values = fact_values_by_export[component_index]
        fact_results = fact_results_by_export[component_index]
        required_specs = component_contract["required_fact_contract_by_category"][category]
        optional_specs = component_contract.get("optional_fact_contract_by_category", {}).get(
            category, {}
        )
        source_specs = (
            component_contract["required_source_contract_by_category"][category]
            + component_contract.get("optional_source_contract_by_category", {}).get(
                category, []
            )
        )
        source_spec = next(
            spec for spec in source_specs
            if spec["source_system"] == slot["source_system"]
        )
        all_category_specs = required_specs | optional_specs
        all_specs = {
            fact_id: all_category_specs[fact_id]
            for fact_id in source_spec["owned_fact_ids"]
        }
        prerequisite_by_fact = (
            component_contract["fact_availability_prerequisite_by_category"][category]
            | component_contract.get("optional_fact_availability_prerequisite_by_category", {}).get(
                category, {}
            )
        )
        expected_fact_results: dict[str, str] = {}
        for fact_id, spec in all_specs.items():
            prerequisite_met = component_fact_prerequisite(
                prerequisite_by_fact[fact_id], export, fact_values,
            )
            if export["result"] == "UNAVAILABLE":
                prerequisite_met = False
            if not prerequisite_met:
                expected_fact_results[fact_id] = "NOT_OBSERVED"
                require(
                    fact_values[fact_id] is None,
                    f"M00 component unavailable fact retains a value: {export['component_source_slot_id']}/{fact_id}",
                )
                continue
            expected_value: Any = None
            expected_value_known = False
            if "expected_value" in spec:
                expected_value = spec["expected_value"]
                expected_value_known = True
            elif spec.get("expected_from") == "parent.initial_artifact_sha256":
                expected_value = initial_artifact_sha256
                expected_value_known = True
            elif spec.get("expected_from") == "parent.final_artifact_sha256":
                expected_value = final_artifact_sha256
                expected_value_known = True
            if expected_value_known:
                expected_fact_results[fact_id] = (
                    "PASS" if fact_values[fact_id] == expected_value else "FAIL"
                )
            else:
                require(
                    spec.get("non_authoritative") is True
                    and isinstance(fact_values[fact_id], bool),
                    f"M00 component fact lacks a closed expectation: {category}/{fact_id}",
                )
                expected_fact_results[fact_id] = (
                    "PASS" if fact_values[fact_id] is True else "FAIL"
                )
        require(
            fact_results == expected_fact_results,
            f"M00 component fact availability/result derivation drift: {export['component_source_slot_id']}",
        )
        if export["result"] == "UNAVAILABLE":
            expected_source_result = "UNAVAILABLE"
        elif "FAIL" in expected_fact_results.values():
            expected_source_result = "FAIL"
        elif "NOT_OBSERVED" in expected_fact_results.values():
            expected_source_result = "PARTIAL"
        else:
            expected_source_result = "PASS"
        require(
            export["result"] == expected_source_result,
            f"M00 component source result is not fact-derived: {export['component_source_slot_id']}",
        )
    if identity_projection_conflict:
        result = "FAIL"

    event_projection_sha256 = sha256_bytes(canonical_json_bytes([
        row["stable_event_projection_sha256"] for row in runtime_event_rows
    ]))
    native_facts = {
        key: fact_values_by_export[
            next(index + 1 for index, export in enumerate(exports)
                 if export["source_domain"] == "NATIVE_LIFECYCLE" and export["source_key"] == key)
        ]
        for key in native_keys
    }
    design = native_facts.get("LANGGRAPH_DECK_DESIGN_LIFT_RUNTIME")
    persistence = native_facts.get("LANGGRAPH_DECK_QUALITY_PERSISTENCE")
    terminal_tokens = [
        facts["TERMINAL_STATE"]
        for facts in (design, persistence)
        if facts is not None and facts.get("TERMINAL_STATE") is not None
    ]
    if terminal_tokens:
        require(
            len(set(terminal_tokens)) == 1
            and terminal_tokens[0] in runtime_contract["native_runtime_result_values"],
            "M00 transient native terminal projections disagree or are not closed",
        )
        native_runtime_result = terminal_tokens[0]
    else:
        first_reached_failure = next(
            (event for event in events if event["result"] == "FAIL"),
            None,
        )
        require(
            first_reached_failure is not None
            and first_reached_failure["failure_signal_code"]
            in runtime_contract["direct_pre_provider_lifecycle_failure_signal_code_values"]
            and first_reached_failure["failure_source_envelope_sha256"] is None
            and first_reached_failure["failure_call_envelope_sha256"] is None,
            "M00 transient lacks an authenticated native terminal or direct pre-provider FAIL",
        )
        native_runtime_result = "FAIL"
    native_runtime_status = runtime_contract["native_runtime_status_by_result"][
        native_runtime_result
    ]
    require(
        (native_runtime_result == "NO_REPAIR_NEEDED") == no_repair_early_exit,
        "M00 transient frozen no-repair lifecycle/native-terminal shape drift",
    )
    if no_repair_early_exit:
        for identity_class in ("INITIAL_QUALITY_RUN", "INITIAL_QUALITY_ATTEMPT", "INITIAL_ARTIFACT_PUBLICATION"):
            require(
                identity_claims_by_class[identity_class]
                and any(
                    row["availability"] == "AVAILABLE"
                    for row in identity_claims_by_class[identity_class]
                ),
                f"M00 frozen no-repair path omits available initial role: {identity_class}",
            )
        for identity_class in ("FINAL_QUALITY_RUN", "FINAL_QUALITY_ATTEMPT", "FINAL_ARTIFACT_PUBLICATION"):
            require(
                identity_claims_by_class[identity_class]
                and all(
                    row["availability"] == "NOT_CREATED"
                    for row in identity_claims_by_class[identity_class]
                ),
                f"M00 frozen no-repair path fabricates or misclassifies final role: {identity_class}",
            )
    if design is not None and design.get("TERMINAL_STATE") is not None:
        require(
            design["ATTEMPT_COUNT"] == 1
            and design["REPAIR_COUNT"] == repair_count
            and design["EVENT_SEQUENCE_SHA256"] == precursor_sha256
            and design["TERMINAL_STATE"] == native_runtime_result,
            "M00 transient native attempt/stage/terminal projection drift",
        )
    if persistence is not None and persistence.get("TERMINAL_STATE") is not None:
        require(
            persistence["ATTEMPT_COUNT"] == 1
            and persistence["MAX_ATTEMPTS"] >= persistence["ATTEMPT_COUNT"]
            and persistence["QUALITY_RUN_IDEMPOTENCY_BOUND"] is True
            and persistence["STAGE_ORDER_SHA256"] == precursor_sha256
            and persistence["TERMINAL_STATE"] == native_runtime_result,
            "M00 transient persistence attempt/stage/terminal projection drift",
        )
    comparator = native_facts.get("LANGGRAPH_DECK_QUALITY_COMPARATOR")
    if result == "PASS":
        require(
            native_runtime_result == "PASS"
            and set(native_facts) == set(runtime_contract["required_native_lifecycle_source_keys"]),
            "M00 transient aggregate PASS lacks the complete native PASS projection",
        )
        event_by_kind = {event["event_kind"]: event for event in events}
        expected_from_values = {
            "native_lifecycle_precursor_manifest_sha256": precursor_sha256,
            "INITIAL_QUALITY_RUN.projection_sha256": native_aliases_by_class["INITIAL_QUALITY_RUN"][1],
            "FINAL_QUALITY_RUN.projection_sha256": native_aliases_by_class["FINAL_QUALITY_RUN"][1],
            "CREATE_INITIAL.artifact_sha256": event_by_kind["CREATE_INITIAL"]["artifact_sha256"],
            "REPAIR.artifact_sha256": event_by_kind["REPAIR"]["artifact_sha256"],
        }
        for source_key in runtime_contract["required_native_lifecycle_source_keys"]:
            source_index = next(
                index + 1
                for index, export in enumerate(exports)
                if export["source_domain"] == "NATIVE_LIFECYCLE"
                and export["source_key"] == source_key
            )
            source_facts = native_facts[source_key]
            source_results = fact_results_by_export[source_index]
            require(
                set(source_results.values()) == {"PASS"},
                f"M00 transient native PASS source contains a non-PASS fact: {source_key}",
            )
            for fact_id, expectation in transient["native_pass_expectation_by_source_key"][source_key].items():
                fact_value = source_facts[fact_id]
                if "expected_value" in expectation:
                    require(
                        fact_value == expectation["expected_value"],
                        f"M00 transient native PASS expectation drift: {source_key}/{fact_id}",
                    )
                if "expected_from" in expectation:
                    require(
                        fact_value == expected_from_values[expectation["expected_from"]],
                        f"M00 transient native PASS source binding drift: {source_key}/{fact_id}",
                    )
                if expectation.get("constraint") == "INTEGER_AT_LEAST_ATTEMPT_COUNT":
                    require(
                        exact_nonnegative_int(fact_value)
                        and fact_value >= source_facts["ATTEMPT_COUNT"],
                        f"M00 transient native PASS integer constraint drift: {source_key}/{fact_id}",
                    )
                if "must_differ_from" in expectation:
                    require(
                        fact_value != source_facts[expectation["must_differ_from"]],
                        f"M00 transient native PASS role identities collapse: {source_key}/{fact_id}",
                    )
    if result == "PASS" and comparator is not None:
        require(
            comparator["INITIAL_QUALITY_RUN_SHA256"] != comparator["FINAL_QUALITY_RUN_SHA256"]
            and comparator["APPROVED_IMPROVEMENT"] is True
            and comparator["PRESERVATION_PASS"] is True
            and comparator["STRICT_SCORE_IMPROVEMENT_IF_REPAIRED"] is True,
            "M00 transient comparator projection drift",
        )
    artifact_registry = native_facts.get("GATEWAY_ARTIFACT_REGISTRY")
    if result == "PASS" and artifact_registry is not None:
        require(
            artifact_registry["INITIAL_ARTIFACT_SHA256"] == initial_artifact_sha256
            and artifact_registry["FINAL_ARTIFACT_SHA256"] == final_artifact_sha256
            and artifact_registry["PUBLICATION_COUNT"] == 2
            and artifact_registry["OWNERSHIP_BOUND"] is True,
            "M00 transient artifact-registry projection drift",
        )
    canvas = native_facts.get("GATEWAY_BUILDER_CANVAS_HISTORY")
    if result == "PASS" and canvas is not None:
        require(
            canvas["ORDERED_EVENT_STREAM_SHA256"] == precursor_sha256
            and canvas["TERMINAL_EVENT_COUNT"] == 1
            and canvas["RUN_DRIFT_REJECTED"] is True,
            "M00 transient builder-event projection drift",
        )
    browser = native_facts.get("AUTHENTICATED_VERCEL_BROWSER_REVIEW")
    if result == "PASS" and browser is not None:
        require(
            browser["AUTHENTICATED_REVIEW_PASS"] is True
            and browser["FINAL_ARTIFACT_DOWNLOAD_PASS"] is True
            and browser["FINAL_ARTIFACT_SHA256"] == final_artifact_sha256,
            "M00 transient authenticated-browser projection drift",
        )
    if expected_synthetic_scope_alias is not None:
        require(
            identity_projection_by_class["SYNTHETIC_SCOPE"]["availability"] == "AVAILABLE"
            and identity_projection_by_class["SYNTHETIC_SCOPE"]["opaque_alias"]
            == expected_synthetic_scope_alias,
            "M00 transient D2-derived synthetic-scope identity drift",
        )
    return {
        "exports": exports,
        "fact_values_by_export": fact_values_by_export,
        "runtime_event_rows": runtime_event_rows,
        "repair_count": repair_count,
        "result": result,
        "native_runtime_result": native_runtime_result,
        "native_runtime_status": native_runtime_status,
        "call_counts_by_category": call_counts_by_category,
        "actual_total_calls": actual_total_calls,
        "actual_spend_usd": actual_spend_usd,
        "call_minimum_missing": call_minimum_missing,
        "call_maximum_exceeded": call_maximum_exceeded,
        "spend_ceiling_exceeded": spend_ceiling_exceeded,
        "effect_counts_by_category": effect_counts_by_category,
        "effect_minimum_missing": effect_minimum_missing,
        "effect_maximum_exceeded": effect_maximum_exceeded,
        "initial_artifact_sha256": initial_artifact_sha256,
        "final_artifact_sha256": final_artifact_sha256,
        "native_aliases_by_class": native_aliases_by_class,
        "identity_projection_rows": identity_projection_rows,
        "native_lifecycle_precursor_manifest_sha256": precursor_sha256,
        "event_projection_sha256": event_projection_sha256,
    }


def _self_test_m00_fact_row(
    fact_id: str,
    value_type: str,
    value: Any,
    *,
    result: str = "PASS",
    not_observed_reason: Optional[str] = None,
) -> dict[str, Any]:
    value_field = {
        "BOOLEAN": "boolean_value",
        "INTEGER": "integer_value",
        "NUMBER": "number_value",
        "CLOSED_TOKEN": "token_value",
        "SHA256": "sha256_value",
    }[value_type]
    row = {
        "fact_id": fact_id,
        "value_type": value_type,
        "boolean_value": None,
        "integer_value": None,
        "number_value": None,
        "token_value": None,
        "sha256_value": None,
        "not_observed_reason": not_observed_reason,
        "result": result,
    }
    if result != "NOT_OBSERVED":
        row[value_field] = value
    return row


def _self_test_m00_alias_row(
    identity_class: str,
    opaque_alias: Optional[str],
    runtime_contract: dict[str, Any],
    *,
    availability: str = "AVAILABLE",
) -> dict[str, Any]:
    if availability == "AVAILABLE":
        require(opaque_alias is not None, "M00 self-test available alias is null")
        projection = sha256_bytes(canonical_json_bytes([
            "FC01_M00_OPAQUE_IDENTITY_PROJECTION_V1",
            identity_class,
            opaque_alias,
        ]))
        reason = None
    else:
        projection = None
        opaque_alias = None
        reason = runtime_contract["identity_projection_status_by_availability"][availability]
    return {
        "identity_class": identity_class,
        "opaque_alias": opaque_alias,
        "projection_sha256": projection,
        "availability": availability,
        "unavailable_reason": reason,
    }


def _self_test_m00_trust_registry(
    schema: dict[str, Any],
    packet: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    trust_contract = schema["supporting_receipt_contracts"][
        "m00_authenticated_export_trust_registry"
    ]
    modulus_hex, public_exponent = _self_test_rsa_pss_public_key()
    public_key_sha256 = sha256_bytes(canonical_json_bytes([
        "FC01_M00_RSA_PSS_PUBLIC_KEY_V1", modulus_hex, public_exponent,
    ]))
    domain_rank = {
        domain: index
        for index, domain in enumerate(trust_contract["attester_source_domain_values"])
    }
    expected = sorted(
        derive_m00_expected_trust_authorizations(schema),
        key=lambda row: (domain_rank[row[0]], row[1], row[2]),
    )
    nonaggregate = [row for row in expected if row[0] != "WHOLE_TRANSIENT_CAPTURE"]
    aggregate_authorization = next(
        row for row in expected if row[0] == "WHOLE_TRANSIENT_CAPTURE"
    )
    authorizations = nonaggregate + [aggregate_authorization]
    rows: list[dict[str, Any]] = []
    for sequence, (source_domain, source_key, slots) in enumerate(
        authorizations, start=1,
    ):
        is_aggregate = source_domain == "WHOLE_TRANSIENT_CAPTURE"
        rows.append({
            "sequence": sequence,
            "attester_id": f"m00-selftest-attester-{sequence:04d}",
            "attestation_key_id": "m00-selftest-rsa-key-0001",
            "source_domain": source_domain,
            "source_key_or_class": source_key,
            "component_source_slot_ids": list(slots),
            "provider_receipt_projection_group_ids": [],
            "covered_attester_sequences": (
                list(range(1, len(nonaggregate) + 1)) if is_aggregate else []
            ),
            "collector_algorithm_id": "m00-selftest-readonly-collector-v1",
            "collector_implementation_sha256": sha256_bytes(
                f"collector-{sequence}".encode("ascii")
            ),
            "source_adapter_id": f"m00-selftest-source-adapter-{sequence:04d}",
            "source_adapter_contract_sha256": sha256_bytes(
                f"adapter-{sequence}".encode("ascii")
            ),
            "attestation_algorithm": trust_contract["attestation_algorithm"],
            "rsa_modulus_hex": modulus_hex,
            "rsa_public_exponent": public_exponent,
            "public_key_sha256": public_key_sha256,
            "valid_from": "2026-08-17T20:00:00Z",
            "valid_through": "2026-08-18T04:00:00Z",
            "read_only_collection": True,
        })
    aggregate = rows[-1]
    registry = {
        "schema_version": 1,
        "record_type": trust_contract["record_type"],
        "campaign_id": CAMPAIGN_ID,
        "amendment_id": AMENDMENT_ID,
        "created_at": "2026-08-17T23:55:00Z",
        "candidate_sha": packet["candidate_sha"],
        "candidate_tree": packet["candidate_tree"],
        "whole_capture_attester_sequence": aggregate["sequence"],
        "capture_attester_id": aggregate["attester_id"],
        "capture_attestation_key_id": aggregate["attestation_key_id"],
        "attester_rows": rows,
        "attester_count": len(rows),
        "attester_manifest_sha256": sha256_bytes(canonical_json_bytes(rows)),
        "raw_private_key_credential_or_source_payload_stored": False,
        "status": "PASS",
    }
    return registry, validate_m00_authenticated_export_trust_registry(
        registry, trust_contract, packet, schema, label="M00 signed transient self-test trust",
    )


def _self_test_build_signed_m00_transient_pass(
    schema: dict[str, Any],
) -> dict[str, Any]:
    runtime = schema["supporting_receipt_contracts"]["m00_runtime_observation_bundle"]
    finalizer = schema["supporting_receipt_contracts"][
        "m00_runtime_finalization_receipt"
    ]
    transient = finalizer["transient_observation_bundle_contract"]
    component = schema["supporting_receipt_contracts"]["m00_component_evidence"]
    call_coverage_contract = schema["supporting_receipt_contracts"][
        "m00_call_observer_coverage"
    ]
    effect_coverage_contract = schema["supporting_receipt_contracts"][
        "m00_effect_observer_coverage"
    ]
    effect_observation_contract = schema["supporting_receipt_contracts"][
        "m00_effect_observation"
    ]
    call_budget_contract = schema["supporting_receipt_contracts"]["m00_call_budget"]
    effects_contract = schema["supporting_receipt_contracts"][
        "m00_data_artifact_effects"
    ]
    candidate = ("a" * 40, "b" * 40)
    scope_alias = "synthetic-scope-fixture-0001"
    consumption_ref = {
        "path": f"{EVIDENCE_REL.as_posix()}/m00-selftest/d2-consumption.json",
        "sha256": "c" * 64,
    }
    attempt_id = sha256_bytes(canonical_json_bytes([
        1, AMENDMENT_ID, consumption_ref["path"], consumption_ref["sha256"],
        candidate[0], candidate[1],
    ]))
    capture_started = "2026-08-18T00:00:00.000000Z"
    capture_ended = "2026-08-18T00:01:00.000000Z"
    signed_at = "2026-08-18T00:01:01.000000Z"
    consumed_at = parse_m00_deterministic_time(capture_started, "M00 self-test consumed_at")
    finalizer_started_at = parse_m00_deterministic_time(
        "2026-08-18T00:01:02.000000Z", "M00 self-test finalizer start",
    )
    initial_artifact_sha256 = "1" * 64
    final_artifact_sha256 = "2" * 64
    implementation_ref = {
        "path": f"{EVIDENCE_REL.as_posix()}/fc01-v1.3-amendment-b-20260817t194401z/evaluator.py",
        "sha256": "e" * 64,
    }
    packet = {
        "gate_id": "FC01-D2",
        "candidate_sha": candidate[0],
        "candidate_tree": candidate[1],
        "window": {
            "starts_at": "2026-08-17T23:50:00Z",
            "ends_at": "2026-08-18T02:00:00Z",
        },
    }
    trust_registry, trust_context = _self_test_m00_trust_registry(schema, packet)
    trust_contract = schema["supporting_receipt_contracts"][
        "m00_authenticated_export_trust_registry"
    ]

    call_budget_rows = []
    minimums = call_budget_contract["required_category_minimums"]
    maximums = {
        "artifact_generation": 2,
        "frozen_quality_judge": 3,
        "artifact_repair": 1,
    }
    for category in call_budget_contract["required_category_order"]:
        call_budget_rows.append({
            "category": category,
            "provider_policy_id": f"m00-provider-policy-{category}",
            "observation_mode": call_budget_contract[
                "required_category_observation_modes"
            ][category],
            "minimum_calls": minimums[category],
            "maximum_calls": maximums[category],
        })
    call_budget = {
        "call_categories": call_budget_rows,
        "minimum_total_calls": sum(row["minimum_calls"] for row in call_budget_rows),
        "maximum_total_calls": sum(row["maximum_calls"] for row in call_budget_rows),
    }
    spend_budget = {"maximum_spend": 10.0}
    expected_effects = {
        "candidate_sha": candidate[0],
        "candidate_tree": candidate[1],
        "synthetic_scope_alias": scope_alias,
        "effect_rows": [
            {
                **row,
                "sequence": index,
                "synthetic_scope_alias": scope_alias,
                "minimum_count": 1,
                "maximum_count": 2,
            }
            for index, row in enumerate(effects_contract["required_effect_rows"], start=1)
        ],
    }
    aliases = {
        "THREAD_TASK_BUILD_RUN": "thread-runtime-run-fixture-0001",
        "INITIAL_QUALITY_RUN": "initial-quality-run-fixture-0001",
        "FINAL_QUALITY_RUN": "final-quality-run-fixture-0002",
        "INITIAL_QUALITY_ATTEMPT": "initial-quality-attempt-fixture-0001",
        "FINAL_QUALITY_ATTEMPT": "final-quality-attempt-fixture-0002",
        "BUILD_MUTATION_TRANSACTION": "build-mutation-transaction-fixture-0001",
        "INITIAL_ARTIFACT_PUBLICATION": "initial-artifact-publication-fixture-0001",
        "FINAL_ARTIFACT_PUBLICATION": "final-artifact-publication-fixture-0002",
        "BUILDER_EVENT_STREAM": "builder-event-stream-fixture-0001",
        "SYNTHETIC_SCOPE": scope_alias,
    }

    authorization_rows = trust_registry["attester_rows"]

    def attester_sequence(domain: str, key: str, slot: Optional[str]) -> int:
        matching = [
            row for row in authorization_rows
            if row["source_domain"] == domain
            and row["source_key_or_class"] == key
            and (
                domain != "COMPONENT_SOURCE"
                or slot in row["component_source_slot_ids"]
            )
        ]
        require(len(matching) == 1, f"M00 self-test attester lookup drift: {domain}/{key}/{slot}")
        return matching[0]["sequence"]

    export_counter = 0

    def alias_rows(classes: list[str]) -> list[dict[str, Any]]:
        return [
            _self_test_m00_alias_row(identity_class, aliases[identity_class], runtime)
            for identity_class in classes
        ]

    def source_export(
        domain: str,
        key: str,
        facts: list[dict[str, Any]],
        identity_classes: list[str],
        *,
        slot: Optional[str] = None,
        observer_mode: str = "PROVIDER_AUTHENTICATED",
        started_at: str = "2026-08-18T00:00:01.000000Z",
        ended_at: str = "2026-08-18T00:00:59.000000Z",
        observed_event_count: int = 1,
    ) -> dict[str, Any]:
        nonlocal export_counter
        export_counter += 1
        if domain in runtime["full_coverage_source_domain_values"]:
            started_at, ended_at = capture_started, capture_ended
        if observer_mode == "SEALED_LOCAL":
            provider_id = provider_sha = None
            provider_null_reason = transient["source_export_local_null_reason"]
            local_ref: Optional[dict[str, Any]] = implementation_ref
        else:
            provider_id = f"m00-selftest-provider-receipt-{export_counter:04d}"
            provider_sha = sha256_bytes(provider_id.encode("ascii"))
            provider_null_reason = None
            local_ref = None
        row = {
            "source_domain": domain,
            "source_key": key,
            "component_source_slot_id": slot,
            "source_attester_sequence": attester_sequence(domain, key, slot),
            "source_envelope_id": None,
            "source_envelope_sha256": None,
            "observer_mode": observer_mode,
            "started_at": started_at,
            "ended_at": ended_at,
            "observed_event_count": observed_event_count,
            "opaque_identity_aliases": alias_rows(identity_classes),
            "minimized_fact_rows": facts,
            "opaque_provider_receipt_id": provider_id,
            "opaque_provider_receipt_sha256": provider_sha,
            "provider_receipt_projection_group_id": None,
            "provider_receipt_null_reason": provider_null_reason,
            "sealed_local_observer_ref": local_ref,
            "failure_signal_code": None,
            "unavailable_reason": None,
            "result": "PASS",
            "status": transient["source_export_result_status_contract"]["PASS"][observer_mode],
            "raw_content_present": False,
        }
        projection = [
            "FC01_M00_SIGNED_SOURCE_ENVELOPE_V1",
            row["source_domain"], row["source_key"], row["component_source_slot_id"],
            row["source_attester_sequence"], row["observer_mode"], row["started_at"],
            row["ended_at"], row["observed_event_count"], row["opaque_identity_aliases"],
            row["minimized_fact_rows"], row["opaque_provider_receipt_id"],
            row["opaque_provider_receipt_sha256"], row["provider_receipt_projection_group_id"],
            row["provider_receipt_null_reason"], row["sealed_local_observer_ref"],
            row["failure_signal_code"], row["unavailable_reason"], row["result"],
            row["status"], row["raw_content_present"],
        ]
        digest = sha256_bytes(canonical_json_bytes(projection))
        row["source_envelope_id"] = digest
        row["source_envelope_sha256"] = digest
        return row

    call_specs = [
        ("CREATE_INITIAL", "artifact_generation", "2026-08-18T00:00:12.000000Z", "2026-08-18T00:00:13.000000Z"),
        ("JUDGE_INITIAL", "frozen_quality_judge", "2026-08-18T00:00:22.000000Z", "2026-08-18T00:00:23.000000Z"),
        ("JUDGE_FINAL", "frozen_quality_judge", "2026-08-18T00:00:42.000000Z", "2026-08-18T00:00:43.000000Z"),
    ]
    budget_by_category = {row["category"]: row for row in call_budget_rows}
    call_exports: list[dict[str, Any]] = []
    for owner_kind, category, started, ended in call_specs:
        budget_row = budget_by_category[category]
        facts = [
            _self_test_m00_fact_row("PHASE", "CLOSED_TOKEN", "FORWARD_M00_ATTEMPT"),
            _self_test_m00_fact_row("CATEGORY", "CLOSED_TOKEN", category),
            _self_test_m00_fact_row("PROVIDER_POLICY_ID", "CLOSED_TOKEN", budget_row["provider_policy_id"]),
            _self_test_m00_fact_row("OUTCOME", "CLOSED_TOKEN", "PASS"),
            _self_test_m00_fact_row("COST_USD", "NUMBER", 1.0),
        ]
        call_exports.append(source_export(
            "CALL_EVENT", category, facts,
            transient["identity_classes_by_call_event_kind"][owner_kind],
            started_at=started, ended_at=ended,
        ))

    lifecycle_semantics: list[dict[str, Any]] = []
    call_by_owner = {
        owner: call_export for (owner, _category, _start, _end), call_export
        in zip(call_specs, call_exports)
    }
    lifecycle_times = [
        ("2026-08-18T00:00:10.000000Z", "2026-08-18T00:00:19.000000Z"),
        ("2026-08-18T00:00:20.000000Z", "2026-08-18T00:00:29.000000Z"),
        ("2026-08-18T00:00:30.000000Z", "2026-08-18T00:00:39.000000Z"),
        ("2026-08-18T00:00:40.000000Z", "2026-08-18T00:00:49.000000Z"),
        ("2026-08-18T00:00:50.000000Z", "2026-08-18T00:00:59.000000Z"),
    ]
    for sequence, (kind, (started, ended)) in enumerate(zip(
        runtime["event_kind_sequences_by_repair_count"]["1"], lifecycle_times,
    ), start=1):
        artifact = (
            initial_artifact_sha256
            if kind in {"CREATE_INITIAL", "JUDGE_INITIAL"}
            else final_artifact_sha256
        )
        call_hashes = (
            [call_by_owner[kind]["source_envelope_sha256"]]
            if kind in call_by_owner else []
        )
        lifecycle_semantics.append({
            "sequence": sequence,
            "event_slot_id": f"{attempt_id}/{sequence:04d}/{kind}",
            "event_kind": kind,
            "started_at": started,
            "ended_at": ended,
            "source_keys": runtime["required_native_sources_by_event_kind"][kind],
            "call_envelope_sha256s": call_hashes,
            "failure_signal_code": None,
            "failure_call_envelope_sha256": None,
            "artifact_sha256": artifact,
            "artifact_null_reason": None,
            "not_observed_reason": None,
            "result": "PASS",
            "status": runtime["lifecycle_status_by_observed_result"]["PASS"],
        })
    native_results = {
        key: "PASS" for key in runtime["required_native_lifecycle_source_keys"]
    }
    precursor = derive_m00_native_lifecycle_precursor_manifest(
        attempt_id, lifecycle_semantics, runtime, native_results,
    )["manifest_sha256"]
    identity_projection = {
        identity_class: sha256_bytes(canonical_json_bytes([
            "FC01_M00_OPAQUE_IDENTITY_PROJECTION_V1",
            identity_class,
            opaque_alias,
        ]))
        for identity_class, opaque_alias in aliases.items()
    }
    native_fact_values = {
        "LANGGRAPH_DECK_DESIGN_LIFT_RUNTIME": {
            "ATTEMPT_COUNT": 1,
            "EVENT_SEQUENCE_SHA256": precursor,
            "REPAIR_COUNT": 1,
            "TERMINAL_STATE": "PASS",
        },
        "LANGGRAPH_DECK_QUALITY_PERSISTENCE": {
            "ATTEMPT_COUNT": 1,
            "MAX_ATTEMPTS": 1,
            "QUALITY_RUN_IDEMPOTENCY_BOUND": True,
            "STAGE_ORDER_SHA256": precursor,
            "TERMINAL_STATE": "PASS",
        },
        "LANGGRAPH_DECK_QUALITY_COMPARATOR": {
            "APPROVED_IMPROVEMENT": True,
            "FINAL_QUALITY_RUN_SHA256": identity_projection["FINAL_QUALITY_RUN"],
            "INITIAL_QUALITY_RUN_SHA256": identity_projection["INITIAL_QUALITY_RUN"],
            "PRESERVATION_PASS": True,
            "STRICT_SCORE_IMPROVEMENT_IF_REPAIRED": True,
        },
        "GATEWAY_ARTIFACT_REGISTRY": {
            "FINAL_ARTIFACT_SHA256": final_artifact_sha256,
            "INITIAL_ARTIFACT_SHA256": initial_artifact_sha256,
            "OWNERSHIP_BOUND": True,
            "PUBLICATION_COUNT": 2,
        },
        "GATEWAY_BUILDER_CANVAS_HISTORY": {
            "ORDERED_EVENT_STREAM_SHA256": precursor,
            "RUN_DRIFT_REJECTED": True,
            "TERMINAL_EVENT_COUNT": 1,
        },
        "AUTHENTICATED_VERCEL_BROWSER_REVIEW": {
            "AUTHENTICATED_REVIEW_PASS": True,
            "FINAL_ARTIFACT_DOWNLOAD_PASS": True,
            "FINAL_ARTIFACT_SHA256": final_artifact_sha256,
        },
    }
    native_exports: list[dict[str, Any]] = []
    for source_key in runtime["required_native_lifecycle_source_keys"]:
        fact_contract = transient["native_fact_contract_by_source_key"][source_key]
        facts = [
            _self_test_m00_fact_row(
                fact_id,
                value_type,
                native_fact_values[source_key][fact_id],
            )
            for fact_id, value_type in fact_contract.items()
        ]
        native_exports.append(source_export(
            "NATIVE_LIFECYCLE", source_key, facts,
            transient["native_identity_classes_by_source_key"][source_key],
        ))

    call_coverage_facts = [
        _self_test_m00_fact_row("OBSERVED_CALL_COUNT", "INTEGER", len(call_exports)),
        _self_test_m00_fact_row("UNCLASSIFIED_CALL_COUNT", "INTEGER", 0),
        _self_test_m00_fact_row("DROPPED_OBSERVATION_COUNT", "INTEGER", 0),
        _self_test_m00_fact_row(
            "STATUS", "CLOSED_TOKEN", call_coverage_contract["pass_required_values"]["status"],
        ),
    ]
    call_coverage_export = source_export(
        "CALL_SOURCE_COVERAGE", "CROSS_SYSTEM_TOOL_MODEL_CALL_COVERAGE",
        call_coverage_facts, transient["identity_classes_by_call_source_coverage"],
        observed_event_count=len(call_exports),
    )

    component_exports: list[dict[str, Any]] = []
    for category in component["component_category_values"]:
        required_specs = component["required_source_contract_by_category"][category]
        spec_by_source = {spec["source_system"]: spec for spec in required_specs}
        for slot in component["component_source_slots_by_category"][category]:
            if not slot["required"]:
                continue
            spec = spec_by_source[slot["source_system"]]
            fact_specs = component["required_fact_contract_by_category"][category]
            facts = []
            for fact_id in spec["owned_fact_ids"]:
                fact_spec = fact_specs[fact_id]
                if "expected_value" in fact_spec:
                    fact_value = fact_spec["expected_value"]
                elif fact_spec["expected_from"] == "parent.initial_artifact_sha256":
                    fact_value = initial_artifact_sha256
                else:
                    require(
                        fact_spec["expected_from"] == "parent.final_artifact_sha256",
                        f"M00 self-test unknown component fact source: {category}/{fact_id}",
                    )
                    fact_value = final_artifact_sha256
                facts.append(_self_test_m00_fact_row(
                    fact_id,
                    fact_spec["value_type"].replace("TOKEN", "CLOSED_TOKEN"),
                    fact_value,
                ))
            source_key = slot["source_system"]
            observer_mode = (
                "SEALED_LOCAL"
                if source_key == "SEALED_PPTX_PACKAGE_VALIDATOR"
                else "PROVIDER_AUTHENTICATED"
            )
            component_exports.append(source_export(
                "COMPONENT_SOURCE", source_key, facts,
                transient["identity_classes_by_component_source_slot_id"][slot["source_slot_id"]],
                slot=slot["source_slot_id"], observer_mode=observer_mode,
            ))

    effect_count_by_source = {
        source_class: 0 for source_class in effect_coverage_contract["required_source_classes"]
    }
    for effect in expected_effects["effect_rows"]:
        effect_count_by_source[
            effect_coverage_contract["effect_category_to_source_class"][effect["effect_class"]]
        ] += 1
    effect_coverage_exports: list[dict[str, Any]] = []
    for source_class in effect_coverage_contract["required_source_classes"]:
        count = effect_count_by_source[source_class]
        facts = [
            _self_test_m00_fact_row("SOURCE_CLASS", "CLOSED_TOKEN", source_class),
            _self_test_m00_fact_row("OBSERVED_EVENT_COUNT", "INTEGER", count),
            _self_test_m00_fact_row("UNCLASSIFIED_EVENT_COUNT", "INTEGER", 0),
            _self_test_m00_fact_row("DROPPED_OBSERVATION_COUNT", "INTEGER", 0),
            _self_test_m00_fact_row(
                "STATUS", "CLOSED_TOKEN", effect_coverage_contract["pass_source_status"],
            ),
        ]
        effect_coverage_exports.append(source_export(
            "EFFECT_SOURCE_COVERAGE", source_class, facts,
            transient["identity_classes_by_effect_source_domain"]["EFFECT_SOURCE_COVERAGE"],
            observed_event_count=count,
        ))

    effect_exports: list[dict[str, Any]] = []
    for index, effect in enumerate(expected_effects["effect_rows"], start=1):
        category = effect["effect_class"]
        facts = [
            _self_test_m00_fact_row("PHASE", "CLOSED_TOKEN", "FORWARD_M00_ATTEMPT"),
            _self_test_m00_fact_row("CATEGORY", "CLOSED_TOKEN", category),
            _self_test_m00_fact_row("TARGET_CLASS", "CLOSED_TOKEN", effect["target_class"]),
            _self_test_m00_fact_row("OPERATION", "CLOSED_TOKEN", effect["operation"]),
            _self_test_m00_fact_row("SYNTHETIC_SCOPE_ALIAS", "CLOSED_TOKEN", scope_alias),
            _self_test_m00_fact_row("COUNT", "INTEGER", 1),
            _self_test_m00_fact_row("CLASSIFICATION", "CLOSED_TOKEN", "AUTHORIZED"),
            _self_test_m00_fact_row(
                "STATUS", "CLOSED_TOKEN", "PASS_OBSERVED_EFFECT",
            ),
        ]
        effect_exports.append(source_export(
            "EFFECT_EVENT", category, facts,
            transient["identity_classes_by_effect_source_domain"]["EFFECT_EVENT"],
            started_at=f"2026-08-18T00:00:0{index}.000000Z",
            ended_at=f"2026-08-18T00:00:0{index + 1}.000000Z",
        ))

    exports = (
        native_exports + [call_coverage_export] + component_exports
        + call_exports + effect_coverage_exports + effect_exports
    )
    native_index = {
        export["source_key"]: index
        for index, export in enumerate(exports, start=1)
        if export["source_domain"] == "NATIVE_LIFECYCLE"
    }
    call_index = {
        owner: exports.index(call_export) + 1
        for owner, call_export in call_by_owner.items()
    }
    lifecycle_events: list[dict[str, Any]] = []
    for semantic in lifecycle_semantics:
        source_indices = [native_index[key] for key in semantic["source_keys"]]
        call_indices = (
            [call_index[semantic["event_kind"]]]
            if semantic["event_kind"] in call_index else []
        )
        event = {
            "sequence": semantic["sequence"],
            "event_slot_id": semantic["event_slot_id"],
            "event_kind": semantic["event_kind"],
            "started_at": semantic["started_at"],
            "ended_at": semantic["ended_at"],
            "source_keys": semantic["source_keys"],
            "source_export_indices": source_indices,
            "call_export_indices": call_indices,
            "source_envelope_sha256s": [
                exports[index - 1]["source_envelope_sha256"] for index in source_indices
            ],
            "call_envelope_sha256s": semantic["call_envelope_sha256s"],
            "failure_signal_code": None,
            "failure_source_envelope_sha256": None,
            "failure_call_envelope_sha256": None,
            "stable_event_projection_sha256": None,
            "artifact_sha256": semantic["artifact_sha256"],
            "artifact_null_reason": None,
            "not_observed_reason": None,
            "result": "PASS",
            "status": runtime["lifecycle_status_by_observed_result"]["PASS"],
        }
        stable_projection = [
            "FC01_M00_STABLE_LIFECYCLE_EVENT_V1",
            event["event_slot_id"], event["event_kind"], event["started_at"],
            event["ended_at"], event["source_envelope_sha256s"],
            event["call_envelope_sha256s"], event["failure_signal_code"],
            event["failure_source_envelope_sha256"],
            event["failure_call_envelope_sha256"], event["artifact_sha256"],
            event["artifact_null_reason"], event["not_observed_reason"],
            event["result"], event["status"],
        ]
        event["stable_event_projection_sha256"] = sha256_bytes(
            canonical_json_bytes(stable_projection)
        )
        lifecycle_events.append(event)

    aggregate = trust_context["aggregate"]
    capture_attestation = {
        "whole_capture_attester_sequence": aggregate["sequence"],
        "attester_id": aggregate["attester_id"],
        "attestation_key_id": aggregate["attestation_key_id"],
        "attestation_algorithm": trust_contract["attestation_algorithm"],
        "signed_at": signed_at,
        "signed_projection_sha256": None,
        "signature_base64url": None,
    }
    value = {
        "d2_consumption_ref": consumption_ref,
        "candidate_sha": candidate[0],
        "candidate_tree": candidate[1],
        "attempt_id": attempt_id,
        "synthetic_scope_alias": scope_alias,
        "capture_started_at": capture_started,
        "capture_ended_at": capture_ended,
        "source_exports": exports,
        "lifecycle_event_exports": lifecycle_events,
        "capture_attestation": capture_attestation,
    }
    signed_projection = [
        trust_contract["capture_signature_contract"]["message_domain"],
        capture_attestation["whole_capture_attester_sequence"],
        capture_attestation["attester_id"],
        capture_attestation["attestation_key_id"],
        capture_attestation["attestation_algorithm"],
        capture_attestation["signed_at"],
        value["d2_consumption_ref"], value["candidate_sha"], value["candidate_tree"],
        value["attempt_id"], value["synthetic_scope_alias"], value["capture_started_at"],
        value["capture_ended_at"], value["source_exports"], value["lifecycle_event_exports"],
    ]
    signed_bytes = canonical_json_bytes(signed_projection)
    capture_attestation["signed_projection_sha256"] = sha256_bytes(signed_bytes)
    capture_attestation["signature_base64url"] = _self_test_rsa_pss_sha256_sign(
        signed_bytes,
        hashlib.sha256(b"m00-signed-transient-repaired-pass-salt").digest(),
    )
    return {
        "value": value,
        "finalizer_contract": finalizer,
        "runtime_contract": runtime,
        "component_contract": component,
        "expected_implementation_ref": implementation_ref,
        "expected_d2_consumption_ref": consumption_ref,
        "expected_candidate": candidate,
        "expected_synthetic_scope_alias": scope_alias,
        "call_budget": call_budget,
        "spend_budget": spend_budget,
        "expected_effects": expected_effects,
        "trust_contract": trust_contract,
        "trust_context": trust_context,
        "consumed_at": consumed_at,
        "finalizer_started_at": finalizer_started_at,
        "held_initial_artifact_sha256": initial_artifact_sha256,
        "held_final_artifact_sha256": final_artifact_sha256,
        "held_final_artifact_facts": {
            "PPTX_CONTAINER_VALID": True,
            "NATIVE_ARTIFACT_VALID": True,
        },
        "precursor_sha256": precursor,
    }


def self_test_m00_signed_transient_pass(schema: dict[str, Any]) -> None:
    fixture = _self_test_build_signed_m00_transient_pass(schema)
    value = fixture.pop("value")
    expected_precursor = fixture.pop("precursor_sha256")
    normalized = validate_m00_transient_observation_bundle_value(
        value,
        schema= schema,
        **fixture,
    )
    require(
        normalized["result"] == "PASS"
        and normalized["repair_count"] == 1
        and normalized["native_lifecycle_precursor_manifest_sha256"]
        == expected_precursor,
        "M00 signed repaired-PASS transient fixture failed",
    )
    mutated = copy.deepcopy(value)
    mutated["lifecycle_event_exports"][0]["artifact_sha256"] = "9" * 64
    signed_projection = mutated["capture_attestation"]
    signed_bytes = canonical_json_bytes([
        schema["supporting_receipt_contracts"]["m00_authenticated_export_trust_registry"]
        ["capture_signature_contract"]["message_domain"],
        signed_projection["whole_capture_attester_sequence"],
        signed_projection["attester_id"],
        signed_projection["attestation_key_id"],
        signed_projection["attestation_algorithm"],
        signed_projection["signed_at"],
        mutated["d2_consumption_ref"], mutated["candidate_sha"],
        mutated["candidate_tree"], mutated["attempt_id"],
        mutated["synthetic_scope_alias"], mutated["capture_started_at"],
        mutated["capture_ended_at"], mutated["source_exports"],
        mutated["lifecycle_event_exports"],
    ])
    mutated["capture_attestation"]["signed_projection_sha256"] = sha256_bytes(signed_bytes)
    expect_failure(
        lambda: validate_m00_transient_observation_bundle_value(
            mutated,
            schema=schema,
            **fixture,
        ),
        "RSA-PSS signature invalid",
    )


def _self_test_build_signed_m00_transient_direct_fail(
    schema: dict[str, Any],
) -> dict[str, Any]:
    fixture = _self_test_build_signed_m00_transient_pass(schema)
    pass_value = fixture["value"]
    runtime = fixture["runtime_contract"]
    finalizer = fixture["finalizer_contract"]
    transient = finalizer["transient_observation_bundle_contract"]
    component = fixture["component_contract"]
    unavailable_reason = transient["source_export_unavailable_reason_by_result"][
        "UNAVAILABLE"
    ]
    identity_reason = runtime["identity_projection_status_by_availability"][
        "NOT_OBSERVED"
    ]

    attempted_categories = {
        category
        for category, prerequisite in component[
            "component_availability_prerequisite_by_category"
        ].items()
        if prerequisite["required_event_kinds"] in ([], ["CREATE_INITIAL"])
        and not prerequisite["requires_initial_artifact"]
        and not prerequisite["requires_final_artifact"]
    }
    # Empty-required-event categories without an artifact prerequisite do not
    # currently exist; keep this explicit so the fixture changes if one lands.
    require(
        attempted_categories
        == {
            "runtime_evidence",
            "persistence_evidence",
            "trace_correlation_evidence",
            "expected_application_persistence_effects",
        },
        "M00 direct-failure attempted component catalog drift",
    )

    def unavailable_export(row: dict[str, Any]) -> dict[str, Any]:
        result = copy.deepcopy(row)
        result.update({
            "observer_mode": "PROVIDER_AUTHENTICATED",
            "started_at": None,
            "ended_at": None,
            "observed_event_count": 0,
            "opaque_provider_receipt_id": None,
            "opaque_provider_receipt_sha256": None,
            "provider_receipt_projection_group_id": None,
            "provider_receipt_null_reason": None,
            "sealed_local_observer_ref": None,
            "failure_signal_code": "AUTHENTICATED_EXPORT_UNAVAILABLE",
            "unavailable_reason": unavailable_reason,
            "result": "UNAVAILABLE",
            "status": transient["source_export_result_status_contract"]["UNAVAILABLE"]
            ["PROVIDER_AUTHENTICATED"],
        })
        for alias in result["opaque_identity_aliases"]:
            alias.update({
                "opaque_alias": None,
                "projection_sha256": None,
                "availability": "NOT_OBSERVED",
                "unavailable_reason": identity_reason,
            })
        for fact in result["minimized_fact_rows"]:
            for value_field in (
                "boolean_value", "integer_value", "number_value", "token_value",
                "sha256_value",
            ):
                fact[value_field] = None
            fact["not_observed_reason"] = unavailable_reason
            fact["result"] = "NOT_OBSERVED"
        projection = [
            "FC01_M00_SIGNED_SOURCE_ENVELOPE_V1",
            result["source_domain"], result["source_key"],
            result["component_source_slot_id"], result["source_attester_sequence"],
            result["observer_mode"], result["started_at"], result["ended_at"],
            result["observed_event_count"], result["opaque_identity_aliases"],
            result["minimized_fact_rows"], result["opaque_provider_receipt_id"],
            result["opaque_provider_receipt_sha256"],
            result["provider_receipt_projection_group_id"],
            result["provider_receipt_null_reason"], result["sealed_local_observer_ref"],
            result["failure_signal_code"], result["unavailable_reason"],
            result["result"], result["status"], result["raw_content_present"],
        ]
        digest = sha256_bytes(canonical_json_bytes(projection))
        result["source_envelope_id"] = digest
        result["source_envelope_sha256"] = digest
        return result

    selected: list[dict[str, Any]] = []
    for row in pass_value["source_exports"]:
        domain = row["source_domain"]
        if domain == "CALL_SOURCE_COVERAGE":
            selected.append(unavailable_export(row))
        elif domain == "COMPONENT_SOURCE":
            category = row["component_source_slot_id"].split("/", 1)[0]
            slot = next(
                slot
                for slot in component["component_source_slots_by_category"][category]
                if slot["source_slot_id"] == row["component_source_slot_id"]
            )
            if category in attempted_categories and slot["required"]:
                selected.append(unavailable_export(row))
        elif domain == "EFFECT_SOURCE_COVERAGE":
            selected.append(unavailable_export(row))
    require(
        [row["source_domain"] for row in selected].count("CALL_SOURCE_COVERAGE") == 1
        and len([row for row in selected if row["source_domain"] == "COMPONENT_SOURCE"])
        == 11
        and len([row for row in selected if row["source_domain"] == "EFFECT_SOURCE_COVERAGE"])
        == 11,
        "M00 direct-failure unavailable source catalog drift",
    )

    attempt_id = pass_value["attempt_id"]
    event_kinds = runtime["event_kind_sequences_by_repair_count"]["0"]
    lifecycle_events: list[dict[str, Any]] = []
    for sequence, kind in enumerate(event_kinds, start=1):
        if sequence == 1:
            result = "FAIL"
            started_at = "2026-08-18T00:00:10.000000Z"
            ended_at = "2026-08-18T00:00:11.000000Z"
            not_observed_reason = None
            artifact_null_reason = "NOT_PRODUCED_DUE_TO_FAILED_STAGE"
            status = runtime["lifecycle_status_by_observed_result"]["FAIL"]
            failure_signal = "LIFECYCLE_AUTHORIZATION_FAILED"
        else:
            result = "NOT_OBSERVED"
            started_at = ended_at = None
            not_observed_reason = "NOT_OBSERVED_DUE_TO_PRIOR_BOUND_FAILURE"
            artifact_null_reason = not_observed_reason
            status = runtime["lifecycle_status_by_not_observed_reason"][
                not_observed_reason
            ]
            failure_signal = None
        event = {
            "sequence": sequence,
            "event_slot_id": f"{attempt_id}/{sequence:04d}/{kind}",
            "event_kind": kind,
            "started_at": started_at,
            "ended_at": ended_at,
            "source_keys": [],
            "source_export_indices": [],
            "call_export_indices": [],
            "source_envelope_sha256s": [],
            "call_envelope_sha256s": [],
            "failure_signal_code": failure_signal,
            "failure_source_envelope_sha256": None,
            "failure_call_envelope_sha256": None,
            "stable_event_projection_sha256": None,
            "artifact_sha256": None,
            "artifact_null_reason": artifact_null_reason,
            "not_observed_reason": not_observed_reason,
            "result": result,
            "status": status,
        }
        stable_projection = [
            "FC01_M00_STABLE_LIFECYCLE_EVENT_V1",
            event["event_slot_id"], event["event_kind"], event["started_at"],
            event["ended_at"], [], [], event["failure_signal_code"], None, None,
            None, event["artifact_null_reason"], event["not_observed_reason"],
            event["result"], event["status"],
        ]
        event["stable_event_projection_sha256"] = sha256_bytes(
            canonical_json_bytes(stable_projection)
        )
        lifecycle_events.append(event)
    precursor = derive_m00_native_lifecycle_precursor_manifest(
        attempt_id, lifecycle_events, runtime, {},
    )["manifest_sha256"]
    value = {
        **{
            key: copy.deepcopy(pass_value[key])
            for key in (
                "d2_consumption_ref", "candidate_sha", "candidate_tree", "attempt_id",
                "synthetic_scope_alias", "capture_started_at", "capture_ended_at",
            )
        },
        "source_exports": selected,
        "lifecycle_event_exports": lifecycle_events,
        "capture_attestation": copy.deepcopy(pass_value["capture_attestation"]),
    }
    attestation = value["capture_attestation"]
    signed_projection = [
        fixture["trust_contract"]["capture_signature_contract"]["message_domain"],
        attestation["whole_capture_attester_sequence"], attestation["attester_id"],
        attestation["attestation_key_id"], attestation["attestation_algorithm"],
        attestation["signed_at"], value["d2_consumption_ref"], value["candidate_sha"],
        value["candidate_tree"], value["attempt_id"], value["synthetic_scope_alias"],
        value["capture_started_at"], value["capture_ended_at"],
        value["source_exports"], value["lifecycle_event_exports"],
    ]
    signed_bytes = canonical_json_bytes(signed_projection)
    attestation["signed_projection_sha256"] = sha256_bytes(signed_bytes)
    attestation["signature_base64url"] = _self_test_rsa_pss_sha256_sign(
        signed_bytes,
        hashlib.sha256(b"m00-signed-transient-direct-fail-salt").digest(),
    )
    fixture.update({
        "value": value,
        "held_initial_artifact_sha256": None,
        "held_final_artifact_sha256": None,
        "held_final_artifact_facts": None,
        "precursor_sha256": precursor,
    })
    return fixture


def self_test_m00_signed_transient_direct_fail(schema: dict[str, Any]) -> None:
    fixture = _self_test_build_signed_m00_transient_direct_fail(schema)
    value = fixture.pop("value")
    expected_precursor = fixture.pop("precursor_sha256")
    normalized = validate_m00_transient_observation_bundle_value(
        value,
        schema=schema,
        **fixture,
    )
    require(
        normalized["result"] == "FAIL"
        and normalized["native_runtime_result"] == "FAIL"
        and normalized["repair_count"] == 0
        and normalized["native_lifecycle_precursor_manifest_sha256"]
        == expected_precursor,
        "M00 signed direct zero-child FAIL transient fixture failed",
    )


def _self_test_m00_committed_aggregate_rows(
    source_registry_rows: list[dict[str, Any]],
    lifecycle_event_rows: list[dict[str, Any]],
    normalized: dict[str, Any],
    fixture: dict[str, Any],
) -> list[dict[str, Any]]:
    """Derive the complete test-only aggregate projection from retained facts."""

    runtime = fixture["runtime_contract"]
    observed_at = fixture["value"]["capture_ended_at"]
    findings: list[dict[str, Any]] = []
    for row in source_registry_rows:
        finding_id: Optional[str] = None
        if row["result"] == "FAIL":
            finding_id = runtime[
                "authenticated_source_failure_signal_to_finding_id"
            ][row["failure_signal_code"]]
        elif row["result"] == "PARTIAL":
            finding_id = runtime["nonpass_source_result_to_finding_id"]["PARTIAL"]
        elif row["result"] == "UNAVAILABLE":
            selector = {
                "CALL_SOURCE_COVERAGE": "UNAVAILABLE_CALL_SOURCE_COVERAGE",
                "EFFECT_SOURCE_COVERAGE": "UNAVAILABLE_EFFECT_SOURCE_COVERAGE",
            }.get(row["source_domain"], "UNAVAILABLE_DEFAULT")
            finding_id = runtime["nonpass_source_result_to_finding_id"][selector]
        if finding_id is not None:
            findings.append(m00_runtime_aggregate_finding(
                finding_id,
                [
                    "SOURCE_REGISTRY_RESULT_V1",
                    row["sequence"],
                    row["source_domain"],
                    row["source_key"],
                    row["component_source_slot_id"],
                    row["source_envelope_sha256"],
                    row["failure_signal_code"],
                    row["result"],
                ],
                [row["sequence"]],
                row["coverage_ended_at"] or observed_at,
                runtime,
            ))
    for event in lifecycle_event_rows:
        if (
            event["result"] == "FAIL"
            and event["failure_source_envelope_sha256"] is None
            and event["failure_call_envelope_sha256"] is None
        ):
            findings.append(m00_runtime_aggregate_finding(
                runtime["direct_lifecycle_failure_signal_to_finding_id"][
                    event["failure_signal_code"]
                ],
                [
                    "DIRECT_LIFECYCLE_RESULT_V1",
                    event["sequence"],
                    event["event_slot_id"],
                    event["event_kind"],
                    event["failure_signal_code"],
                    event["result"],
                ],
                [],
                event["ended_at"] or observed_at,
                runtime,
            ))
    if normalized["call_minimum_missing"]:
        findings.append(m00_runtime_aggregate_finding(
            "CALL_MINIMUM_MISSING",
            [
                "CALL_MINIMUM_RECONCILIATION_V1",
                normalized["call_counts_by_category"],
                fixture["call_budget"]["call_categories"],
            ],
            [],
            observed_at,
            runtime,
        ))
    if normalized["call_maximum_exceeded"]:
        findings.append(m00_runtime_aggregate_finding(
            "CALL_MAXIMUM_EXCEEDED",
            [
                "CALL_MAXIMUM_RECONCILIATION_V1",
                normalized["call_counts_by_category"],
                fixture["call_budget"]["call_categories"],
            ],
            [],
            observed_at,
            runtime,
        ))
    if normalized["spend_ceiling_exceeded"]:
        findings.append(m00_runtime_aggregate_finding(
            "SPEND_CEILING_EXCEEDED",
            [
                "SPEND_RECONCILIATION_V1",
                normalized["actual_spend_usd"],
                fixture["spend_budget"]["maximum_spend"],
            ],
            [],
            observed_at,
            runtime,
        ))
    if normalized["effect_minimum_missing"]:
        findings.append(m00_runtime_aggregate_finding(
            "EFFECT_MINIMUM_MISSING",
            [
                "EFFECT_MINIMUM_RECONCILIATION_V1",
                normalized["effect_counts_by_category"],
                fixture["expected_effects"]["effect_rows"],
            ],
            [],
            observed_at,
            runtime,
        ))
    if normalized["effect_maximum_exceeded"]:
        findings.append(m00_runtime_aggregate_finding(
            "EFFECT_MAXIMUM_EXCEEDED",
            [
                "EFFECT_MAXIMUM_RECONCILIATION_V1",
                normalized["effect_counts_by_category"],
                fixture["expected_effects"]["effect_rows"],
            ],
            [],
            observed_at,
            runtime,
        ))
    return finalize_m00_runtime_aggregate_findings(findings, runtime)


def _self_test_project_m00_committed_runtime_bundle(
    schema: dict[str, Any],
    fixture: dict[str, Any],
    normalized: dict[str, Any],
) -> dict[str, Any]:
    """Project a genuinely signed transient fixture into the frozen bundle shape."""

    value = fixture["value"]
    runtime = fixture["runtime_contract"]
    component = fixture["component_contract"]
    finalizer = fixture["finalizer_contract"]
    exports = value["source_exports"]

    source_registry_rows: list[dict[str, Any]] = []
    for sequence, export in enumerate(exports, start=1):
        row = {
            "sequence": sequence,
            "source_domain": export["source_domain"],
            "source_key": export["source_key"],
            "component_source_slot_id": export["component_source_slot_id"],
            "source_attester_sequence": export["source_attester_sequence"],
            "source_envelope_id": export["source_envelope_id"],
            "source_envelope_sha256": export["source_envelope_sha256"],
            "observer_mode": export["observer_mode"],
            "coverage_started_at": export["started_at"],
            "coverage_ended_at": export["ended_at"],
            "observed_event_count": export["observed_event_count"],
            "opaque_provider_receipt_id": export["opaque_provider_receipt_id"],
            "opaque_provider_receipt_sha256": export[
                "opaque_provider_receipt_sha256"
            ],
            "provider_receipt_projection_group_id": export[
                "provider_receipt_projection_group_id"
            ],
            "failure_signal_code": export["failure_signal_code"],
            "result": export["result"],
            "provider_receipt_null_reason": export[
                "provider_receipt_null_reason"
            ],
            "sealed_local_observer_ref": export["sealed_local_observer_ref"],
            "native_identity_aliases": copy.deepcopy(
                export["opaque_identity_aliases"]
            ),
            "native_fact_rows": (
                copy.deepcopy(export["minimized_fact_rows"])
                if export["source_domain"] == "NATIVE_LIFECYCLE"
                else []
            ),
            "minimized_projection_sha256": None,
            "unavailable_reason": export["unavailable_reason"],
            "raw_payload_or_user_private_or_secret_content_stored": export[
                "raw_content_present"
            ],
            "status": export["status"],
        }
        row["minimized_projection_sha256"] = m00_minimized_source_projection_sha256(
            row
        )
        exact_keys(
            row,
            runtime["source_registry_row_exact_fields"],
            f"M00 committed self-test registry row {sequence}",
        )
        source_registry_rows.append(row)

    lifecycle_event_rows: list[dict[str, Any]] = []
    for event in value["lifecycle_event_exports"]:
        row = {
            "sequence": event["sequence"],
            "event_slot_id": event["event_slot_id"],
            "event_kind": event["event_kind"],
            "started_at": event["started_at"],
            "ended_at": event["ended_at"],
            "source_envelope_sha256s": copy.deepcopy(
                event["source_envelope_sha256s"]
            ),
            "call_envelope_sha256s": copy.deepcopy(
                event["call_envelope_sha256s"]
            ),
            "failure_signal_code": event["failure_signal_code"],
            "failure_source_envelope_sha256": event[
                "failure_source_envelope_sha256"
            ],
            "failure_call_envelope_sha256": event[
                "failure_call_envelope_sha256"
            ],
            "stable_event_projection_sha256": event[
                "stable_event_projection_sha256"
            ],
            "source_registry_sequences": copy.deepcopy(
                event["source_export_indices"]
            ),
            "call_registry_sequences": copy.deepcopy(event["call_export_indices"]),
            "artifact_sha256": event["artifact_sha256"],
            "artifact_null_reason": event["artifact_null_reason"],
            "not_observed_reason": event["not_observed_reason"],
            "result": event["result"],
            "status": event["status"],
        }
        exact_keys(
            row,
            runtime["lifecycle_event_row_exact_fields"],
            f"M00 committed self-test lifecycle row {event['sequence']}",
        )
        lifecycle_event_rows.append(row)

    event_by_kind = {row["event_kind"]: row for row in lifecycle_event_rows}
    actual_slot_ids = {
        row["component_source_slot_id"]
        for row in source_registry_rows
        if row["source_domain"] == "COMPONENT_SOURCE"
    }
    component_attempt_state_rows: list[dict[str, Any]] = []
    for sequence, category in enumerate(
        finalizer["required_component_categories"], start=1,
    ):
        prerequisite = component[
            "component_availability_prerequisite_by_category"
        ][category]
        prerequisite_sequences = [
            event_by_kind[event_kind]["sequence"]
            for event_kind in prerequisite["required_event_kinds"]
        ]
        satisfied_sequences = [
            event_by_kind[event_kind]["sequence"]
            for event_kind in prerequisite["required_event_kinds"]
            if event_by_kind[event_kind]["result"] != "NOT_OBSERVED"
        ]
        attempted = (
            satisfied_sequences == prerequisite_sequences
            and (
                not prerequisite["requires_initial_artifact"]
                or normalized["initial_artifact_sha256"] is not None
            )
            and (
                not prerequisite["requires_final_artifact"]
                or normalized["final_artifact_sha256"] is not None
            )
        )
        if attempted:
            availability = "ATTEMPTED"
            attempted_slots = [
                slot["source_slot_id"]
                for slot in component["component_source_slots_by_category"][category]
                if slot["required"] or slot["source_slot_id"] in actual_slot_ids
            ]
            not_produced_reason = None
        else:
            availability = "NOT_PRODUCED"
            attempted_slots = []
            not_produced_reason = "NOT_PRODUCED_DUE_TO_UNREACHED_PREREQUISITE"
        row = {
            "sequence": sequence,
            "component_category": category,
            "availability": availability,
            "prerequisite_event_sequences": prerequisite_sequences,
            "satisfied_prerequisite_event_sequences": satisfied_sequences,
            "attempted_component_source_slot_ids": attempted_slots,
            "not_produced_reason": not_produced_reason,
            "status": runtime["component_attempt_state_status_by_value"][
                availability
            ],
        }
        exact_keys(
            row,
            runtime["component_attempt_state_row_exact_fields"],
            f"M00 committed self-test component state {sequence}",
        )
        component_attempt_state_rows.append(row)
    expected_component_slots = [
        slot_id
        for row in component_attempt_state_rows
        for slot_id in row["attempted_component_source_slot_ids"]
    ]
    require(
        [
            row["component_source_slot_id"]
            for row in source_registry_rows
            if row["source_domain"] == "COMPONENT_SOURCE"
        ]
        == expected_component_slots,
        "M00 committed self-test component state/registry projection drift",
    )

    attestation = copy.deepcopy(value["capture_attestation"])
    signature = decode_canonical_base64url_nopad(
        attestation["signature_base64url"],
        "M00 committed self-test capture signature",
    )
    attestation["signature_sha256"] = sha256_bytes(signature)
    reached_events = [
        row for row in lifecycle_event_rows if row["result"] != "NOT_OBSERVED"
    ]
    effect_counts = normalized["effect_counts_by_category"]
    unexpected_effect_categories = {
        "synthetic_trace_store_effect",
        "production_user_data_read_or_write",
        "private_object_read",
        "operator_database_mutation",
        "voice",
        "unlisted_provider_or_network_action",
        "unlisted_filesystem_or_artifact_effect",
        "raw_sensitive_content_recorded",
    }
    aggregate_rows = _self_test_m00_committed_aggregate_rows(
        source_registry_rows, lifecycle_event_rows, normalized, fixture,
    )
    failure_stage = aggregate_rows[0]["failure_stage"] if aggregate_rows else None
    failing_invariant_ids = sorted({
        row["failing_invariant_id"] for row in aggregate_rows
    })
    reference_root = f"{EVIDENCE_REL.as_posix()}/m00-selftest"
    bundle = {
        "schema_version": 1,
        "record_type": runtime["record_type"],
        "campaign_id": CAMPAIGN_ID,
        "amendment_id": AMENDMENT_ID,
        "created_at": "2026-08-18T00:01:02.000000Z",
        "coverage_started_at": value["capture_started_at"],
        "coverage_ended_at": value["capture_ended_at"],
        "attempt_started_at": reached_events[0]["started_at"],
        "attempt_ended_at": reached_events[-1]["ended_at"],
        "d2_packet": {"path": f"{reference_root}/d2-packet.json", "sha256": "3" * 64},
        "d2_approval": {"path": f"{reference_root}/d2-approval.json", "sha256": "4" * 64},
        "d2_consumption": copy.deepcopy(value["d2_consumption_ref"]),
        "d2_frozen_inputs": {"path": f"{reference_root}/d2-frozen-inputs.json", "sha256": "5" * 64},
        "authenticated_export_trust_registry": {
            "path": f"{reference_root}/authenticated-export-trust-registry.json",
            "sha256": "6" * 64,
        },
        "deployed_identity_overlay": {
            "path": f"{reference_root}/deployed-identity-overlay.json",
            "sha256": "7" * 64,
        },
        "candidate_sha": value["candidate_sha"],
        "candidate_tree": value["candidate_tree"],
        "synthetic_scope_alias": value["synthetic_scope_alias"],
        "attempt_id": value["attempt_id"],
        "correlation_alias": sha256_bytes(canonical_json_bytes([
            "FC01_M00_CORRELATION_V1",
            value["attempt_id"],
            value["synthetic_scope_alias"],
        ])),
        "prepare_authority": runtime["required_values"]["prepare_authority"],
        "execution_owner": runtime["required_values"]["execution_owner"],
        "finalization_mode": runtime["required_values"]["finalization_mode"],
        "capture_attestation": attestation,
        "source_registry_rows": source_registry_rows,
        "source_registry_sha256": m00_source_registry_sha256(
            value["attempt_id"], source_registry_rows,
        ),
        "identity_projection_rows": copy.deepcopy(
            normalized["identity_projection_rows"]
        ),
        "lifecycle_event_rows": lifecycle_event_rows,
        "component_attempt_state_rows": component_attempt_state_rows,
        "aggregate_failure_rows": aggregate_rows,
        "unbound_forward_call_registry_sequences": [],
        "native_runtime_result": normalized["native_runtime_result"],
        "native_runtime_status": normalized["native_runtime_status"],
        "repair_count": normalized["repair_count"],
        "actual_call_counts_by_category": copy.deepcopy(
            normalized["call_counts_by_category"]
        ),
        "actual_total_calls": normalized["actual_total_calls"],
        "actual_spend_usd": normalized["actual_spend_usd"],
        "observed_effect_event_count": sum(effect_counts.values()),
        "unexpected_effect_count": sum(
            effect_counts[category] for category in unexpected_effect_categories
        ),
        "operator_database_mutations": effect_counts[
            "operator_database_mutation"
        ],
        "private_reads": effect_counts["private_object_read"],
        "voice_calls": effect_counts["voice"],
        "raw_content_recorded": effect_counts["raw_sensitive_content_recorded"] > 0,
        "matching_attempt_count": runtime["required_values"]["matching_attempt_count"],
        "prior_matching_attempt_count": runtime["required_values"][
            "prior_matching_attempt_count"
        ],
        "retry_count": runtime["required_values"]["retry_count"],
        "unclassified_source_record_count": 0,
        "dropped_source_record_count": 0,
        "failure_stage": failure_stage,
        "failing_invariant_ids": failing_invariant_ids,
        "raw_prompt_response_payload_user_private_or_secret_content_stored": runtime[
            "required_values"
        ]["raw_prompt_response_payload_user_private_or_secret_content_stored"],
        "result": normalized["result"],
        "status": runtime["result_status_contract"][normalized["result"]],
    }
    exact_keys(bundle, runtime["exact_fields"], "M00 committed self-test bundle")
    return bundle


def _self_test_build_m00_committed_runtime_fixture(
    schema: dict[str, Any], *, direct_fail: bool,
) -> dict[str, Any]:
    fixture = (
        _self_test_build_signed_m00_transient_direct_fail(schema)
        if direct_fail
        else _self_test_build_signed_m00_transient_pass(schema)
    )
    transient_arguments = {
        key: value
        for key, value in fixture.items()
        if key not in {"value", "precursor_sha256"}
    }
    normalized = validate_m00_transient_observation_bundle_value(
        fixture["value"], schema=schema, **transient_arguments,
    )
    bundle = _self_test_project_m00_committed_runtime_bundle(
        schema, fixture, normalized,
    )
    return {
        "bundle": bundle,
        "runtime_contract": fixture["runtime_contract"],
        "trust_contract": fixture["trust_contract"],
        "trust_context": fixture["trust_context"],
        "call_budget": fixture["call_budget"],
        "spend_budget": fixture["spend_budget"],
        "expected_effects": fixture["expected_effects"],
        "expected_implementation_ref": fixture["expected_implementation_ref"],
        "window_ends_at": "2026-08-18T02:00:00Z",
    }


def self_test_m00_committed_runtime_pass_projection(schema: dict[str, Any]) -> None:
    fixture = _self_test_build_m00_committed_runtime_fixture(
        schema, direct_fail=False,
    )
    context = validate_m00_runtime_bundle_projection(
        fixture.pop("bundle"), schema=schema, **fixture,
    )
    require(
        context["result"] == "PASS",
        "M00 committed repaired-PASS runtime projection failed",
    )


def self_test_m00_committed_runtime_direct_fail_projection(
    schema: dict[str, Any],
) -> None:
    fixture = _self_test_build_m00_committed_runtime_fixture(
        schema, direct_fail=True,
    )
    bundle = fixture.pop("bundle")
    require(
        any(
            row["finding_id"] == "DIRECT_LIFECYCLE_AUTHORIZATION_FAILURE"
            for row in bundle["aggregate_failure_rows"]
        )
        and all(
            row["source_registry_sequences"] == []
            for row in bundle["aggregate_failure_rows"]
            if row["finding_id"] == "DIRECT_LIFECYCLE_AUTHORIZATION_FAILURE"
        ),
        "M00 committed direct zero-child FAIL omits direct provenance",
    )
    context = validate_m00_runtime_bundle_projection(
        bundle, schema=schema, **fixture,
    )
    require(
        context["result"] == "FAIL",
        "M00 committed direct zero-child FAIL runtime projection failed",
    )


def validate_m00_finalizer_cli_inputs(args: argparse.Namespace) -> None:
    control = Path(os.path.abspath(args.control_repo))
    require(control.resolve(strict=True) == control and control.is_dir(), "M00 finalizer control repository path invalid")
    require(git_text(control, "cat-file", "-t", args.evidence_head) == "commit", "M00 finalizer evidence HEAD is not a commit")
    require(git_text(control, "rev-parse", "HEAD") == args.evidence_head, "M00 finalizer control checkout is not exact evidence HEAD")
    package = control / PACKAGE_REL
    execution = validate_execution_contract(package)
    schema = validate_approval_schema_parity(package, execution)
    implementation_at_head = committed_blob(control, args.evidence_head, PACKAGE_REL / "evaluator.py")
    require(
        sha256_bytes(implementation_at_head) == sha256_file(Path(__file__).resolve()),
        "M00 finalizer invoking evaluator is not the exact evidence-HEAD evaluator",
    )
    consumption_relative = Path(args.d2_consumption_ref)
    require(
        not consumption_relative.is_absolute()
        and ".." not in consumption_relative.parts
        and args.d2_consumption_ref.startswith(EVIDENCE_REL.as_posix() + "/"),
        "M00 finalizer D2 consumption reference is outside governed evidence",
    )
    consumption_data = committed_blob(control, args.evidence_head, consumption_relative)
    consumption = json.loads(
        consumption_data.decode("utf-8"),
        object_pairs_hook=duplicate_guard,
        parse_constant=reject_json_constant,
    )
    exact_keys(consumption, CONSUMPTION_FIELDS, "M00 finalizer D2 consumption")
    require(consumption["gate_id"] == "FC01-D2", "M00 finalizer consumption is not D2")
    consumption_ref = {
        "path": consumption_relative.as_posix(),
        "sha256": sha256_bytes(consumption_data),
    }
    observation_path = canonical_regular_cli_input(args.observation_bundle, "M00 observation bundle")
    observation_data = observation_path.read_bytes()
    observation = json.loads(
        observation_data.decode("utf-8"),
        object_pairs_hook=duplicate_guard,
        parse_constant=reject_json_constant,
    )
    require(isinstance(observation, dict), "M00 transient observation bundle is not an object")
    finalizer_contract = schema["supporting_receipt_contracts"]["m00_runtime_finalization_receipt"]
    validate_m00_transient_observation_bundle_value(
        observation,
        finalizer_contract,
        schema["supporting_receipt_contracts"]["m00_runtime_observation_bundle"],
        schema["supporting_receipt_contracts"]["m00_component_evidence"],
    )
    require(observation["d2_consumption_ref"] == consumption_ref, "M00 transient consumption reference drift")
    candidate_repo = Path.cwd().resolve()
    validate_git_identity(
        candidate_repo,
        observation["candidate_sha"],
        observation["candidate_tree"],
        "M00 transient candidate",
    )
    sentinel = finalizer_contract["cli_contract"]["artifact_absence_sentinel"]
    artifact_paths: list[Path] = []
    for raw, label in (
        (args.initial_artifact, "M00 transient initial artifact"),
        (args.final_artifact, "M00 transient final artifact"),
    ):
        if raw == sentinel:
            continue
        artifact_paths.append(canonical_regular_cli_input(raw, label))
    require(
        len(artifact_paths) == len({(path.stat().st_dev, path.stat().st_ino) for path in artifact_paths}),
        "M00 transient artifacts alias one another",
    )
    transient_root: Optional[Path] = None
    if artifact_paths:
        parent_set = {path.parent for path in artifact_paths}
        require(len(parent_set) == 1, "M00 transient artifacts are not in one dedicated root")
        transient_root = next(iter(parent_set))
        require(
            all(path.parent == transient_root for path in artifact_paths),
            "M00 transient artifact is nested below the dedicated root",
        )
    output = Path(os.path.abspath(args.output_dir))
    require(".." not in Path(args.output_dir).parts and not output.exists(), "M00 output directory is not a fresh absent path")
    output_parent = output.parent.resolve(strict=True)
    require(output_parent == output.parent, "M00 output parent traverses a symlink")
    protected = [control, candidate_repo, Path(__file__).resolve(), observation_path]
    if transient_root is not None:
        protected.append(transient_root)
    require(
        all(not paths_overlap(output, path) for path in protected)
        and (transient_root is None or all(not paths_overlap(transient_root, path) for path in (control, candidate_repo, output))),
        "M00 output/transient/control/candidate/implementation paths overlap",
    )
    fail(
        "M00 transient input is valid, but deterministic emission is blocked because the current schema does not carry exact per-event lifecycle exports",
        state="BLOCKED_EVIDENCE",
    )


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--setup-receipt")
    parser.add_argument("--control-repo")
    parser.add_argument("--candidate-repo")
    parser.add_argument("--evidence-head")
    parser.add_argument("--d2-consumption-ref")
    parser.add_argument("--observation-bundle")
    parser.add_argument("--initial-artifact")
    parser.add_argument("--final-artifact")
    parser.add_argument("--output-dir")
    group = parser.add_mutually_exclusive_group()
    group.add_argument("--self-test", action="store_true")
    group.add_argument("--print-contracts", action="store_true")
    group.add_argument("--print-projections", action="store_true")
    group.add_argument("--validate-approval", nargs="+", metavar="PATH")
    group.add_argument("--validate-clock-ledger", metavar="PATH")
    group.add_argument("--validate-ci-lane", nargs=3, metavar=("GATE", "LANE", "INPUT"))
    group.add_argument("--finalize-m00-runtime", action="store_true")
    return parser.parse_args(argv)


def main(argv: Optional[list[str]] = None) -> int:
    args = parse_args(argv or sys.argv[1:])
    ci_common = (args.setup_receipt, args.control_repo, args.candidate_repo)
    ci_common_count = sum(value is not None for value in ci_common)
    m00_finalizer_values = (
        args.control_repo,
        args.evidence_head,
        args.d2_consumption_ref,
        args.observation_bundle,
        args.initial_artifact,
        args.final_artifact,
        args.output_dir,
    )
    if args.finalize_m00_runtime:
        require(
            all(value is not None for value in m00_finalizer_values),
            "--finalize-m00-runtime requires all seven canonical arguments",
        )
        require(
            args.setup_receipt is None and args.candidate_repo is None,
            "M00 finalizer does not accept CI setup/candidate arguments",
        )
        validate_m00_finalizer_cli_inputs(args)
        fail("M00 finalizer returned without emitting its deterministic closure")
    require(
        all(value is None for value in m00_finalizer_values[1:]),
        "M00 finalizer-only arguments require --finalize-m00-runtime",
    )
    require(ci_common_count in {0, 3}, "CI commands require all of --setup-receipt, --control-repo, and --candidate-repo")
    require(
        ci_common_count == 0 or args.self_test or args.validate_ci_lane is not None,
        "CI repository/setup arguments are only valid with --self-test or --validate-ci-lane",
    )
    if args.self_test:
        if ci_common_count == 0:
            run_self_test()
            return 0
        control_repo = resolve_ci_repository(args.control_repo, "/tmp/fc01-control", "CI control repository")
        candidate_repo = resolve_ci_repository(args.candidate_repo, ".", "CI candidate repository")
        require(
            args.setup_receipt in {
                "/tmp/fc01-ci/setup-d1-governance-evaluators.json",
                "/tmp/fc01-ci/setup-d3-governance-evaluators.json",
            },
            "CI self-test setup path is not a canonical governance-evaluators path",
        )
        setup_path, setup = load_ci_runtime_receipt(
            args.setup_receipt,
            args.setup_receipt,
            "CI self-test setup receipt",
        )
        gate_id = setup.get("gate_id")
        require(gate_id in {"FC01-D1", "FC01-D3"} and setup.get("lane_id") == "governance-evaluators", "CI self-test setup gate/lane drift")
        expected_setup_path = f"/tmp/fc01-ci/setup-{gate_id.lower().replace('fc01-', '')}-governance-evaluators.json"
        require(args.setup_receipt == expected_setup_path, "CI self-test setup path/gate drift")
        packet: dict[str, Any] = {
            "gate_id": gate_id,
            "candidate_sha": setup.get("candidate_sha"),
            "candidate_tree": setup.get("candidate_tree"),
            "bindings": {},
        }
        validate_ci_repository_pair(
            candidate_repo,
            control_repo,
            packet["candidate_sha"],
            packet["candidate_tree"],
            setup.get("evidence_control_head"),
        )
        execution_contract = validate_execution_contract(control_repo / PACKAGE_REL)
        schema = validate_approval_schema_parity(control_repo / PACKAGE_REL, execution_contract)
        validate_ci_evaluator_setup_value(
            control_repo,
            candidate_repo,
            setup,
            setup["evidence_control_head"],
            packet,
            schema,
            lane_id="governance-evaluators",
            label="CI governance evaluator setup",
            runtime_path=setup_path,
            expected_input_ref=None,
        )
        run_self_test(control_repo)
        return 0
    if args.print_contracts:
        print(json.dumps(contracts_export(), sort_keys=True, indent=2))
        return 0
    if args.print_projections:
        repo = repo_root()
        paths = activation_paths(repo)
        seals = seal_paths(repo)
        require(len(paths) == 1 and len(seals) == 1, "one committed seal and activation required")
        activation_rel = paths[0].relative_to(repo).as_posix()
        activation_sha = sha256_file(paths[0])
        seal = load_json(seals[0])
        rendered = {
            "state.md": render_state_projection(activation_rel, activation_sha, seal).decode(),
            "decisions.md.append": render_decision_append(activation_rel, activation_sha).decode(),
            "experiments.jsonl.append": canonical_jsonl_bytes(projection_experiment(activation_rel, activation_sha)).decode(),
        }
        print(json.dumps(rendered, sort_keys=True, indent=2))
        return 0
    if args.validate_approval is not None:
        require(len(args.validate_approval) in {2, 3}, "--validate-approval requires PACKET RECEIPT [CONSUMPTION]")
        paths = [Path(item) for item in args.validate_approval]
        consumed = validate_approval_files(paths[0], paths[1], paths[2] if len(paths) == 3 else None)
        if consumed:
            packet = load_json(paths[0])
            print("PASS_FC01_APPROVAL_CONSUMED_ONE_USE")
            for key in FALSE_AUTHORITY:
                print(f"{key}={str(GATE_AUTHORITY_AFTER_DECISION[packet['gate_id']][key]).lower()}")
        else:
            print("PASS_APPROVAL_PENDING_CONSUMPTION")
            for key in FALSE_AUTHORITY:
                print(f"{key}=false")
        return 0
    if args.validate_clock_ledger is not None:
        repo = repo_root()
        seal_path, seal = find_single_seal(repo)
        ledger = load_json(Path(args.validate_clock_ledger).resolve())
        require(ledger.get("record_type") == "FC01_V13_ACTIVE_CLOCK_LEDGER_V1", "legacy active-clock ledger schema is not accepted")
        require(
            ledger.get("seal_receipt")
            == {
                "path": seal_path.relative_to(repo).as_posix(),
                "sha256": sha256_file(seal_path),
            },
            "clock ledger seal binding mismatch",
        )
        active, remaining = validate_clock_ledger_value(
            ledger,
            seal,
            dt.datetime.now(UTC),
            repo=repo,
        )
        print("PASS_FC01_V13_TWO_CLOCKS")
        print(f"active_engineering_seconds={active}")
        print(f"remaining_active_engineering_seconds={remaining}")
        return 0
    if args.validate_ci_lane is not None:
        require(ci_common_count == 3, "--validate-ci-lane requires the canonical setup and repository arguments")
        gate_id, lane_id, input_name = args.validate_ci_lane
        require(gate_id in {"FC01-D1", "FC01-D3"}, "CI lane gate must be FC01-D1 or FC01-D3")
        input_path, receipt = load_ci_runtime_receipt(
            input_name,
            f"/tmp/fc01-ci/{lane_id}.json",
            "CI lane input",
        )
        require(receipt.get("gate_id") == gate_id and receipt.get("lane_id") == lane_id, "CI lane command/input identity drift")
        setup_path, setup = load_ci_runtime_receipt(
            args.setup_receipt,
            f"/tmp/fc01-ci/setup-{gate_id.lower().replace('fc01-', '')}-{lane_id}.json",
            "CI lane setup receipt",
        )
        control_repo = resolve_ci_repository(args.control_repo, "/tmp/fc01-control", "CI control repository")
        candidate_repo = resolve_ci_repository(args.candidate_repo, ".", "CI candidate repository")
        governed_path, input_commit = find_committed_exact_evidence_copy(
            control_repo, input_path.read_bytes(), "CI lane input",
        )
        input_ref = {
            "path": governed_path.relative_to(control_repo).as_posix(),
            "sha256": sha256_bytes(input_path.read_bytes()),
        }
        execution_contract = validate_execution_contract(control_repo / PACKAGE_REL)
        schema = validate_approval_schema_parity(control_repo / PACKAGE_REL, execution_contract)
        packet: dict[str, Any] = {
            "gate_id": gate_id,
            "candidate_sha": receipt.get("candidate_sha"),
            "candidate_tree": receipt.get("candidate_tree"),
            "bindings": {},
        }
        require(
            setup.get("gate_id") == gate_id
            and setup.get("lane_id") == lane_id
            and (setup.get("candidate_sha"), setup.get("candidate_tree"))
            == (packet["candidate_sha"], packet["candidate_tree"]),
            "CI lane setup/input identity drift",
        )
        validate_ci_repository_pair(
            candidate_repo,
            control_repo,
            packet["candidate_sha"],
            packet["candidate_tree"],
            setup.get("evidence_control_head"),
        )
        if gate_id == "FC01-D1":
            packet["bindings"]["allowlisted_diff"] = candidate_name_status(candidate_repo, FROZEN_PRODUCT, packet["candidate_sha"])
        validate_ci_evaluator_setup_value(
            control_repo,
            candidate_repo,
            setup,
            setup["evidence_control_head"],
            packet,
            schema,
            lane_id=lane_id,
            label=f"CI evaluator setup/{gate_id}/{lane_id}",
            runtime_path=setup_path,
            expected_input_ref=input_ref,
        )
        require(
            setup["workflow_job_id"] == receipt["workflow_job_id"]
            and setup["check_name"] == receipt["check_name"]
            and setup["command"] == receipt["command"]
            and setup["command_sha256"] == receipt["command_sha256"],
            "CI lane setup/input execution identity drift",
        )
        validate_ci_lane_input_receipt(
            control_repo,
            input_ref,
            packet,
            schema,
            lane_id=lane_id,
            at_commit=input_commit,
            label=f"CI lane input/{gate_id}/{lane_id}",
            preloaded=(receipt, input_commit),
            candidate_repo=candidate_repo,
        )
        print("PASS_FC01_V13_CI_LANE_INPUT")
        print(f"gate_id={gate_id}")
        print(f"lane_id={lane_id}")
        print(f"candidate_sha={packet['candidate_sha']}")
        for key in FALSE_AUTHORITY:
            print(f"{key}=false")
        return 0
    state, authority, version = validate_activation_sequence()
    output_state(state, authority, version=version)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except GovernanceError as exc:
        print(f"{exc.state}: {exc}", file=sys.stderr)
        for key in FALSE_AUTHORITY:
            print(f"{key}=false", file=sys.stderr)
        raise SystemExit(1)
